"use strict";exports.id=3064,exports.ids=[3064],exports.modules={53064:(a,b,c)=>{c.d(b,{l:()=>d});let d=[{moduleNumber:1,moduleSlug:"module-1",title:"Getting Started with PowerPoint",emoji:"\uD83C\uDFA8",description:"Learn the PowerPoint interface, create presentations, save files, and understand how slides work.",lessons:[{slug:"getting-started-with-powerpoint",title:"Getting Started with PowerPoint",description:"Learn your way around the PowerPoint interface including the Ribbon, Quick Access Toolbar, slide views, zoom controls, and Backstage view.",objectives:["Identify the Ribbon, slide pane, thumbnail pane, and notes pane","Switch between Normal, Slide Sorter, Reading, and Presenter views","Explain what a placeholder is and why it matters","Navigate a deck efficiently while building it"],duration:"12 min",videoUrl:"https://www.youtube.com/embed/k6pg4nZS6fA",practiceFiles:[],sections:[{heading:"PowerPoint is a visual aid, not the presentation",blocks:[{type:"scenario",role:"You prepare the monthly all-staff briefing at Lakeside Medical Associates.",text:"Your first deck has fourteen slides carrying every word you plan to say. During the meeting the room reads ahead, stops listening, and you end up reading your own slides aloud to people who finished them a minute ago.",task:"Learn the tool, and learn what belongs on a slide versus what belongs in your mouth."},{type:"paragraph",text:"The most useful principle in this entire course is that the audience cannot read and listen at the same time. Text-heavy slides force a choice, and the audience reliably chooses reading — which makes the presenter redundant. Slides should carry the few things that genuinely benefit from being seen: an image, a number, a chart, a short phrase that anchors what you are saying."},{type:"paragraph",text:"Everything else goes in the notes pane, which only you see in Presenter View. This is what the notes pane is actually for, and using it properly is the difference between a deck that supports you and a deck that replaces you."},{type:"key-terms",terms:[{term:"Placeholder",definition:"A pre-positioned content box defined by the slide layout. Typing into placeholders rather than free text boxes is what keeps a deck consistent."},{term:"Layout",definition:"A named arrangement of placeholders — Title Slide, Title and Content, Two Content. Chosen per slide."},{term:"Slide Master",definition:"The design definition behind every layout. Change it once and the whole deck follows."},{term:"Theme",definition:"The coordinated colors, fonts, and effects applied across the presentation."},{term:"Notes pane",definition:"Text attached to a slide that the audience never sees. Visible to you in Presenter View."}]},{type:"table",caption:"The views and when to use each",columns:["View","Shows","Use it to"],rows:[["Normal","One slide plus thumbnails and notes","Build and edit slides"],["Outline","Text only, as a hierarchy","Draft and reorder the argument before designing anything"],["Slide Sorter","All slides as thumbnails","Reorder, delete, and check visual consistency"],["Reading","Full screen in a window","Review the flow without leaving your desktop"],["Presenter","Notes, timer, and next slide","Actually present"]]},{type:"tip",text:"Build the deck in Outline View first. It shows only the text hierarchy, so you are forced to work on the argument before you can be distracted by design. A deck whose outline does not make sense will not be rescued by a theme."}]},{heading:"PowerPoint Start Screen",blocks:[{type:"paragraph",text:"When you open PowerPoint, the Start Screen appears. From here you can create a new presentation, choose from templates, or open recent files."},{type:"paragraph",text:"Select Blank Presentation to open the PowerPoint editing environment and begin building your slides."},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_interface.png",alt:"PowerPoint interface overview"}]},{heading:"Understanding the PowerPoint Interface",blocks:[{type:"paragraph",text:"Once a presentation opens, you will see the PowerPoint interface. The main workspace includes the Ribbon, slide navigation pane, slide editing area, and status bar."},{type:"paragraph",text:"The slide pane is where you build your presentation, while the navigation pane on the left allows you to organize and switch between slides."}]},{heading:"The Ribbon",blocks:[{type:"paragraph",text:"The Ribbon contains the commands you use to create and edit presentations. It is organized into tabs such as Home, Insert, Design, Transitions, Animations, Slide Show, Review, and View."},{type:"paragraph",text:"Each tab contains groups of related commands. For example, the Font group contains tools for formatting text."},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_ribbon.png",alt:"PowerPoint ribbon tabs"},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_small_arrow.png",alt:"Ribbon dialog launcher"}]},{heading:"Showing and Hiding the Ribbon",blocks:[{type:"paragraph",text:"You can control how much of the Ribbon is visible using the Ribbon Display Options in the top-right corner of PowerPoint."},{type:"paragraph",text:"Options include Auto-hide Ribbon, Show Tabs, and Show Tabs and Commands."},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_ribbon_dropdown.png",alt:"Ribbon display options"}]},{heading:"Quick Access Toolbar",blocks:[{type:"paragraph",text:"The Quick Access Toolbar is located above the Ribbon and provides quick access to commonly used commands such as Save, Undo, Redo, and Start From Beginning."},{type:"paragraph",text:"You can customize the Quick Access Toolbar by clicking the drop-down arrow and selecting additional commands."},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_quick_access.png",alt:"Quick access toolbar"},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_quick_print_setup.png",alt:"Quick access customization menu"},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_quick_print.png",alt:"Quick print added to quick access toolbar"}]},{heading:"Using the Tell Me Box",blocks:[{type:"paragraph",text:"The Tell Me box works like a search tool inside PowerPoint. You can type the name of a command or feature and PowerPoint will help you find it instantly."},{type:"paragraph",text:"This is especially useful when you are learning PowerPoint and do not know where certain tools are located."},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_shapes.png",alt:"Using the Tell Me box to search commands"}]},{heading:"Ruler, Guides, and Gridlines",blocks:[{type:"paragraph",text:"PowerPoint includes layout tools to help align objects on your slides. These include the ruler, guides, and gridlines."},{type:"paragraph",text:"You can enable these tools from the View tab in the Ribbon under the Show group."},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_view_tools.png",alt:"View tab ruler gridlines guides"}]},{heading:"Slide Views",blocks:[{type:"paragraph",text:"PowerPoint includes multiple slide views that change how your presentation is displayed. These include Normal view, Slide Sorter view, Reading view, and Slide Show view."},{type:"paragraph",text:"You can switch between these views using the view buttons in the bottom-right corner of the PowerPoint window."},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_slide_view_command.png",alt:"Slide view buttons"}]},{heading:"Zoom Controls",blocks:[{type:"paragraph",text:"The Zoom slider located in the bottom-right corner allows you to zoom in or out of your slide."},{type:"paragraph",text:"This helps you adjust your workspace when working on detailed slide content."},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_zoom_command.png",alt:"Zoom slider control"}]},{heading:"Backstage View",blocks:[{type:"paragraph",text:"Backstage view is accessed by clicking the File tab. It contains options for saving, printing, sharing, exporting, and managing your presentation."},{type:"paragraph",text:"This area also shows presentation information such as file size, slide count, and document properties."},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_file_tab.png",alt:"File tab backstage button"},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_backstage_view.png",alt:"PowerPoint backstage view"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Where are most PowerPoint commands organized?",options:["The status bar at the bottom of the screen","The Quick Access Toolbar above the slide","The Ribbon at the top of the screen","The slide navigation pane on the left"],correctIndex:2,explanation:"The Ribbon organizes PowerPoint's commands into task-based tabs — Home for text and slides, Insert for objects, Design for themes, Transitions and Animations for motion.",optionRationales:["The status bar reports the slide number, view controls, and zoom. It displays information rather than housing commands.","The Quick Access Toolbar holds a few shortcuts you choose yourself. It is a convenience layer over the Ribbon.","Correct. The Ribbon organizes commands into task-based tabs.","The navigation pane shows slide thumbnails for reordering and selecting. It manages slides rather than holding commands."]}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Open PowerPoint and create a blank presentation.","Change the Ribbon Display Options to Show Tabs.","Add New, Quick Print, and Spelling to the Quick Access Toolbar.","Use the Tell Me box to search for Shapes.","Insert a shape onto the slide.","Enable the Ruler from the View tab.","Zoom the presentation to 120%.","Return the Ribbon display to Show Tabs and Commands."]},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_final_result.png",alt:"PowerPoint backstage view"}]},{slug:"understanding-onedrive-for-powerpoint",title:"Understanding OneDrive for PowerPoint",description:"Learn how to sign in to PowerPoint, connect your Microsoft account, and use OneDrive to save and access presentations from anywhere.",objectives:["Save a presentation to OneDrive and open it elsewhere","Explain why cloud storage matters for a deck you will present","Share a presentation with appropriate permissions","Plan for presenting when the network is unavailable"],duration:"8 min",sections:[{heading:"The file has to be there when you stand up to present",blocks:[{type:"scenario",role:"You present at the quarterly staff meeting at Lakeside Medical Associates.",text:"Your deck is on your desk computer. The meeting is in the conference room, on a different machine, and the guest network is refusing connections. You have four minutes and thirty people waiting.",task:"Store the deck so it is reachable from anywhere, and carry a fallback for when the network is not."},{type:"paragraph",text:"OneDrive makes the presentation reachable from any machine you can sign in on, which solves the ordinary case well. It also gives you version history, so an accidental deletion of six slides is recoverable rather than final."},{type:"callout",variant:"warning",text:"Never let the cloud be your only copy of something you must present. Networks fail in conference rooms specifically. Before any presentation that matters, put a copy on a USB drive or the local desktop, and export a PDF as a last-resort fallback — a PDF will open on literally any machine, and a static deck is far better than no deck."},{type:"tip",text:"Embedded video and audio are the usual cause of a deck that works on your machine and fails on the presentation machine. File > Info > Optimize Media Compatibility embeds and converts media so it travels with the file. Always run it before presenting from a different computer."}]},{heading:"What is OneDrive?",blocks:[{type:"paragraph",text:"OneDrive is Microsoft's cloud storage service. It allows you to store presentations and other files online so you can access them from any computer, tablet, or smartphone with an internet connection."},{type:"paragraph",text:"Using OneDrive makes it easy to save, edit, and share PowerPoint presentations while keeping your files protected and backed up."}]},{heading:"Signing in to PowerPoint",blocks:[{type:"paragraph",text:"To use OneDrive features, you need to sign in with a Microsoft account. Click the Sign in button in the upper-right corner of the PowerPoint window."},{type:"paragraph",text:"After signing in, PowerPoint connects to your OneDrive storage so you can save presentations online and access them across devices."},{type:"image",src:"/images/powerpoint/module-1/onedrive/powerpoint_sign_in.png",alt:"PowerPoint sign in button"}]},{heading:"Benefits of Using OneDrive",blocks:[{type:"paragraph",text:"Once you sign in, OneDrive provides several powerful advantages for managing presentations."},{type:"list",ordered:!1,items:["Access files anywhere from any device connected to the internet.","Back up presentations safely in the cloud.","Share files with coworkers or classmates.","Collaborate on presentations with multiple people at the same time."]}]},{heading:"Saving Presentations to OneDrive",blocks:[{type:"paragraph",text:"When you save a presentation, you can choose OneDrive as the storage location. This allows the file to sync automatically with your Microsoft account."},{type:"paragraph",text:"Click File → Save As and choose OneDrive instead of saving directly to your computer."},{type:"image",src:"/images/powerpoint/module-1/onedrive/powerpoint_onedrive.png",alt:"Saving a PowerPoint presentation to OneDrive"}]},{heading:"Opening Files from OneDrive",blocks:[{type:"paragraph",text:"Once your presentations are stored in OneDrive, you can open them from any device. Simply sign into PowerPoint and choose OneDrive when opening a file."},{type:"paragraph",text:"You can still save files locally to your computer, but OneDrive provides additional convenience and protection."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is the benefit of saving a presentation to OneDrive?",options:["It automatically adds transitions to every slide","It compresses the file size to save disk space","You can access and share it from any device","It protects the presentation from being edited by anyone"],correctIndex:2,explanation:"OneDrive stores the presentation on Microsoft's servers so you can open it from any device you sign in on, and share it by link. It also provides version history and co-authoring.",optionRationales:["Storage location has no effect on transitions, which are applied from the Transitions tab.","OneDrive does not compress files. Reducing file size is done with Compress Pictures and media optimization.","Correct. The presentation is reachable from any device you sign in on, and can be shared by link.","Sharing permissions are something you set deliberately. Saving to OneDrive does not lock a file against editing."]}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Sign in to PowerPoint using a Microsoft account.","Open the File menu and select Save As.","Choose OneDrive as the save location.","Save a presentation to OneDrive.","Locate your saved presentation inside your OneDrive account."]}]},{slug:"creating-and-opening-presentations",title:"Creating and Opening Presentations",description:"Learn how to create new PowerPoint presentations, use templates, open existing files, pin presentations, and understand Compatibility Mode.",objectives:["Create presentations from blank files and from templates","Open and pin recent presentations","Evaluate whether a template suits your content","Explain what a template supplies beyond appearance"],duration:"12 min",videoUrl:"https://www.youtube.com/embed/OX3vRazm4fw",practiceFiles:[{name:"Creating & Opening Presentations Practice File",url:"/practice/powerpoint/module-1/creating-opening/Powerpoint_CreatingOpening_Practice.ppt"}],sections:[{heading:"A template is a set of decisions already made",blocks:[{type:"scenario",role:"You produce recurring briefings at Lakeside Medical Associates.",text:"Every month you rebuild the same deck: the same title arrangement, the same colors, the same closing slide. Twenty minutes each time, spent re-making decisions you already made in January — and the decks still do not quite match each other.",task:"Build the practice's design once as a template, then start every deck from it."},{type:"paragraph",text:"A template supplies the theme, the slide layouts, and often placeholder content — all the structural decisions. Starting from one means starting with the design settled, so your attention goes to the argument rather than to fonts."},{type:"callout",variant:"info",text:"Judge a template by its layouts, not its title slide. Many attractive templates supply three usable layouts and nothing else, so the moment you need a comparison slide or a full-width chart you are improvising with text boxes — and the consistency you chose the template for is gone. Open the Slide Master and look at what layouts exist before committing to a template."}]},{heading:"Creating a New Presentation",blocks:[{type:"paragraph",text:"PowerPoint files are called presentations. When starting a new project, you will usually begin with a blank presentation."},{type:"paragraph",text:"To create a new presentation, click the File tab to open Backstage view, then select New and choose Blank Presentation."},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_file_tab.png",alt:"File tab in PowerPoint"},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_backstage.png",alt:"New presentation screen"}]},{heading:"Using Templates",blocks:[{type:"paragraph",text:"Templates are predesigned presentations that allow you to quickly start a slideshow with built-in formatting, layouts, and color themes."},{type:"paragraph",text:"From the New screen in Backstage view, you can search for templates using the search bar or choose from suggested templates."},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_new_template.png",alt:"PowerPoint template selection screen"},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_review_template.png",alt:"Template preview screen"},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_new_template_create.png",alt:"Create presentation from template"}]},{heading:"Opening Existing Presentations",blocks:[{type:"paragraph",text:"You can open presentations that have already been saved on your computer or OneDrive."},{type:"paragraph",text:"Click File → Open to view recent files or browse your computer to locate a presentation."},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_existing.png",alt:"Open presentations menu"},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_existing_browse.png",alt:"Browse option in PowerPoint"},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_doc_folder.png",alt:"Open dialog box"}]},{heading:"Pinning Presentations",blocks:[{type:"paragraph",text:"If you frequently use the same presentation, you can pin it to the Recent list so it stays easy to access."},{type:"paragraph",text:"Hover your mouse over a recent file and click the pushpin icon to pin the presentation."},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_pin_present.png",alt:"Pinned presentation"},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_unpin_present.png",alt:"Unpin presentation"}]},{heading:"Understanding Compatibility Mode",blocks:[{type:"paragraph",text:"If you open a presentation created in an older version of PowerPoint, it may open in Compatibility Mode."},{type:"paragraph",text:"Compatibility Mode disables certain newer features so the presentation remains compatible with older versions of PowerPoint."},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_compatibility.png",alt:"PowerPoint compatibility mode"}]},{heading:"Converting a Presentation",blocks:[{type:"paragraph",text:"To access newer PowerPoint features, you can convert a presentation from Compatibility Mode to the latest file format."},{type:"paragraph",text:"Open Backstage view, click Convert, and save the presentation as the newer format."},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_convert_compat.png",alt:"Convert presentation command"},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_save_as.png",alt:"Save converted presentation"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is a PowerPoint template?",options:["A blank slide with no formatting or placeholders","A slideshow that plays automatically without editing","A pre-designed presentation you can customize as a starting point","A file saved in read-only mode"],correctIndex:2,explanation:"A template is a pre-designed presentation supplying the theme, slide layouts, and often sample content, used as a starting point. Opening one creates a new presentation and leaves the template intact.",optionRationales:["A blank slide with no formatting is what you get from a blank presentation, which is the opposite of a template.","That describes a self-running or kiosk presentation, configured under Set Up Slide Show.","Correct. A template is a pre-designed presentation you customize as a starting point.","Read-only status is a file property, unrelated to what a template is."]}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Create a new blank PowerPoint presentation.","Search for a template and create a presentation from it.","Open an existing presentation from your computer.","Pin a presentation in the Recent list.","Open a presentation in Compatibility Mode.","Convert the presentation to the latest PowerPoint format."]}]},{slug:"saving-presentations",title:"Saving Presentations",description:"Learn how to save PowerPoint presentations, change file types, export presentations, and recover unsaved work.",objectives:["Save in the format that matches how the deck will be used","Export to PDF and to video","Explain what each export format preserves and loses","Prepare a deck for a machine that may not have PowerPoint"],duration:"10 min",videoUrl:"https://www.youtube.com/embed/iwecUGKmiyw",practiceFiles:[{name:"PowerPoint Saving Practice File",url:"/practice/powerpoint/module-1/saving/Powerpoint_Saving_Practice.pptx"}],sections:[{heading:"Choose the format for how it will be opened",blocks:[{type:"scenario",role:"You distribute the orientation deck at Lakeside Medical Associates.",text:"You email the .pptx to twelve new hires. Three cannot open it, two see substituted fonts that break every slide layout, and one edits it and forwards their version to the rest.",task:"Match the distribution format to what recipients actually need to do with it."},{type:"table",caption:"Export formats",columns:["Format","Preserves","Use for"],rows:[[".pptx","Everything, fully editable","Colleagues who must edit it"],["PDF","Layout and fonts; loses animation and video","Distributing to read — opens anywhere"],["MP4 video","Animation, timing, and narration","Self-paced training people watch without you"],["PowerPoint Show (.ppsx)","Everything; opens straight into the slide show","Handing to someone who should present, not edit"],["Images (PNG/JPG)","One picture per slide","Dropping a slide into another document"]]},{type:"callout",variant:"warning",text:"Fonts are the most common cause of a deck that looks wrong on someone else's machine. If a font is not installed there, PowerPoint substitutes another and your layout reflows — text overflows placeholders and line breaks land in the wrong places. File > Options > Save > Embed fonts in the file prevents it, and PDF sidesteps the problem entirely."}]},{heading:"Saving a Presentation",blocks:[{type:"paragraph",text:"Where you save decides what you can do later. A file on the computer's own drive is reachable only from that machine, and is gone if the drive fails. A file in OneDrive follows you to any device you sign in on, keeps a version history you can roll back, and is the only kind of file AutoSave and co-authoring work on. For a presentation you will build over several sessions, or deliver from a room's machine rather than your own, save to OneDrive from the start."},{type:"paragraph",text:"Click the File tab to open Backstage view and access the Save and Save As commands."},{type:"image",src:"/images/powerpoint/module-1/saving/saving_file_tab.png",alt:"PowerPoint file tab"}]},{heading:"Using the Save Command",blocks:[{type:"paragraph",text:"Save writes over the file you opened. That is what you want when you are updating your own work — and it is exactly the wrong thing when you opened an existing deck to build a new one from it. Whenever a file is your starting point rather than your subject, use Save As first, before you change anything."},{type:"paragraph",text:"The first Save always opens Save As, because PowerPoint has nowhere to write to yet. After that it saves silently, which is why the Save-As-first habit matters: once the file has a name, a reflexive Ctrl+S goes straight into it with no prompt."},{type:"image",src:"/images/powerpoint/module-1/saving/saving_command.png",alt:"Save command in PowerPoint"}]},{heading:"Using Save As",blocks:[{type:"paragraph",text:"Save As creates a new file and leaves the original untouched. Do it before you edit, not after. Renaming a file you have already changed does not restore the original, and the deck you overwrote may have been the one someone else needed."},{type:"paragraph",text:"From the Save As screen you can choose to store the presentation on OneDrive, your computer, or another location."},{type:"image",src:"/images/powerpoint/module-1/saving/saving_save_as.png",alt:"Save As screen"}]},{heading:"Entering a File Name",blocks:[{type:"paragraph",text:'Name the file so a stranger could identify it in a folder list: subject, audience, and date in year-month order — "2026-10-14 Staff Orientation - New Hires.pptx". Year-first dates sort chronologically automatically. "Presentation1 final v2 FINAL.pptx" is the file nobody can find in March.'},{type:"image",src:"/images/powerpoint/module-1/saving/saving_filename_input.png",alt:"File name input field"},{type:"image",src:"/images/powerpoint/module-1/saving/saving_filename_input_change.png",alt:"Changing file name"}]},{heading:"Choosing a File Type",blocks:[{type:"paragraph",text:"Match the format to what the recipient needs to do. A .pptx is editable — right for a colleague who will revise it, and wrong for a deck you do not want altered. A PowerPoint Show (.ppsx) opens straight into the slide show, which suits handing a deck to someone who will present but not edit. A PDF opens anywhere, locks the layout, and drops animation and video."},{type:"image",src:"/images/powerpoint/module-1/saving/saving_file_type_save_as.png",alt:"File type dropdown"}]},{heading:"Exporting Presentations",blocks:[{type:"paragraph",text:"Export produces a copy in another format and leaves your .pptx alone. Video is the one worth knowing: it preserves animation, timing, and narration, so a deck people watch without you keeps working. It also takes minutes to render on a long deck, so do it before the day you need it."},{type:"image",src:"/images/powerpoint/module-1/saving/saving_change_file_type.png",alt:"Change file type export screen"},{type:"image",src:"/images/powerpoint/module-1/saving/saving_change_to_pdf.png",alt:"Export presentation as PDF"}]},{heading:"Sharing Presentations",blocks:[{type:"paragraph",text:"Sharing requires the file to be in OneDrive or SharePoint — that is what a share link points at. If the Share button offers to upload first, it is telling you the file is currently local and cannot be shared as a link."},{type:"paragraph",text:'Choose the permission deliberately. "Can view" is right for most recipients; "can edit" is for genuine co-authors. And permissions outlive the task — a link shared for one afternoon still works next year unless someone revokes it. Set an expiry on anything sensitive.'},{type:"image",src:"/images/powerpoint/module-1/saving/saving_share.png",alt:"Share presentation window"},{type:"image",src:"/images/powerpoint/module-1/saving/saving_share_input.jpeg",alt:"Entering email to share presentation"}]},{heading:"Recovering Unsaved Presentations",blocks:[{type:"paragraph",text:"AutoRecover is a safety net, not a save. It keeps periodic snapshots so a crash costs you minutes rather than hours, and it is not a substitute for saving. Check the interval under File > Options > Save and set it to match how much work you could bear to redo."},{type:"paragraph",text:"Go to File → Info → Manage Presentation and choose Recover Unsaved Presentations."},{type:"image",src:"/images/powerpoint/module-1/saving/saving_recover_unsaved.png",alt:"Recover unsaved presentations"}]},{heading:"Document Recovery",blocks:[{type:"paragraph",text:"Open the recovered version and check it before you close the pane — once you dismiss it, the recovery files are cleared. Compare it against the last version you saved, since the recovered copy may be newer or older depending on when the snapshot was taken."},{type:"image",src:"/images/powerpoint/module-1/saving/saving_doc_recovery.png",alt:"Document recovery pane"}]},{heading:"PowerPoint Save Options",blocks:[{type:"paragraph",text:"Two settings are worth changing once. Set the AutoRecover interval to five minutes rather than the default ten. And set the default save location to OneDrive, so the safe choice is the one that happens when you are not thinking about it."},{type:"image",src:"/images/powerpoint/module-1/saving/saving_options.png",alt:"PowerPoint save options"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What should you do if you want to share a presentation that others cannot edit?",options:["Save it as a .pptx file and email it","Use the Share button to invite collaborators","Export it as a PDF","Mark it as Final in the Info pane"],correctIndex:2,explanation:"PDF preserves layout and fonts exactly and is not casually editable, so it is right for distributing a deck people should read rather than change. It does lose animation, transitions, and embedded video.",optionRationales:["A .pptx is fully editable, which is precisely what you are trying to avoid — and it also risks font substitution on the recipient's machine.","Sharing with collaborators grants editing access, which is the opposite of the goal.","Correct. PDF locks the layout and fonts and is not casually editable.","Mark as Final is only an advisory flag. It shows a notice and is dismissed with one click, so it prevents nothing."]}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Open PowerPoint and create a new blank presentation.","Save the presentation to your computer using Save As.","Rename the presentation.","Export the presentation as a PDF.","Open the File tab and locate the Recover Unsaved Presentations option."]}]},{slug:"slide-basics",title:"Slide Basics",description:"Learn how to create slides, choose layouts, work with placeholders, duplicate and reorder slides, and apply design changes in PowerPoint.",objectives:["Add, duplicate, delete, and reorder slides","Choose a layout that matches the slide's content","Explain why placeholders beat free-floating text boxes","Use the outline to structure a deck before designing it"],duration:"14 min",videoUrl:"https://www.youtube.com/embed/TZfcVbKJs1E",practiceFiles:[{name:"PowerPoint Slide Basics Practice File",url:"/practice/powerpoint/module-1/slide-basics/Powerpoint_SlideBasics_Practice.pptx"}],sections:[{heading:"Layouts are what keep a deck from drifting",blocks:[{type:"scenario",role:"You build a twenty-slide orientation deck at Lakeside Medical Associates.",text:"You add text boxes wherever you need them rather than using layouts. Your titles land at slightly different heights on almost every slide. Watching the deck, the title jitters up and down from slide to slide, and the whole thing feels amateurish for reasons nobody can name.",task:"Use layouts and placeholders so alignment is structural rather than something you re-achieve each time."},{type:"paragraph",text:"A layout is a set of placeholders positioned by the Slide Master. Type into placeholders and every title lands in exactly the same place on every slide, with the same font and size. That invisible consistency is most of what separates a professional deck from a homemade one."},{type:"paragraph",text:"Free text boxes place themselves wherever you drop them, which is why title jitter happens. They have a legitimate role — a caption over an image, an annotation on a diagram — but they should never be doing a placeholder's job."},{type:"worked-example",title:"Building a slide that stays consistent with the rest of the deck",task:"Add a slide comparing two intake processes, without breaking the deck's alignment.",steps:[{move:"Home > New Slide, and pick the Two Content layout rather than accepting the default.",why:"The layout is chosen for the content, not the other way round. Two Content gives two side-by-side placeholders already aligned to the master, so the comparison structure is built in before you type anything."},{move:"Click into each placeholder and type.",why:"Placeholder text inherits the master's font, size, and position automatically, and it appears in the outline. Text in a free box does neither, which is also why it will not appear if anyone builds a summary from the outline."},{move:"If the text does not fit, cut the text rather than shrinking the font.",why:"PowerPoint offers to autofit by reducing the size, which is how a deck ends up with eight different body sizes. Overflow is a signal that the slide is carrying too much — move the detail to the notes, which is where it belonged."},{move:"Use Outline View to check the slide's place in the argument.",why:"The outline shows the deck as structure, stripped of design. If a slide's title does not make sense in that list, the problem is with the content rather than the layout."}],result:"A comparison slide that matches every other slide's alignment and typography exactly.",takeaway:"Pick the layout that fits the content, type into placeholders, and treat overflow as a content problem rather than a font-size problem."}]},{heading:"Understanding Slides",blocks:[{type:"paragraph",text:"PowerPoint presentations are built one slide at a time. Each slide acts like a page in your presentation, and together the slides tell your full story."},{type:"paragraph",text:"Most slides begin with placeholders. Placeholders are built-in boxes that make it easy to add titles, text, pictures, charts, tables, and other content without having to build the layout yourself."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_slide_placeholders.png",alt:"PowerPoint slide with placeholders"},{type:"paragraph",text:"Using placeholders helps keep slides organized and consistent. Instead of dragging random objects around the screen, PowerPoint gives you a structured starting point."}]},{heading:"Using the Slide Navigation Pane",blocks:[{type:"paragraph",text:"The Slide Navigation Pane appears on the left side of the PowerPoint window. It displays thumbnails of every slide in the presentation."},{type:"paragraph",text:"This pane allows you to jump between slides quickly, see the order of your presentation, and make changes to slide arrangement without leaving the main editing view."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_nav_pane.jpeg",alt:"PowerPoint slide navigation pane"},{type:"paragraph",text:"When a presentation begins to grow, the Navigation Pane becomes one of the most important tools for staying organized."}]},{heading:"Adding a New Slide",blocks:[{type:"paragraph",text:"To continue building a presentation, you will usually need to insert additional slides. PowerPoint makes this easy with the New Slide command on the Home tab."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_new_slide.png",alt:"New Slide command on Home tab"},{type:"paragraph",text:"Clicking the top half of the New Slide button inserts a new slide immediately. This is the fastest way to keep moving when you are building a presentation from scratch."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_quick_slide_add.png",alt:"Quick new slide insertion"},{type:"paragraph",text:"New slides usually appear directly below the currently selected slide in the Navigation Pane."}]},{heading:"Choosing the Right Slide Layout",blocks:[{type:"paragraph",text:"Not every slide should look the same. Some slides only need a title, while others may need text, pictures, or two side-by-side content areas."},{type:"paragraph",text:"That is where slide layouts come in. Layouts control how placeholders are arranged on the slide."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_choose_slide_layout.png",alt:"Choosing a slide layout"},{type:"paragraph",text:"One of the most common layouts is Title and Content. It gives you a title placeholder at the top and one large content area below."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_title_and_content.png",alt:"Title and Content layout example"},{type:"paragraph",text:"Choosing the correct layout early makes your slides easier to build and usually saves you from unnecessary resizing later."}]},{heading:"Changing the Layout of an Existing Slide",blocks:[{type:"paragraph",text:"Sometimes you create a slide and later realize it needs a different layout. Thankfully, you do not need to start over."},{type:"paragraph",text:"PowerPoint lets you change the layout of an existing slide using the Layout command on the Home tab."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_change_layout.png",alt:"Changing slide layout from Home tab"},{type:"paragraph",text:"For example, you may want to switch to a Blank slide if you want full control over where objects appear."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_blank_slide.png",alt:"Blank slide layout option"},{type:"paragraph",text:"Changing layouts is a clean way to reshape a slide without deleting it and rebuilding everything from scratch."}]},{heading:"Adding a Text Box",blocks:[{type:"paragraph",text:"Placeholders are useful, but sometimes you need more freedom. A text box allows you to place text exactly where you want it on the slide."},{type:"paragraph",text:"To insert one, go to the Insert tab and click Text Box."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_add_text_box.png",alt:"Text Box command on Insert tab"},{type:"paragraph",text:"After selecting the command, click and drag on the slide to draw the text box area."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_text_box_create.png",alt:"Drawing a text box on a slide"},{type:"paragraph",text:"Once the text box appears, you can type directly inside it and format it like any other text in PowerPoint."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_text_box_appear.png",alt:"Text box added to slide"}]},{heading:"Moving and Resizing Placeholders",blocks:[{type:"paragraph",text:"You are not locked into PowerPoint’s default object positions. Placeholders and text boxes can be moved and resized whenever needed."},{type:"paragraph",text:"To move an object, click its border and drag it to a new location."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_move_placeholder.png",alt:"Moving a placeholder on a slide"},{type:"paragraph",text:"To resize an object, drag one of the sizing handles on the corners or sides. Corner handles adjust both height and width, while side handles adjust only one dimension."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_resize_placeholder.png",alt:"Resizing a placeholder"},{type:"paragraph",text:"These adjustments help you improve spacing, balance your slide, and make room for other content."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_adjust_placeholder.png",alt:"Adjusted placeholder size and position"}]},{heading:"Duplicating Slides",blocks:[{type:"paragraph",text:"If you have a slide with a layout you want to reuse, duplicating it is much faster than rebuilding the entire slide from scratch."},{type:"paragraph",text:"To duplicate a slide, right-click the slide thumbnail in the Navigation Pane and choose Duplicate Slide."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_duplicate_slide.jpeg",alt:"Duplicate Slide command"},{type:"paragraph",text:"You can also copy and paste slides. This is useful when moving content between presentations or when you want even more control over placement."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_copy_slide.jpeg",alt:"Copying a slide thumbnail"},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_paste_appear.jpeg",alt:"Pasted slide appears in navigation pane"}]},{heading:"Reordering Slides",blocks:[{type:"paragraph",text:"As your presentation grows, you may decide that some slides belong earlier or later in the sequence."},{type:"paragraph",text:"To reorder slides, click and drag a slide thumbnail in the Navigation Pane. A horizontal insertion line shows where the slide will be placed."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_move_slide.jpeg",alt:"Dragging slide to new position"},{type:"paragraph",text:"Reordering slides is one of the easiest ways to improve the flow of your presentation without changing the content itself."}]},{heading:"Applying a Theme",blocks:[{type:"paragraph",text:"Themes give your presentation a consistent visual style by applying coordinated colors, fonts, and background styles across all slides."},{type:"paragraph",text:"To apply a theme, go to the Design tab and select one of the available theme thumbnails."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_select_theme.png",alt:"Selecting a theme from the Design tab"},{type:"paragraph",text:"Once applied, the theme updates the appearance of your presentation instantly."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_applied_theme.jpeg",alt:"Theme applied to presentation"}]},{heading:"Formatting the Background",blocks:[{type:"paragraph",text:"If you want to customize the appearance of a slide even more, you can modify the slide background."},{type:"paragraph",text:"Use the Format Background command to choose a solid fill, gradient, texture, or picture background."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_format_background.png",alt:"Format Background command"},{type:"paragraph",text:"You can then select the background fill style and choose a color or other formatting option."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_background_fill.png",alt:"Background fill options"},{type:"paragraph",text:"If you want the same background on every slide, click Apply to All."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_format_apply_to_all.jpeg",alt:"Apply background formatting to all slides"}]},{heading:"Changing Slide Size",blocks:[{type:"paragraph",text:"PowerPoint allows you to choose between Standard (4:3) and Widescreen (16:9) slide sizes."},{type:"paragraph",text:"Widescreen is the more modern format and is commonly used for classroom projectors, TVs, and online presentations."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_slide_size.png",alt:"Slide size options in PowerPoint"}]},{heading:"Completed Presentation Example",blocks:[{type:"paragraph",text:"After adding slides, choosing layouts, inserting text, duplicating content, and applying theme changes, your presentation will start to look polished and organized."},{type:"paragraph",text:"The completed practice file gives a good example of how a simple presentation can become much more visually effective once these slide basics are applied."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_final_result.png",alt:"Completed PowerPoint presentation example"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is a layout in PowerPoint?",options:["A theme that changes the fonts and colors of a presentation","A color palette used across all slides","A pre-arranged set of placeholders for content on a slide","A saved view that shows all slides at once"],correctIndex:2,explanation:"A layout is a pre-arranged set of placeholders defining where content sits on a slide. Because placeholder positions come from the Slide Master, using layouts keeps every slide aligned consistently.",optionRationales:["That describes a theme, which sets colors and fonts across the whole presentation. A layout arranges content areas.","A color palette is part of the theme. Layouts govern arrangement, not color.","Correct. A layout is a pre-arranged set of placeholders for a slide's content.","That describes Slide Sorter view. A layout is a property of a slide rather than a way of viewing the deck."]}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Insert a new slide into the presentation.","Change the layout of one slide.","Add a text box to a blank slide.","Move or resize a placeholder.","Duplicate one of the existing slides.","Reorder a slide in the Navigation Pane.","Apply a theme to the presentation.","Change the background formatting and apply it to all slides."]},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_final_result.png",alt:"Final result for slide basics challenge"}]}],level:"Beginner",estimatedMinutes:43},{moduleNumber:2,moduleSlug:"module-2",title:"Working with Text",emoji:"\uD83D\uDCDD",description:"Learn how to edit slide content, format text, organize slides, and work with lists in PowerPoint.",lessons:[{slug:"powerpoint-text-basics",title:"PowerPoint Text Basics",description:"Learn how to select text, cut, copy, paste, drag text, and format text using the tools on the Home tab.",objectives:["Add and edit text in placeholders and text boxes","Select text efficiently with keyboard shortcuts","Apply formatting that stays consistent with the deck's theme","Recognize when a slide is carrying too much text"],duration:"9 min",videoUrl:"https://www.youtube.com/embed/F9RL0Lk5cmw",practiceFiles:[{name:"PowerPoint Text Basics Practice File",url:"/practice/powerpoint/module-2/text-basics/Powerpoint_TextBasics_Practice.pptx"}],sections:[{heading:"The word limit is the design",blocks:[{type:"scenario",role:"You present quarterly results at Lakeside Medical Associates.",text:"Your key slide holds ninety words in five bullets. You watch the room read it, and by the time you reach your second sentence they have finished and are checking their phones. The information was delivered. The point was not.",task:"Reduce each slide to what genuinely benefits from being seen, and move the rest to the notes."},{type:"paragraph",text:"A commonly cited guide is roughly six words per line and six lines per slide. The number matters less than the principle behind it: a slide is glanced at, not read. Anything requiring sustained reading belongs in a handout or in the notes pane."},{type:"paragraph",text:"Font size is the other half. Twenty-four point is a sensible floor for body text — not for aesthetics, but because it is what remains legible from the back of a room. If your content only fits at eighteen point, the slide has too much on it, and shrinking the type just makes it unreadable as well as crowded."},{type:"table",caption:"Where content belongs",columns:["Content","Put it","Because"],rows:[["The single point of the slide","The slide, as a short phrase","It anchors what you are saying"],["Your supporting explanation","The notes pane","You say it; the audience listens rather than reads"],["Detailed figures and tables","A handout","Detail needs reading time a live audience does not have"],["The source of a statistic","A small line on the slide","It establishes credibility without being read aloud"]]}]},{heading:"Selecting Text",blocks:[{type:"paragraph",text:"Before you can edit or move text in PowerPoint, you first need to select it. Selecting text allows you to copy it, delete it, format it, or move it to another location on the slide."},{type:"paragraph",text:"Dragging works, and there are faster ways worth knowing: double-click selects a word, triple-click selects a paragraph, and Ctrl+A selects everything in the placeholder. Precise selection matters because PowerPoint applies formatting to exactly what is highlighted — a stray trailing space picked up in the selection is how one word ends up a different size."},{type:"image",src:"/images/powerpoint/module-2/text-basics/text-basics_select_text.png",alt:"Selecting text in a PowerPoint text box"},{type:"paragraph",text:"Once the text is highlighted, PowerPoint knows that any commands you choose will apply to that selection."}]},{heading:"Copying and Pasting Text",blocks:[{type:"paragraph",text:"Copy leaves the original in place; cut removes it. The keyboard versions are worth using — Ctrl+C, Ctrl+X, Ctrl+V — because they work identically in Word, Excel, and your browser."},{type:"paragraph",text:"First select the text you want to copy. Then click the Copy command in the Clipboard group on the Home tab."},{type:"image",src:"/images/powerpoint/module-2/text-basics/text-basics_copy.png",alt:"Copy command on the PowerPoint ribbon"},{type:"paragraph",text:"Pasting normally brings the source formatting with it, which is why text copied from a web page arrives in the wrong font on a colored background. Ctrl+Shift+V, or Paste Options > Keep Text Only, brings the words and leaves the formatting behind. On a slide, where consistency is most of what looks professional, that is almost always what you want."},{type:"image",src:"/images/powerpoint/module-2/text-basics/text-basics_paste_command.png",alt:"Paste command on the PowerPoint ribbon"},{type:"paragraph",text:"The copied text will appear in the new location while the original text remains unchanged."}]},{heading:"Cutting and Pasting Text",blocks:[{type:"paragraph",text:"If you want to move text instead of copying it, you can use the Cut command. Cutting removes the selected text and places it on the clipboard."},{type:"paragraph",text:"Select the text you want to move, then click the Cut command on the Home tab."},{type:"image",src:"/images/powerpoint/module-2/text-basics/text-basics_cut.png",alt:"Cut command on the PowerPoint ribbon"},{type:"paragraph",text:"Place the insertion point where the text should appear, then click Paste."},{type:"image",src:"/images/powerpoint/module-2/text-basics/text-basics_paste.png",alt:"Pasting text into a new position"},{type:"paragraph",text:"The text will appear in its new location and will be removed from its original position."}]},{heading:"Dragging and Dropping Text",blocks:[{type:"paragraph",text:"Another quick way to move text is by dragging and dropping it. This allows you to move text directly without using the Ribbon commands."},{type:"paragraph",text:"First select the text you want to move. Then click and drag the selected text to a new location within the text box."},{type:"image",src:"/images/powerpoint/module-2/text-basics/text-basics_drag_select_text.png",alt:"Dragging selected text in PowerPoint"},{type:"paragraph",text:"When you release the mouse, the text will move to the new location."},{type:"image",src:"/images/powerpoint/module-2/text-basics/text-basics_dragged_text.png",alt:"Text moved to a new location on the slide"}]},{heading:"Formatting Text",blocks:[{type:"paragraph",text:"Emphasis works by contrast, which makes it a budget. Bold one phrase on a slide and the eye goes there; bold six and you have emphasized nothing. Before formatting anything, decide which single thing the audience should see first."},{type:"paragraph",text:"Prefer the placeholder's own styling to manual formatting wherever you can. Text typed into a layout placeholder inherits size, font, and position from the Slide Master, so it matches every other slide automatically. Formatting applied by hand has to be repeated, and it drifts."},{type:"image",src:"/images/powerpoint/module-2/text-basics/text-basics_ribbon_commands.png",alt:"Font and paragraph commands in the PowerPoint ribbon"},{type:"paragraph",text:"Bold for emphasis, and use it sparingly. Avoid underline entirely on a slide: readers read underlined text as a hyperlink and some will wait for it to do something. Italic is harder to read when projected, so keep italic runs short."}]},{heading:"Completed Slide Example",blocks:[{type:"paragraph",text:"After editing and formatting the text, the slide will appear more organized and easier to read."},{type:"paragraph",text:"The example below shows how the slide should look after rearranging the list and formatting the text."},{type:"image",src:"/images/powerpoint/module-2/text-basics/text-basics_final_result.jpeg",alt:"Completed PowerPoint slide example"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"How do you select all text in a text box in PowerPoint?",options:["Right-click the text box and choose Select All","Click the text box, then press Ctrl + A","Double-click the text box border","Go to Home → Select → Select All Text"],correctIndex:1,explanation:"Clicking the text box places your cursor inside it, and Ctrl+A then selects all the text within that box rather than every object on the slide.",optionRationales:["PowerPoint's right-click menu for a text box has no Select All command.","Correct. Click into the box to place the cursor, then Ctrl+A selects all the text inside it.","Double-clicking the border selects the text box as an object, which lets you format the box rather than edit its text. Useful, but not the same thing.","Home > Select offers Select All for objects on the slide, not for text inside one box."]}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Open the practice presentation.","Select slide 4.","Move the text 'Lower blood pressure' so it appears between 'Companionship' and 'Social opportunities'.","Use either Cut and Paste or Drag and Drop.","Select the list of benefits and apply italics formatting.","Select the title 'Did You Know?' remove the bold formatting and change the font size to 36 pt."]},{type:"image",src:"/images/powerpoint/module-2/text-basics/text-basics_final_result.jpeg",alt:"Final result for the text basics challenge"}]},{slug:"powerpoint-lists",title:"PowerPoint Lists",description:"Learn how to create bulleted and numbered lists to organize information clearly on slides.",objectives:["Create bulleted and numbered lists and change their levels","Choose between bullets and numbers based on whether order matters","Explain why long bulleted lists undermine a presentation","Convert a list into a stronger visual when appropriate"],duration:"8 min",videoUrl:"https://www.youtube.com/embed/hL5XQGFdmDo",practiceFiles:[{name:"Lists Practice File",url:"/practice/powerpoint/module-2/lists/Powerpoint_Lists_Practice.pptx"}],sections:[{heading:"The bullet list is the default, and rarely the best choice",blocks:[{type:"scenario",role:"You explain the referral workflow at Lakeside Medical Associates.",text:"Six bullets describing six sequential steps. The audience sees six equal-looking items and cannot tell that order matters, that step three depends on step two, or where the decision point is. A simple diagram would have shown all three instantly.",task:"Use numbers when sequence matters, and consider whether a list is the right form at all."},{type:"paragraph",text:"Bullets signal a set with no order. Numbers signal sequence. Using bullets for a procedure actively misinforms, because readers take the formatting as meaning — the same rule that applies in Word applies here, and matters more, because a slide gets a glance rather than a careful read."},{type:"paragraph",text:"It is also worth asking whether a list is the right form at all. A sequence is usually clearer as a process diagram, a comparison as a two-column table, and a proportion as a chart. Bullets are the default because they are easy to type, not because they communicate well."},{type:"tip",text:"Tab demotes a bullet to the next level and Shift+Tab promotes it, which works as you type. If you find yourself needing a third or fourth level on a slide, the content has outgrown the format — split it into several slides or move it to a handout."}]},{heading:"Bulleted Lists",blocks:[{type:"paragraph",text:"Bulleted lists are commonly used in PowerPoint to organize information into clear and easy-to-read points."},{type:"paragraph",text:"To add bullets, select the text you want to format and click the Bullets command in the Paragraph group on the Home tab."},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_bullet_command.png",alt:"Bullets command in the PowerPoint ribbon"},{type:"paragraph",text:"You can also click the drop-down arrow next to the Bullets command to choose from different bullet styles."},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_bullets_dropdown.png",alt:"Bullet style dropdown menu"}]},{heading:"Choosing a Bullet Style",blocks:[{type:"paragraph",text:"PowerPoint includes several built-in bullet styles such as circles, squares, arrows, and checkmarks."},{type:"paragraph",text:"Selecting a style immediately updates the appearance of the list."},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_bullet_style.png",alt:"Selecting a bullet style in PowerPoint"}]},{heading:"Customizing Bullets",blocks:[{type:"paragraph",text:"If you want more control over the appearance of your bullets, you can open the Bullets and Numbering dialog box."},{type:"paragraph",text:"From here you can change the bullet style, adjust the size, or select a different color."},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_bullets_and_numbering.png",alt:"Bullets and Numbering dialog box"},{type:"paragraph",text:"You can also click Customize to choose symbols or other bullet characters."},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_symbol_dialog.png",alt:"Symbol dialog used for custom bullets"}]},{heading:"Numbered Lists",blocks:[{type:"paragraph",text:"Numbered lists are useful when presenting steps, instructions, or information that should appear in a specific order."},{type:"paragraph",text:"To apply numbering, select the text and click the Numbering command on the Home tab."},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_numbering_command.png",alt:"Numbering command in PowerPoint"},{type:"paragraph",text:"Click the drop-down arrow next to the Numbering button to choose from different numbering formats."},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_number_options.png",alt:"Numbered list formatting options"}]},{heading:"Continuing Numbering",blocks:[{type:"paragraph",text:"When you create numbered lists across multiple slides or sections, PowerPoint can continue numbering automatically."},{type:"paragraph",text:"You can adjust where numbering starts by opening the Bullets and Numbering dialog box and changing the Start At value."},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_continued_numbering.png",alt:"Changing numbering start value"},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_continued_numbering_displayed.png",alt:"Numbering continued across a list"}]},{heading:"Completed Slide Example",blocks:[{type:"paragraph",text:"After applying bullets or numbering and customizing the formatting, your slide will look more organized and easier for your audience to read."},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_final_result.png",alt:"Final result of formatted lists on a PowerPoint slide"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"When should you use a numbered list on a slide?",options:["When you want to add visual variety with different bullet symbols","When the order of items does not matter","When the order of items matters","When you have more than five items to list"],correctIndex:2,explanation:"Numbers communicate sequence. Use them whenever steps must happen in a particular order; bullets tell the audience the order does not matter, which misleads them on a procedure.",optionRationales:["Visual variety is not a reason to change list type. The list type carries meaning, and choosing it for looks misinforms.","That is exactly when bullets are appropriate — numbers would imply an order that does not exist.","Correct. Numbers signal sequence, so use them whenever order matters.","Item count has no bearing on the choice. If anything, more than five or six items suggests the slide should be split."]}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Open the practice presentation.","Select the slide that contains the agenda list.","Convert the list into a numbered list.","Change the numbering so the list starts at 5.","Customize the bullet style for another list on the slide."]},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_final_result.png",alt:"Final result for the lists challenge"}]},{slug:"indents-and-line-spacing",title:"Indents and Line Spacing",description:"Learn how to adjust paragraph indentation and spacing to improve slide readability.",objectives:["Adjust line spacing and paragraph spacing in a placeholder","Use indent levels to show hierarchy","Explain how whitespace affects legibility from a distance","Recognize when spacing changes are hiding a content problem"],duration:"11 min",videoUrl:"https://www.youtube.com/embed/fhLlISfmGqA",practiceFiles:[{name:"Indents and Line Spacing Practice File",url:"/practice/powerpoint/module-2/indents/Powerpoint_IndentsLineSpacing_Practice.pptx"}],sections:[{heading:"Whitespace is what makes a slide readable from the back",blocks:[{type:"scenario",role:"You prepare a training slide at Lakeside Medical Associates.",text:"You cram five bullets in by cutting line spacing to 0.8. On your monitor it is fine. Projected in a room with the lights on, the lines run together into a gray block and the people at the back read none of it.",task:"Use spacing to aid legibility, and treat crowding as a signal to cut content."},{type:"paragraph",text:"Line spacing between about 1.0 and 1.2 suits most slide text. Tighter than that and lines start to merge visually at a distance, particularly with a projector's reduced contrast. Space between paragraphs matters more on a slide than in a document, because it is what separates one idea from the next at a glance."},{type:"callout",variant:"warning",text:"Reducing line spacing to fit more content is treating the symptom. Crowding means the slide is carrying more than a slide can carry — the fix is to split it or move detail to the notes. A slide that only fits at 0.8 spacing and 16 point will not be read by anyone beyond the second row."}]},{heading:"Why Indents and Spacing Matter",blocks:[{type:"paragraph",text:"Indentation and line spacing help organize text so information is easier for your audience to read."},{type:"paragraph",text:"Indentation creates hierarchy within lists and paragraphs, while line spacing controls the vertical distance between lines of text."}]},{heading:"Showing the Ruler",blocks:[{type:"paragraph",text:"The ruler provides visual controls that allow you to adjust indentation precisely."},{type:"paragraph",text:"If the ruler is not visible, go to the View tab and check the Ruler option."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_show_ruler.png",alt:"Turning on the ruler in PowerPoint"}]},{heading:"Understanding Indent Markers",blocks:[{type:"paragraph",text:"The ruler contains several markers that control how text is indented."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_first_line_marker.png",alt:"First line indent marker"},{type:"paragraph",text:"The first-line indent marker controls where the first line of a paragraph begins."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_hanging_indent_marker.png",alt:"Hanging indent marker"},{type:"paragraph",text:"The hanging indent marker controls the indentation of every line except the first."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_left_indent_marker.png",alt:"Left indent marker"},{type:"paragraph",text:"The left indent marker moves the entire paragraph inward."}]},{heading:"Adjusting Indentation",blocks:[{type:"paragraph",text:"You can adjust bullet alignment by dragging the indent markers on the ruler."},{type:"paragraph",text:"This allows you to control how far bullet points and text appear from the left side of the slide."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_left_indent_marker_example.png",alt:"Example of adjusting the left indent marker"},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_left_indent_marker_example_dragged.png",alt:"Left indent marker dragged"}]},{heading:"Using Hanging Indents",blocks:[{type:"paragraph",text:"The hanging indent marker controls how lines wrap after the first line of text."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_hanging_indent_marker_example.png",alt:"Hanging indent marker example"},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_hanging_indent_marker_example_dragged.png",alt:"Dragging the hanging indent marker"}]},{heading:"Creating Multilevel Lists",blocks:[{type:"paragraph",text:"Indentation can also be used to create multilevel lists that organize information into main topics and subtopics."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_list_multilevel.png",alt:"Multilevel bullet list example"}]},{heading:"Adjusting Line Spacing",blocks:[{type:"paragraph",text:"Line spacing controls how much vertical space appears between lines of text."},{type:"paragraph",text:"To change line spacing, select the text and click the Line Spacing button in the Paragraph group on the Home tab."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_line_spacing_size.png",alt:"Line spacing menu"},{type:"paragraph",text:"You can select common spacing options such as 1.0, 1.5, or 2.0."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_line_spacing_example.png",alt:"Line spacing example"}]},{heading:"Using Line Spacing Options",blocks:[{type:"paragraph",text:"For more precise control, open Line Spacing Options from the dropdown menu."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_line_spacing_options.png",alt:"Line spacing options dialog box"},{type:"paragraph",text:"You can adjust spacing before and after paragraphs to improve readability."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_line_spacing_adjusted.png",alt:"Adjusted line spacing"}]},{heading:"Completed Slide Example",blocks:[{type:"paragraph",text:"After adjusting indentation and line spacing, the slide will appear more organized and easier to read."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_final_result.png",alt:"Completed PowerPoint slide"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What does increasing line spacing do?",options:["Increases the font size of the selected text","Adds more space between lines of text, improving readability","Moves the text box higher on the slide","Changes the indent level of bullet points"],correctIndex:1,explanation:"Line spacing controls the vertical gap between lines within a paragraph. On a slide, adequate spacing is what keeps lines from merging visually when projected at a distance.",optionRationales:["Font size is a separate setting. Line spacing changes the gaps between lines, not the size of the characters.","Correct. It adds space between lines, which improves legibility — especially when projected.","Position on the slide is controlled by moving the placeholder. Line spacing works inside it.","Indent level is changed with Tab and Shift+Tab or the indent buttons. Spacing and indentation are independent."]}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Open the practice presentation.","Navigate to the slide containing the agenda.","Select the bulleted list.","Change the line spacing using Line Spacing Options.","Show the ruler if it is not already visible.","Adjust the left indent marker to align the bullet points."]},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_final_result.png",alt:"Final result of the indents and spacing challenge"}]},{slug:"using-find-and-replace",title:"Using Find & Replace in PowerPoint",description:"Learn how to quickly locate text in your presentation and replace it with new content using the Find and Replace tools.",objectives:["Find text across all slides in a presentation","Replace text throughout a deck","Use Replace Fonts to swap a typeface everywhere","Check that a replacement has not broken anything"],duration:"7 min",videoUrl:"https://www.youtube.com/embed/TEqzwdC4x58",practiceFiles:[{name:"Find and Replace Practice File",url:"/practice/powerpoint/module-2/find-replace/Powerpoint_FindReplace_Practice.pptx"}],sections:[{heading:"One command for a change that touches every slide",blocks:[{type:"scenario",role:"You update the orientation deck at Lakeside Medical Associates.",text:"The practice changes its name. The old name appears on thirty-one of forty slides, including several inside diagrams. Slide by slide, this is half an hour and a guarantee of missing two.",task:"Replace throughout the deck in one action, then verify the result."},{type:"paragraph",text:"Replace (Ctrl+H) works across every slide at once. Match case is available and worth using for a proper noun, so you change the practice name without touching an ordinary word that happens to contain the same letters."},{type:"callout",variant:"info",text:"Replace Fonts, on the Replace dropdown, swaps one typeface for another everywhere in the deck. It is the correct fix when you inherit a presentation using a font your machine does not have, and far faster than selecting text on every slide. Check the deck afterwards — different fonts have different widths, so text that fitted before may now overflow its placeholder."},{type:"tip",text:"Find and Replace does not reach text inside images or embedded objects. After a replacement, use Outline View to confirm the old text is gone from all the real text, and then look through the slides for any that appears in a picture or a screenshot."}]},{heading:"Finding Text",blocks:[{type:"paragraph",text:"The Find tool allows you to search for specific words or phrases within your presentation."},{type:"paragraph",text:"This is useful when working with presentations that contain many slides or repeated information."},{type:"paragraph",text:"To use Find, go to the Home tab and click the Find command in the Editing group."},{type:"image",src:"/images/powerpoint/module-2/find-replace/find-replace_find_command.png",alt:"Find command in PowerPoint"},{type:"paragraph",text:"The Find dialog box will appear where you can enter the word or phrase you want to locate."},{type:"image",src:"/images/powerpoint/module-2/find-replace/find-replace_find_next.png",alt:"Find dialog box in PowerPoint"}]},{heading:"Locating Text",blocks:[{type:"paragraph",text:"After entering the search text, click Find Next to move through the presentation and locate each occurrence."},{type:"paragraph",text:"When PowerPoint finds the text, it will highlight the matching word or phrase on the slide."},{type:"image",src:"/images/powerpoint/module-2/find-replace/find-replace_text_found.jpeg",alt:"Highlighted search result in PowerPoint"}]},{heading:"Using Replace",blocks:[{type:"paragraph",text:"The Replace feature allows you to search for text and replace it with different text automatically."},{type:"paragraph",text:"This tool is especially useful when you need to update names, dates, or repeated information across multiple slides."},{type:"paragraph",text:"To open Replace, click the Replace command in the Editing group on the Home tab."},{type:"image",src:"/images/powerpoint/module-2/find-replace/find-replace_replace_command.png",alt:"Replace command in PowerPoint"},{type:"paragraph",text:"The Replace dialog box allows you to enter both the text you want to find and the text you want to replace it with."},{type:"image",src:"/images/powerpoint/module-2/find-replace/find-replace_replace_dialog.png",alt:"Replace dialog box"}]},{heading:"Replacing Text",blocks:[{type:"paragraph",text:"Once the text is found, you can click Replace to change the highlighted occurrence."},{type:"image",src:"/images/powerpoint/module-2/find-replace/find-replace_replace_execute.png",alt:"Replacing text in PowerPoint"},{type:"paragraph",text:"If you want PowerPoint to replace every occurrence of the text in the presentation, click Replace All."},{type:"image",src:"/images/powerpoint/module-2/find-replace/find-replace_replace_finished.jpeg",alt:"PowerPoint confirmation after replacing text"}]},{heading:"Completed Slide Example",blocks:[{type:"paragraph",text:"After replacing the text, the updated content will appear throughout the presentation."},{type:"paragraph",text:"This allows you to quickly update repeated information without manually editing each slide."},{type:"image",src:"/images/powerpoint/module-2/find-replace/find-replace_final_result.png",alt:"Completed slide after replacing text"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is the main use of Replace in PowerPoint?",options:["To format all instances of a word with bold or italic","To delete a word or phrase from every slide","To swap one word or phrase for another throughout the whole presentation","To move text from one slide to another"],correctIndex:2,explanation:"Replace swaps one word or phrase for another throughout the entire presentation in a single action, rather than requiring you to edit each slide.",optionRationales:["Replace changes the text itself, not its formatting. Formatting every instance is a separate task.","Deleting is possible by replacing with nothing, but that is a special case rather than what Replace is for.","Correct. It swaps one word or phrase for another across every slide at once.","Moving text between slides is done by cutting and pasting. Replace changes text in place."]}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the presentation:"},{type:"list",ordered:!0,items:["Open the presentation.","Use the Find command to search for the text '2015-2016'.","Use Replace to change it to '2016-2017'.","Click Replace All to update every occurrence.","Confirm the changes when PowerPoint displays the replacement message."]},{type:"image",src:"/images/powerpoint/module-2/find-replace/find-replace_final_result.png",alt:"Final result of the Find and Replace challenge"}]}],level:"Beginner",estimatedMinutes:46},{moduleNumber:3,moduleSlug:"module-3",title:"Slide Design & Themes",emoji:"\uD83C\uDFA8",description:"Learn how to improve the visual appearance of your presentation using themes and layouts.",lessons:[{slug:"applying-themes",title:"Applying Themes",description:"Learn how to quickly change the design of your presentation using built-in PowerPoint themes.",objectives:["Apply a theme and explain what it changes","Choose theme variants and understand what they alter","Judge a theme by legibility rather than attractiveness","Keep a deck consistent with organizational branding"],duration:"8 min",videoUrl:"https://www.youtube.com/embed/_gYShFl6i94",practiceFiles:[{name:"Applying Themes Practice File",url:"/practice/powerpoint/module-3/themes/Powerpoint_Themes_Practice.pptx"}],sections:[{heading:"Choose a theme for the room, not for the monitor",blocks:[{type:"scenario",role:"You design the annual staff briefing at Lakeside Medical Associates.",text:"You pick a theme with pale gray text on a white background. It looks refined on your monitor. Projected in a room where the lights must stay on, the text is close to invisible from the fourth row.",task:"Evaluate a theme by whether it survives a real projector in a real room."},{type:"paragraph",text:"A theme sets colors, fonts, and effects across every slide at once, so the whole deck stays coherent and a redesign is one click rather than forty. That is its value. Its risk is that theme choice is usually made on a bright monitor a foot from your face, under conditions nothing like a presentation."},{type:"paragraph",text:"Projection loses contrast, and ambient light loses more. Strong contrast — genuinely dark text on a genuinely light background, or the reverse — is the single most important property of a presentation theme. Mid-gray on white, or any two mid-tones together, will fail in the room."},{type:"callout",variant:"warning",text:"Test on the actual equipment when the presentation matters. Colors shift on projectors, thin fonts lose their strokes, and a subtle background gradient can turn into visible banding. Ten minutes in the room beforehand catches all of it — and is also when you discover the resolution is different from your laptop's."}]},{heading:"What is a Theme?",blocks:[{type:"paragraph",text:"A theme is a predefined combination of colors, fonts, layouts, and visual effects that control the overall appearance of a presentation."},{type:"paragraph",text:"PowerPoint presentations use a theme by default. Even if you never choose one manually, the Office theme is already applied when you create a new presentation."},{type:"paragraph",text:"Applying a theme allows you to instantly change the design of every slide while keeping the presentation consistent and professional."},{type:"image",src:"/images/powerpoint/module-3/themes/applying-themes_example.png",alt:"Two slides showing different PowerPoint themes applied"}]},{heading:"Theme Elements",blocks:[{type:"paragraph",text:"Every PowerPoint theme includes a set of design elements that work together to control the appearance of your slides."},{type:"paragraph",text:"These elements ensure that colors, fonts, and design effects remain consistent throughout the entire presentation."},{type:"paragraph",text:"The three main theme elements are theme colors, theme fonts, and theme effects."},{type:"image",src:"/images/powerpoint/module-3/themes/applying-themes_theme_colors.png",alt:"Theme colors menu in PowerPoint"},{type:"paragraph",text:"Theme colors define the color palette used throughout the presentation."},{type:"image",src:"/images/powerpoint/module-3/themes/applying-themes_theme_fonts.png",alt:"Theme fonts shown in PowerPoint font menu"},{type:"paragraph",text:"Theme fonts determine the default fonts used for headings and body text."},{type:"image",src:"/images/powerpoint/module-3/themes/applying-themes_theme_effects.png",alt:"Theme effects and shape styles in PowerPoint"},{type:"paragraph",text:"Theme effects control the appearance of shapes, SmartArt graphics, and other design elements."}]},{heading:"Applying a Theme",blocks:[{type:"paragraph",text:"All themes in PowerPoint are located on the Design tab in the Themes group."},{type:"paragraph",text:"You can apply a theme at any time, and PowerPoint will automatically update every slide in the presentation."},{type:"paragraph",text:"To apply a theme, open the Design tab and locate the Themes group."},{type:"image",src:"/images/powerpoint/module-3/themes/applying-themes_more_themes.png",alt:"Themes group on the PowerPoint Design tab"},{type:"paragraph",text:"Click the More arrow to view the complete gallery of available themes."},{type:"image",src:"/images/powerpoint/module-3/themes/applying-themes_desired_themes.png",alt:"PowerPoint theme gallery"},{type:"paragraph",text:"Select the theme you want and it will immediately be applied to the entire presentation."},{type:"image",src:"/images/powerpoint/module-3/themes/applying-themes_applied_theme.png",alt:"Theme applied to PowerPoint presentation"}]},{heading:"Using Theme Variants",blocks:[{type:"paragraph",text:"After applying a theme, you can change the appearance of that theme by choosing a variant."},{type:"paragraph",text:"Variants adjust the color scheme while keeping the same overall theme layout and design."},{type:"image",src:"/images/powerpoint/module-3/themes/applying-themes_variant_theme.png",alt:"Theme variants options in PowerPoint"},{type:"paragraph",text:"This allows you to quickly explore different design options without changing the entire theme."}]},{heading:"Completed Presentation Example",blocks:[{type:"paragraph",text:"After applying a theme and selecting a variant, your slides will have a consistent design and professional appearance."},{type:"image",src:"/images/powerpoint/module-3/themes/applying-themes_final_result.jpeg",alt:"Final presentation with applied theme"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What does applying a theme to a presentation do?",options:["Changes only the font used in the presentation","Adds animations to every slide automatically","Changes the overall visual design including colors, fonts, and backgrounds","Replaces all slide content with placeholder text"],correctIndex:2,explanation:"A theme applies a coordinated set of colors, fonts, backgrounds, and effects across every slide, so the deck stays visually consistent and can be redesigned in one action.",optionRationales:["Fonts are one part of a theme. It also changes colors, backgrounds, and effects.","Themes are static design. Animation is applied separately from the Animations tab.","Correct. A theme changes the overall visual design — colors, fonts, and backgrounds — across the deck.","Themes never alter content. Only the design changes."]}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Open the practice presentation.","Select the Design tab.","Open the Themes gallery.","Apply the Gallery theme.","Select a different theme variant."]},{type:"image",src:"/images/powerpoint/module-3/themes/applying-themes_final_result.jpeg",alt:"Final result after applying a theme"}]},{slug:"modifying-themes",title:"Modifying Themes",description:"Learn how to customize PowerPoint themes by changing theme colors, fonts, effects, and background styles.",objectives:["Change theme colors, fonts, and effects independently","Create and save a custom theme for reuse","Check color contrast for legibility","Apply organizational branding consistently"],duration:"10 min",videoUrl:"https://www.youtube.com/embed/UH7Gzjd3rGA",practiceFiles:[{name:"Modifying Themes Practice File",url:"/practice/powerpoint/module-3/modifying/Powerpoint_ModifyingThemes_Practice.pptx"}],sections:[{heading:"Build the practice's theme once",blocks:[{type:"scenario",role:"You standardize presentations across Lakeside Medical Associates.",text:"Five staff produce decks and all five look different. Patients and partners see materials that do not appear to come from the same organization. Everyone is choosing colors from scratch each time, because there is nothing to choose from.",task:"Define the practice's colors and fonts once as a saved theme, so consistency is the easy path."},{type:"paragraph",text:"Theme colors, fonts, and effects can each be changed independently from the Design tab's Variants dropdown. Set the practice's palette and typefaces, then Save Current Theme — the theme appears in the gallery for everyone it is shared with, in PowerPoint, Word, and Excel alike."},{type:"paragraph",text:"Once the theme exists, staff choose from theme colors rather than inventing them, and every deck matches without anyone needing to remember a hex code. Making the consistent choice the easy one is what actually produces consistency."},{type:"callout",variant:"warning",text:"Check contrast when you set the palette, not afterwards. Body text should reach at least a 4.5:1 contrast ratio against its background; large display text can go to 3:1. Free checkers online will give you the number from two hex values. Building the palette to pass means no one downstream has to think about it."}]},{heading:"Modifying PowerPoint Themes",blocks:[{type:"paragraph",text:"PowerPoint themes control the overall appearance of your presentation, including colors, fonts, and visual effects."},{type:"paragraph",text:"If you like the general design of a theme but want to adjust certain elements, you can modify the theme instead of choosing a completely different one."},{type:"paragraph",text:"You can change theme colors, fonts, effects, and background styles while keeping the overall layout of the theme."},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_variant_dropdown.png",alt:"Variants dropdown menu in PowerPoint"}]},{heading:"Changing Theme Colors",blocks:[{type:"paragraph",text:"If you don't like the colors of a theme, you can quickly apply a different color set while keeping the rest of the theme unchanged."},{type:"paragraph",text:"Theme colors control the color palette used for text, shapes, charts, and other design elements in your presentation."},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_variant_colors.png",alt:"Theme color options in PowerPoint"},{type:"paragraph",text:"To change theme colors, open the Design tab, click the Variants drop-down arrow, select Colors, and choose the desired color set."}]},{heading:"Customizing Theme Colors",blocks:[{type:"paragraph",text:"If none of the built-in color sets match your design needs, you can create your own custom theme colors."},{type:"paragraph",text:"Custom colors allow you to control the exact colors used for text backgrounds, accents, and hyperlinks."},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_customize_colors.png",alt:"Customize theme colors dialog box"},{type:"paragraph",text:"Open Design → Variants → Colors → Customize Colors, then choose new colors and give your custom theme a name before saving it."}]},{heading:"Changing Theme Fonts",blocks:[{type:"paragraph",text:"Theme fonts define the default fonts used for headings and body text across the entire presentation."},{type:"paragraph",text:"Changing theme fonts helps keep text consistent throughout all slides."},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_variant_font.png",alt:"Theme fonts menu in PowerPoint"},{type:"paragraph",text:"To change fonts, open the Design tab, click Variants, select Fonts, and choose a font pair from the list."}]},{heading:"Customizing Theme Fonts",blocks:[{type:"paragraph",text:"If you want to use specific fonts, you can create your own custom theme font combination."},{type:"paragraph",text:"This allows you to choose one font for headings and another for body text."},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_customize_fonts.png",alt:"Customize fonts dialog box in PowerPoint"},{type:"paragraph",text:"Select Design → Variants → Fonts → Customize Fonts, choose the heading and body fonts, then save the custom font theme."}]},{heading:"Changing Theme Effects",blocks:[{type:"paragraph",text:"Theme effects control the appearance of shapes, SmartArt graphics, and other visual objects in your presentation."},{type:"paragraph",text:"Changing theme effects can adjust elements such as shadows, glows, reflections, and shape styles."},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_theme_effects.jpeg",alt:"Theme effects options in PowerPoint"},{type:"paragraph",text:"To apply a different effect style, open the Design tab, click Variants, select Effects, and choose the desired effect."}]},{heading:"Changing Background Styles",blocks:[{type:"paragraph",text:"You can also change the background style of your slides to further customize the appearance of your presentation."},{type:"paragraph",text:"Background styles depend on the current theme and color settings."},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_background_styles.png",alt:"Background styles options in PowerPoint"},{type:"paragraph",text:"Open Design → Variants → Background Styles and choose a new background. For additional options, select Format Background."}]},{heading:"Saving a Custom Theme",blocks:[{type:"paragraph",text:"After customizing colors, fonts, and effects, you can save your theme and reuse it in future presentations."},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_save_current_theme.jpeg",alt:"Save current theme option in PowerPoint"},{type:"paragraph",text:"Open the Themes gallery on the Design tab and select Save Current Theme."},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_save_dialog.png",alt:"Save theme dialog box"},{type:"paragraph",text:"Enter a name for the theme and click Save. The theme will appear in the Custom section of the theme gallery."}]},{heading:"Completed Presentation Example",blocks:[{type:"paragraph",text:"After modifying theme colors, fonts, effects, and background styles, your presentation will have a customized and consistent design."},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_final_result.png",alt:"Final presentation after modifying theme"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which element of a theme controls the color palette used throughout the presentation?",options:["Theme effects","Theme fonts","Background styles","Theme colors"],correctIndex:3,explanation:"Theme colors define the palette applied across the presentation — backgrounds, text, accents, chart series, and shape fills all draw from it.",optionRationales:["Theme effects control shadows, reflections, and 3-D treatments on shapes.","Theme fonts set the heading and body typefaces.","Background styles are variations built from the theme colors, so they follow the palette rather than defining it.","Correct. Theme colors define the palette used throughout the presentation."]}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Open the practice presentation.","Change the theme colors.","Customize the fonts so the heading font is Garamond and the body font is Arial.","Change the background style.","Optional: Save your customized theme."]},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_final_result.png",alt:"Final result after modifying a theme"}]},{slug:"slide-master-view",title:"Slide Master View",description:"Learn how to use Slide Master view to make global design changes, create custom layouts, manage placeholders, and keep an entire presentation consistent.",objectives:["Open Slide Master view and explain what it controls","Distinguish the master from the layouts beneath it","Add a logo or standing element to every slide at once","Edit a layout without affecting the rest of the deck"],duration:"16 min",videoUrl:"https://www.youtube.com/embed/h6ARCTypPTg",practiceFiles:[{name:"Slide Master View Practice File",url:"/practice/powerpoint/module-3/slide-master-view/Powerpoint_SlideMaster_Practice.pptx"}],sections:[{heading:"One change instead of forty",blocks:[{type:"scenario",role:"You maintain the standard deck at Lakeside Medical Associates.",text:"The practice logo must appear on every slide of a forty-slide deck. Pasted onto each slide by hand, it lands in forty slightly different positions and takes twenty minutes. Placed on the Slide Master, it appears once on every slide, in exactly the same place, in about fifteen seconds.",task:"Use the master for anything that should appear on every slide."},{type:"paragraph",text:"Slide Master view (View > Slide Master) shows a hierarchy. The master is at the top, and every layout beneath inherits from it. A change to the master reaches all layouts; a change to one layout affects only slides using that layout. This is the same inheritance idea as styles in Word, applied to slide design."},{type:"table",caption:"Where to make a change",columns:["You want to change","Edit","Effect"],rows:[["Logo on every slide","The master","Appears on all layouts at once"],["Title font throughout","The master's title placeholder","Every layout's title updates"],["The title slide only","The Title Slide layout","Other slides are unaffected"],["Add a new arrangement","Insert Layout","Becomes available in the New Slide gallery"]]},{type:"worked-example",title:"Putting the practice logo on every slide",task:"Add the logo to a forty-slide deck so it sits identically on every slide and stays there as slides are added.",steps:[{move:"View > Slide Master, and select the top thumbnail — the master itself.",why:"The top thumbnail is larger and sits above the indented layouts. Selecting a layout instead is the usual mistake, and it puts the logo on only the slides using that one layout."},{move:"Insert the logo and position it, allowing clear space from the edges.",why:"Projectors and video calls sometimes crop the outer edge of a slide. Keeping the logo a little inside the boundary means it survives that, and it looks deliberate rather than jammed into the corner."},{move:"Close Master View and check several slides, including the title slide.",why:"The Title Slide layout often has its own background and may position or hide the logo differently. Checking a few slides of different layouts confirms the change reached them as intended."},{move:"Add a new slide and confirm the logo appears on it too.",why:"This is the actual test of whether you edited the master rather than individual slides. A logo that appears on new slides automatically is inherited; one that does not was pasted onto existing slides."}],result:"The logo on every slide, in one position, appearing automatically on any slide added later.",takeaway:"Edit the master for what belongs everywhere and a layout for what belongs on one kind of slide. Never paste a standing element onto individual slides."}]},{heading:"What Slide Master View Does",blocks:[{type:"paragraph",text:"Slide Master view allows you to control the overall design and layout structure of an entire presentation. Instead of editing slides one by one, you can update the master and its layouts so that design changes appear everywhere they are used."},{type:"paragraph",text:"This is especially useful when you want consistent branding, repeated logos, matching fonts, and reusable slide layouts throughout a presentation."}]},{heading:"Opening Slide Master View",blocks:[{type:"paragraph",text:"To begin working with slide masters, go to the View tab and select Slide Master. PowerPoint will switch from the normal editing view into the master editing workspace."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_ribbon_view.png",alt:"View tab with Slide Master command in PowerPoint"},{type:"paragraph",text:"Once Slide Master view opens, the left pane will display the large master slide at the top and the related layouts below it."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_slide_master_select.png",alt:"Slide Master selected in the left pane"}]},{heading:"Understanding the Master Slide and Layouts",blocks:[{type:"paragraph",text:"The top slide in Slide Master view is the master slide. It controls global elements such as theme fonts, background styling, and repeated objects like logos."},{type:"paragraph",text:"The smaller slides beneath it are layouts. Each layout controls the structure of a specific slide type such as title slides, content slides, or image-based slides."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_slide_master.png",alt:"Slide Master view showing hierarchy"},{type:"paragraph",text:"When you apply a layout to a slide, that slide inherits all formatting and structure from that layout."}]},{heading:"Editing Master Text and Branding",blocks:[{type:"paragraph",text:"You can format text on the master or layouts just like regular slides, including font style, size, and alignment."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_text_formatting.png",alt:"Formatting text in Slide Master"},{type:"paragraph",text:"You can also insert logos or branding elements so they automatically appear on multiple slides."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_resize_move_logo.png",alt:"Logo placement"}]},{heading:"Using Theme Fonts in Slide Master",blocks:[{type:"paragraph",text:"Slide Master view works closely with themes. Changing theme fonts will update text across all layouts instantly."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_theme_font.png",alt:"Theme fonts"},{type:"paragraph",text:"This ensures consistency and helps maintain a professional appearance."}]},{heading:"Inserting and Managing Placeholders",blocks:[{type:"paragraph",text:"Placeholders define where content such as text, images, charts, and media will appear on a slide."},{type:"paragraph",text:"Use Insert Placeholder from the Slide Master tab to add placeholders to layouts."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_placeholders.png",alt:"Insert placeholder menu"},{type:"paragraph",text:"Once placed, you can resize and position placeholders to create structured layouts."}]},{heading:"Creating a Custom Layout",blocks:[{type:"paragraph",text:"You can create your own layouts to standardize how slides are structured across a presentation."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_ribbon.png",alt:"Slide Master ribbon"},{type:"paragraph",text:"Custom layouts are useful for things like product slides, team slides, or image-focused content."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_select_layout.png",alt:"Selecting layout"}]},{heading:"Renaming Layouts",blocks:[{type:"paragraph",text:"Renaming layouts makes them easier to identify and reuse later."},{type:"paragraph",text:"Click Rename and assign a meaningful name such as Product Slide."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_rename_layout.png",alt:"Rename layout"},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_rename_dialog.png",alt:"Rename dialog"}]},{heading:"Showing and Hiding Master Elements",blocks:[{type:"paragraph",text:"You can control whether titles, footers, and background elements appear on specific layouts."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_titles_footers.png",alt:"Footer options"}]},{heading:"Applying Custom Layouts to Slides",blocks:[{type:"paragraph",text:"Apply layouts from the Home tab to instantly update slide structure and formatting."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_use_custom_layout.png",alt:"Applying layout"}]},{heading:"Saving the Theme",blocks:[{type:"paragraph",text:"Save your customized theme to reuse it in future presentations."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_save_current_theme.png",alt:"Save theme"},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_save_theme.png",alt:"Save dialog"}]},{heading:"Closing Slide Master View",blocks:[{type:"paragraph",text:"Click Close Master View to return to the normal editing environment."}]},{heading:"Completed Presentation Example",blocks:[{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_slides_updated.jpeg",alt:"Final slides"}]},{heading:"Pro Tip",blocks:[{type:"callout",variant:"success",text:"If you find yourself repeating the same formatting changes across multiple slides, switch to Slide Master view. One change there updates every slide automatically."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What does Slide Master control?",options:["Only one slide","The entire presentation design","Animations only"],correctIndex:1,explanation:"The Slide Master sits at the top of the design hierarchy: changes there flow down to every layout and therefore to the whole presentation.",optionRationales:["A single slide is edited directly in Normal view. The master's purpose is precisely that it is not limited to one slide.","Correct. The master controls the design for the entire presentation through the layouts that inherit from it.","Animation is applied per object from the Animations tab. The master governs design and layout."]},{type:"knowledge-check",question:"What is a layout?",options:["A color theme","A slide structure template","A font style"],correctIndex:1,explanation:"A layout is a slide structure template — a named arrangement of placeholders that inherits its design from the master. Choosing a layout decides where content sits on that slide.",optionRationales:["A color theme is part of the theme, set from the Design tab.","Correct. A layout is a slide structure template defining the placeholder arrangement.","Font styles come from the theme fonts, not from a layout."]},{type:"knowledge-check",question:"Why are placeholders important?",options:["To lock slides","To define content areas","To animate slides"],correctIndex:1,explanation:"Placeholders define where content belongs on a slide. Because their position comes from the master, typing into placeholders rather than free text boxes is what keeps every slide aligned consistently.",optionRationales:["Placeholders do not lock anything. Restricting changes is a separate feature.","Correct. Placeholders define the content areas, which is what keeps slides consistent.","Animation is applied separately. A placeholder can be animated, but that is not its purpose."]}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Open the practice presentation.","Go to the View tab and open Slide Master view.","Select one of the layouts and rename it Product Slide.","Insert a Picture placeholder on a custom layout.","Move and resize the logo so it is aligned consistently on the layout.","Change the theme font used for the layout.","Return to Normal view.","Apply the custom Product Slide layout to an existing slide.","Save the current theme for future use."]},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_slides_updated.jpeg",alt:"Final result"}]}],level:"Beginner",estimatedMinutes:35},{moduleNumber:4,moduleSlug:"module-4",title:"Managing Slides & Presentations",emoji:"\uD83D\uDCC2",description:"Organize slides, manage presentation structure, print slides, and present to an audience.",lessons:[{slug:"managing-slides",title:"Managing Slides",description:"Learn how to organize slides using slide views, notes, and sections to manage large presentations more effectively.",objectives:["Reorder, duplicate, hide, and delete slides","Organize a long deck into sections","Use speaker notes effectively","Choose the right view for reorganizing a presentation"],duration:"11 min",videoUrl:"https://www.youtube.com/embed/UmOJXAr_riE",practiceFiles:[{name:"Managing Slides Practice File",url:"/practice/powerpoint/module-4/managing-slides/Powerpoint_ManagingSlides_Practice.pptx"}],sections:[{heading:"Structure the deck before you polish it",blocks:[{type:"scenario",role:"You assemble the annual review deck at Lakeside Medical Associates.",text:"Forty-five slides in Normal view means scrolling a thumbnail strip to find anything. Reordering means dragging a slide past thirty others and hoping it lands where you meant.",task:"Use Slide Sorter and sections to work on the deck's shape rather than one slide at a time."},{type:"paragraph",text:"Slide Sorter view shows every slide as a thumbnail on one screen, which is the right place to reorder, delete, and check visual consistency. Seeing all forty-five at once also reveals patterns you cannot notice one slide at a time — six consecutive bullet slides, or a title that jumps position."},{type:"paragraph",text:"Sections group slides under named headings that collapse and expand. In a long deck they make navigation practical, and they let you jump directly to a section when a question comes up during the presentation."},{type:"tip",text:"Hiding a slide (right-click > Hide Slide) keeps it in the file but skips it during the show. It is the right way to hold backup detail for a question you might be asked — the slide is there if you need it and never appears if you do not."}]},{heading:"Slide Views",blocks:[{type:"paragraph",text:"PowerPoint includes several slide views that help you work with slides in different ways."},{type:"paragraph",text:"The slide view buttons are located in the bottom-right corner of the PowerPoint window."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_slide_views.png",alt:"Slide view buttons in PowerPoint"},{type:"paragraph",text:"Each view provides a different way to work with slides, including editing, organizing, and presenting your presentation."},{type:"paragraph",text:"As presentations grow larger, switching to the right view becomes more important. Instead of doing everything in one workspace, PowerPoint gives you different ways to focus on structure, content, notes, and delivery."}]},{heading:"Normal View",blocks:[{type:"paragraph",text:"Normal View is the default editing view used when creating and editing slides."},{type:"paragraph",text:"This view displays the current slide in the center, slide thumbnails on the left, and the notes pane below the slide."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_normal_view.png",alt:"Normal view in PowerPoint"},{type:"paragraph",text:"You can also drag slides in the navigation pane to quickly change their order."},{type:"paragraph",text:"Normal View is best when you are actively building content, editing text, inserting media, and making detailed slide changes. It is the main work area most users spend the majority of their time in."}]},{heading:"Slide Sorter View",blocks:[{type:"paragraph",text:"Slide Sorter View displays all slides as thumbnails so you can easily rearrange them."},{type:"paragraph",text:"This view is helpful when organizing presentations with many slides."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_thumbnail.jpeg",alt:"Slide sorter view showing slide thumbnails"},{type:"paragraph",text:"To move a slide, simply click and drag it to a new position."},{type:"paragraph",text:"Slide Sorter View is especially useful when you want to look at the overall flow of a presentation. Instead of focusing on one slide at a time, you can step back and evaluate the sequence of ideas across the full deck."}]},{heading:"Reading View and Slide Show View",blocks:[{type:"paragraph",text:"Reading View shows the presentation in a window while still allowing access to PowerPoint tools."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_reading_view.png",alt:"Reading view in PowerPoint"},{type:"paragraph",text:"Slide Show View displays the presentation exactly as the audience will see it."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_slide_show_view.png",alt:"Slide show view in PowerPoint"},{type:"paragraph",text:"Reading View is useful when you want to preview slides without fully entering presentation mode. Slide Show View is better when you want to rehearse or present the deck as a finished product."}]},{heading:"Outline View",blocks:[{type:"paragraph",text:"Outline View displays the text from your slides in outline form."},{type:"paragraph",text:"This makes it easier to review or edit the text from multiple slides at once."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_outline_view.png",alt:"Outline view command"},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_outline_edit.png",alt:"Editing text in outline view"},{type:"paragraph",text:"Outline View is ideal when you want to focus on the presentation’s message rather than its design. It helps you see whether your slides are logically organized and whether the text communicates your ideas clearly."}]},{heading:"Adding Notes",blocks:[{type:"paragraph",text:"You can add notes to slides using the Notes pane below the slide."},{type:"paragraph",text:"Notes are often used as speaker notes to help presenters remember what to say."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_notes_pane.png",alt:"Opening the notes pane"},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_notes.png",alt:"Typing notes in the notes pane"},{type:"paragraph",text:"Speaker notes are not usually shown to the audience during a presentation, so they can include reminders, talking points, or extra detail that supports your delivery."}]},{heading:"Notes Page View",blocks:[{type:"paragraph",text:"You can also view notes in Notes Page view."},{type:"paragraph",text:"This view shows the slide at the top with a large area below it where you can edit notes."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_notes_page_view.png",alt:"Notes page view"},{type:"paragraph",text:"Notes Page View gives you more room to work with presenter notes than the standard Notes pane. This can be helpful when a slide needs more detailed speaking guidance."}]},{heading:"Creating Slide Sections",blocks:[{type:"paragraph",text:"When presentations contain many slides, sections can help organize them into groups."},{type:"paragraph",text:"To create a section, select a slide, click the Section command on the Home tab, and choose Add Section."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_add_section.png",alt:"Add section command"},{type:"paragraph",text:"A new Untitled Section will appear in the slide navigation pane."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_untitled_section.png",alt:"Untitled section in slide pane"},{type:"paragraph",text:"Sections are especially useful for large presentations because they break the deck into smaller parts. Instead of managing one long slide list, you can organize slides by topic, audience, or stage of the presentation."}]},{heading:"Renaming Sections",blocks:[{type:"paragraph",text:"You can rename a section to better describe the slides it contains."},{type:"paragraph",text:"Click the Section command and choose Rename Section."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_rename_section.png",alt:"Rename section command"},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_rename_dialog.png",alt:"Rename section dialog"},{type:"paragraph",text:"Clear section names make a presentation easier to navigate, especially when you revisit the file later or share it with another presenter."}]},{heading:"Collapsing and Removing Sections",blocks:[{type:"paragraph",text:"Sections can be collapsed in the slide navigation pane to hide slides inside them."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_collapse_section.png",alt:"Collapsed slide section"},{type:"paragraph",text:"If you no longer need a section, you can remove it using the Section command."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_remove_section.png",alt:"Remove section command"},{type:"paragraph",text:"Collapsing sections helps reduce clutter in the navigation pane so you can focus on the part of the presentation you are currently editing. Removing a section deletes the grouping, but it does not automatically delete the slides inside it."}]},{heading:"Completed Presentation Example",blocks:[{type:"paragraph",text:"After organizing slides into sections and adding notes, the presentation becomes easier to navigate and manage."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_final_result.png",alt:"Completed slide organization"},{type:"paragraph",text:"A well-organized presentation saves time during editing, makes it easier to prepare for delivery, and helps you stay in control as your slide deck grows."}]},{heading:"Pro Tip",blocks:[{type:"callout",variant:"success",text:"When a presentation starts getting long, do not wait until the end to organize it. Add sections as you build so the file stays clean and manageable from the start."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which view is best for rearranging slides quickly?",options:["Reading View","Slide Sorter View","Notes Page View","Slide Show View"],correctIndex:1,explanation:"Slide Sorter view shows every slide as a thumbnail on one screen, so you can drag slides into a new order and see the whole deck's structure at once.",optionRationales:["Reading View plays the presentation in a window for review. It does not support reordering.","Correct. Slide Sorter shows all slides as thumbnails, making reordering and structural review straightforward.","Notes Page view shows one slide with its notes below, for working on what you will say.","Slide Show view presents full screen to an audience and cannot be used for editing."]},{type:"knowledge-check",question:"What are slide notes mainly used for?",options:["Changing the design of a slide","Adding speaker reminders and talking points","Animating slide transitions","Creating new sections"],correctIndex:1,explanation:"Speaker notes hold what you plan to say. The audience never sees them, and they appear in Presenter View alongside a timer and the next slide.",optionRationales:["Design changes are made on the slide itself or through the Slide Master.","Correct. Notes hold reminders and talking points, visible only to you in Presenter View.","Transitions are applied from the Transitions tab, independently of notes.","Sections are created by right-clicking between slides. Notes are attached to a single slide."]},{type:"knowledge-check",question:"What is the main benefit of using sections?",options:["They automatically animate slides","They print slides faster","They organize large presentations into groups","They replace slide layouts"],correctIndex:2,explanation:"Sections group slides under named, collapsible headings, which makes a long deck navigable and lets you move a whole group of slides at once.",optionRationales:["Sections have no effect on animation.","Sections are an organizational tool and do not affect printing speed.","Correct. Sections organize a large presentation into named groups.","Layouts and sections do different jobs — a layout arranges one slide's content, a section groups many slides."]}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Open the practice presentation.","Create a section for the first slide and name it Introduction.","Create a section named Dogs beginning with the slide 'Man's Best Friend'.","Create a section named Cats & More beginning with the slide 'The Little Things in Life'.","Move the slide titled 'Pogo' so it appears in the Dogs section.","Switch to Outline View.","Add a note on slide 4 that says 'Move before slide 3 or delete'.","Switch back to Normal View."]},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_final_result.png",alt:"Final challenge result"}]},{slug:"printing-presentations",title:"Printing Presentations",description:"Learn how to print slides, handouts, and notes pages, and understand PowerPoint’s print settings for different presentation needs.",objectives:["Choose an appropriate print layout for a given purpose","Print handouts with a sensible number of slides per page","Print speaker notes for yourself","Reduce ink and improve legibility on printed slides"],duration:"10 min",videoUrl:"https://www.youtube.com/embed/fzuHplbKD9A",practiceFiles:[{name:"Printing Practice File",url:"/practice/powerpoint/module-4/printing/Powerpoint_Printing_Practice.pptx"}],sections:[{heading:"A printed deck serves a different purpose from a projected one",blocks:[{type:"scenario",role:"You prepare materials for the board meeting at Lakeside Medical Associates.",text:"You print forty slides full page, one per sheet, on a dark-backgrounded theme. Forty sheets per attendee, most of the toner cartridge, and pages so dark the text is barely legible on paper.",task:"Pick the print layout that matches what the reader will do with it."},{type:"table",caption:"Print layouts",columns:["Layout","Produces","Use for"],rows:[["Full Page Slides","One slide per sheet","Rarely — only when detail genuinely needs the size"],["Notes Pages","Slide plus your notes","Your own copy while presenting"],["Handouts, 3 per page","Slides with ruled lines beside them","Audience handouts — the lines invite notes"],["Handouts, 6 per page","Six thumbnails per sheet","A compact reference after the session"],["Outline","Text only","Reviewing the argument without design"]]},{type:"tip",text:"For a dark-themed deck, choose Color/Grayscale > Pure Black and White in the print settings. It prints readable text on a white background instead of reproducing the dark background, saving most of the toner and producing something people can actually read and annotate."}]},{heading:"Accessing the Print Screen",blocks:[{type:"paragraph",text:"To print a presentation, open the File tab to enter Backstage view, then select Print. This opens the print workspace where you can preview and adjust all print settings."},{type:"image",src:"/images/powerpoint/module-4/printing/printing_tab.png",alt:"Print option selected in PowerPoint File tab"},{type:"paragraph",text:"Check the preview before every print job, not just the settings. The page count is the fastest check available: a deck that shows 12 slides and previews 13 pages has a stray blank, and finding it now costs thirty seconds instead of a stack of wasted paper."},{type:"image",src:"/images/powerpoint/module-4/printing/printing_print_pane.png",alt:"Print pane with preview and settings"}]},{heading:"Understanding Print Settings",blocks:[{type:"paragraph",text:"PowerPoint provides several print settings that allow you to control how your presentation will appear when printed."},{type:"image",src:"/images/powerpoint/module-4/printing/printing_print_options.png",alt:"Print settings options in PowerPoint"},{type:"paragraph",text:"Printing a range matters more than it sounds. When one slide changes after you have printed forty packets, printing just that page and swapping it is a few minutes; reprinting everything is an afternoon and a full toner cartridge."},{type:"paragraph",text:"For a dark-themed deck, choose Pure Black and White rather than Color. It prints readable dark text on white instead of reproducing the dark background, which saves most of the toner and produces something people can actually annotate."}]},{heading:"Print Layout Types",blocks:[{type:"paragraph",text:"One of the most important decisions when printing is choosing the correct layout. PowerPoint offers several formats depending on how the presentation will be used."},{type:"paragraph",text:"Full Page is rarely the right choice for an audience. It uses one sheet per slide and leaves no room to write. Handouts at 3 per page add ruled lines beside each slide, which is what people actually want to take notes on."},{type:"image",src:"/images/powerpoint/module-4/printing/printing_full_page.png",alt:"Full page slide printing example"},{type:"paragraph",text:"Handouts allow you to print multiple slides per page. This is useful for audiences who want to follow along during a presentation."},{type:"image",src:"/images/powerpoint/module-4/printing/printing_handout.png",alt:"Handout layout with multiple slides per page"},{type:"paragraph",text:"Notes Pages include each slide along with speaker notes beneath it. This is helpful when presenting or reviewing detailed talking points."},{type:"image",src:"/images/powerpoint/module-4/printing/printing_notes_page.png",alt:"Notes page with slide and speaker notes"},{type:"paragraph",text:"Printing the outline is a good way to check your own argument before you worry about design. Stripped of images and layout, a deck that does not make sense as a list of headings will not make sense to an audience either."},{type:"image",src:"/images/powerpoint/module-4/printing/printing_outline.png",alt:"Outline view showing text-only slide content"},{type:"tip",text:"If you're presenting to an audience, print handouts with 3 slides per page so viewers can take notes during your presentation."}]},{heading:"Using Print Preview",blocks:[{type:"paragraph",text:"Before printing, always review the print preview to ensure your slides appear correctly. This helps avoid issues such as incorrect layouts or cut-off content."},{type:"image",src:"/images/powerpoint/module-4/printing/printing_print_layout.png",alt:"Print preview showing slide layout"}]},{heading:"Printing Your Presentation",blocks:[{type:"paragraph",text:"Once your settings are configured, click the Print button to print your presentation."},{type:"image",src:"/images/powerpoint/module-4/printing/printing_print_command.png",alt:"Print button in PowerPoint"}]},{heading:"Completed Output Example",blocks:[{type:"paragraph",text:"A properly printed presentation should match your selected layout and provide a clear, readable format for your audience."},{type:"image",src:"/images/powerpoint/module-4/printing/printing_final_result.png",alt:"Final printed presentation example"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which print layout includes space for audience notes beside each slide?",options:["Full Page Slides","Notes Pages","Handouts","Outline"],correctIndex:2,explanation:"The Handouts layouts print slide thumbnails, and the 3-per-page option adds ruled lines beside each slide specifically so the audience can write notes.",optionRationales:["Full Page Slides prints one slide per sheet with no room for notes.","Notes Pages prints the presenter's own notes below each slide, which is for you rather than the audience.","Correct. Handouts, particularly 3 per page, include ruled lines for audience notes.","Outline prints the text hierarchy only, with no slides and no note space."]}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Open the practice presentation.","Go to File and select Print.","Change the print layout to Handouts (3 slides per page).","Preview the print layout.","Switch to Notes Pages view.","Return to Handouts layout.","Print the presentation or export it as a PDF."]},{type:"image",src:"/images/powerpoint/module-4/printing/printing_final_result.png",alt:"Final printed handout example"}]},{slug:"presenting-your-slide-show",title:"Presenting Your Slide Show",description:"Learn how to deliver your presentation using Slide Show view, navigation tools, Presenter View, and interactive presentation features.",objectives:["Start a slide show and navigate it confidently","Use Presenter View to see notes, timing, and the next slide","Use presentation tools such as the pen and screen blanking","Prepare for the practical failures that occur during presentations"],duration:"12 min",videoUrl:"https://www.youtube.com/embed/7-2oM3AGHQM",practiceFiles:[{name:"Presenting Practice File",url:"/practice/powerpoint/module-4/presenting/PowerPoint_Presenting_Practice.pptx"}],sections:[{heading:"Presenter View is the reason to stop reading your slides",blocks:[{type:"scenario",role:"You present at the all-staff meeting at Lakeside Medical Associates.",text:"Without Presenter View you turn to the screen to see what is on the slide, which means talking to the wall. You cannot see what is coming next, and you have no idea whether you are running long.",task:"Use Presenter View so your notes, the next slide, and a timer are in front of you and the audience sees only the presentation."},{type:"paragraph",text:"Presenter View puts your notes, a timer, a preview of the next slide, and navigation controls on your screen while the audience sees the slide alone. It is the single feature that most improves how a presentation is delivered, because it removes every reason to look at the projection."},{type:"table",caption:"Controls worth knowing before you stand up",columns:["Key","Does"],rows:[["F5","Starts the show from the beginning"],["Shift + F5","Starts from the current slide — what you want when rehearsing"],["B or W","Blanks the screen to black or white"],["Number then Enter","Jumps directly to that slide"],["Esc","Ends the show"],["Ctrl + P","Turns the pointer into a pen for annotating"]]},{type:"tip",text:"Pressing B blanks the screen to black. When discussion starts, or a question takes you off the deck, blanking removes the slide as a distraction and brings attention back to the room. It is the most useful key in the list and almost nobody knows it."},{type:"callout",variant:"warning",text:"Have a fallback. Carry the deck on a USB drive and a PDF export, know your opening two minutes well enough to start without slides, and arrive early enough to test the display. Presentations fail on unfamiliar hardware more often than on anything you did wrong in PowerPoint."}]},{heading:"Starting a Slide Show",blocks:[{type:"paragraph",text:"To present your slides, you must enter Slide Show view. This mode displays your presentation in full screen, just as your audience will see it."},{type:"paragraph",text:"You can start a slide show in several ways depending on your situation."},{type:"list",items:["Press F5 to start from the beginning","Use the Slide Show tab → From Beginning","Use From Current Slide to start from your current position","Click the Slide Show button in the bottom-right corner"]},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_start_command.png",alt:"Starting a slideshow in PowerPoint"},{type:"tip",text:"Use 'From Current Slide' when practicing or presenting updates so you don’t restart the entire presentation every time."}]},{heading:"Navigating Slides",blocks:[{type:"paragraph",text:"While presenting, you can move between slides using several methods."},{type:"list",items:["Click the mouse to move forward","Press the spacebar or arrow keys","Use on-screen navigation arrows"]},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_advance_arrows.png",alt:"Slide navigation arrows"},{type:"paragraph",text:"Using multiple navigation methods ensures you can present smoothly whether using a keyboard, mouse, or remote clicker."}]},{heading:"Ending a Slide Show",blocks:[{type:"paragraph",text:"To end your presentation, you can press the Esc key at any time."},{type:"paragraph",text:"You can also right-click during the presentation and select End Show from the menu."},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_end_show.png",alt:"End slideshow option"},{type:"paragraph",text:"At the end of the final slide, PowerPoint will display a message indicating the presentation has finished."}]},{heading:"Using Presentation Tools",blocks:[{type:"paragraph",text:"During a presentation, you can access additional tools by right-clicking or using the Slide Options menu."},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_right_clicking.png",alt:"Right-click presentation menu"},{type:"paragraph",text:"These tools allow you to navigate slides, access settings, and control your presentation without exiting Slide Show view."}]},{heading:"Jumping Between Slides",blocks:[{type:"paragraph",text:"You can jump to any slide instantly by selecting 'See All Slides' during your presentation."},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_thumbnail_versions.png",alt:"Slide thumbnails during presentation"},{type:"paragraph",text:"This is especially useful when answering audience questions or navigating a presentation out of order."}]},{heading:"Using Drawing Tools",blocks:[{type:"paragraph",text:"PowerPoint includes drawing tools that allow you to annotate slides during a presentation."},{type:"list",items:["Pen for writing","Highlighter for emphasis","Different colors for visibility"]},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_pen_tool.png",alt:"Pen tool menu"},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_pen_tool_drawing.png",alt:"Drawing on slide"},{type:"tip",text:"Use drawing tools to emphasize key data points while speaking—it keeps your audience engaged and focused."}]},{heading:"Using the Laser Pointer",blocks:[{type:"paragraph",text:"The laser pointer allows you to highlight areas without permanently marking the slide."},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_laser_pointer.png",alt:"Laser pointer option"},{type:"paragraph",text:"This is useful when you want to guide attention without adding annotations."}]},{heading:"Presenter View",blocks:[{type:"paragraph",text:"Presenter View allows you to see additional information while your audience only sees the slides."},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_presenter_view.png",alt:"Presenter View"},{type:"paragraph",text:"Presenter View includes tools like a timer, slide previews, notes, and navigation controls."},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_presenter_view_example.png",alt:"Presenter View interface labeled"},{type:"tip",text:"Always use Presenter View when available—it allows you to stay organized and deliver a more professional presentation."}]},{heading:"Setting Up a Slide Show",blocks:[{type:"paragraph",text:"PowerPoint allows you to configure how your presentation behaves using the Set Up Slide Show dialog box."},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_setup_slideshow_ribbon.png",alt:"Set up slideshow button"},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_setup_show_dialog.png",alt:"Set up slideshow dialog"},{type:"paragraph",text:"You can choose presentation type, slide range, and how slides advance."},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_advance_slide_timing.png",alt:"Slide timing settings"}]},{heading:"Completed Presentation Example",blocks:[{type:"paragraph",text:"A well-delivered presentation uses navigation tools, annotations, and Presenter View to guide the audience effectively."},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_final_result.jpeg",alt:"Final presentation example"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which feature allows you to view notes and upcoming slides while the audience sees only the presentation?",options:["Slide Sorter View","Presenter View","Reading View","Outline View"],correctIndex:1,explanation:"Presenter View shows your notes, a timer, and the upcoming slide on your screen while the audience sees only the current slide — which is what lets you speak to the room rather than read the projection.",optionRationales:["Slide Sorter is an editing view showing thumbnails. It is not used while presenting.","Correct. Presenter View gives you notes, timing, and the next slide privately.","Reading View plays the show in a window for your own review, with no separate presenter display.","Outline View shows the text hierarchy for drafting and is not a presentation view."]}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Open the practice presentation.","Start the slide show from the beginning.","Navigate to slide 8.","Use the pen tool to circle key data points.","Switch to Presenter View.","Use the laser pointer to highlight content.","End the slide show properly."]},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_final_result.jpeg",alt:"Final challenge result"}]}],level:"Beginner",estimatedMinutes:30},{moduleNumber:5,moduleSlug:"module-5",title:"Images & Objects",emoji:"\uD83D\uDDBC️",description:"Insert pictures, format images, work with shapes, and align objects to create visually engaging slides.",lessons:[{slug:"inserting-pictures",title:"Inserting Pictures",description:"Learn how to insert pictures from your computer, online sources, screenshots, and screen clippings, then resize and position them on your slides.",objectives:["Insert pictures from your computer, online sources, and screen captures","Use Screen Clipping to capture part of the screen","Choose images that carry meaning rather than decorate","Respect licensing when using images you did not create"],duration:"13 min",videoUrl:"https://www.youtube.com/embed/I-xlLwC4ERc",practiceFiles:[{name:"Inserting Pictures Practice File",url:"/practice/powerpoint/module-5/inserting-pictures/Powerpoint_InsertingPictures_Practice.pptx"}],sections:[{heading:"An image should do a job",blocks:[{type:"scenario",role:"You build a training deck at Lakeside Medical Associates.",text:"You add a stock photo of smiling people in scrubs to every slide because the slides looked bare. None of the photos relate to what the slides say. They add nothing, they cost the audience a moment of attention each time, and the file is now 40 MB.",task:"Use images that carry information, and leave slides alone when they do not need one."},{type:"paragraph",text:"A picture earns its place when it shows something words handle poorly — what a form looks like, where a control sits, how a workflow branches, what a trend does. A screenshot of the actual EHR screen teaches. A stock photo of anonymous clinicians does not."},{type:"callout",variant:"warning",text:"Images found through a web search are not free to use. Most are copyrighted, and using one in materials your organization distributes creates real exposure. Use PowerPoint's built-in stock images, photographs your practice owns, or sources with an explicit license that permits your use — and keep a note of where each came from."},{type:"callout",variant:"warning",text:"Screenshots of clinical systems are a particular risk. Before capturing any screen showing patient data, use a training or demo environment, or fully redact the information — and redact by editing the image itself, not by covering it with a shape. A shape laid over a name in PowerPoint can simply be dragged aside by anyone who opens the file."}]},{heading:"Why Pictures Matter",blocks:[{type:"paragraph",text:"Pictures play a critical role in making presentations more engaging and easier to understand. Instead of relying only on text, visuals help communicate ideas faster and more clearly."},{type:"paragraph",text:"In professional presentations, images are used to reinforce key points, illustrate concepts, and maintain audience attention."},{type:"callout",variant:"info",text:"A strong presentation doesn’t just tell—it shows. Use visuals to support your message, not replace it."}]},{heading:"Inserting a Picture from Your Computer",blocks:[{type:"paragraph",text:"To insert a picture saved on your computer, go to the Insert tab and select Pictures from the Images group."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_insert.png",alt:"Insert Pictures command"},{type:"paragraph",text:"This opens a file browser where you can locate and select your image."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_onedrive_pics.jpeg",alt:"Selecting an image from computer"},{type:"paragraph",text:"Once inserted, the image will appear directly on your slide and can be adjusted as needed."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_inserted_picture.png",alt:"Inserted image on slide"}]},{heading:"Using Content Placeholders",blocks:[{type:"paragraph",text:"Many slide layouts include content placeholders that allow you to insert images quickly without using the Ribbon."},{type:"paragraph",text:"Clicking the picture icon inside the placeholder lets you insert an image while keeping it aligned with the slide layout."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_placeholder_insert.png",alt:"Insert picture from placeholder"},{type:"paragraph",text:"You can also insert online images directly from the placeholder using the Online Pictures icon."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_online_placeholder.png",alt:"Online pictures placeholder icon"}]},{heading:"Inserting Online Pictures",blocks:[{type:"paragraph",text:"If you don’t already have an image saved, PowerPoint allows you to search for pictures online directly within the application."},{type:"paragraph",text:"Go to the Insert tab and select Online Pictures to begin searching."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_online_pics_ribbon.png",alt:"Online Pictures command"},{type:"paragraph",text:"A search window will appear where you can browse categories or type keywords to find specific images."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_online_pictures.jpeg",alt:"Online picture categories"},{type:"paragraph",text:"For example, searching for a topic like 'exercise' or 'healthy food' will return relevant images."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_online_pics_selection.jpeg",alt:"Search results"},{type:"paragraph",text:"Select the image you want and click Insert. PowerPoint will automatically place it on your slide."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_online_displayed.png",alt:"Inserted online picture"},{type:"tip",text:"The more specific your search term, the better your results."}]},{heading:"Resizing, Moving, and Rotating Pictures",blocks:[{type:"paragraph",text:"Once a picture is inserted, you can adjust it to fit your slide layout."},{type:"paragraph",text:"To move an image, click and drag it to a new position."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_move_picture.png",alt:"Moving image"},{type:"paragraph",text:"To resize an image, drag one of the corner handles. This keeps the image proportional."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_resize_picture.png",alt:"Resizing image"},{type:"paragraph",text:"To rotate an image, drag the circular rotation handle above the picture."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_rotate_picture.png",alt:"Rotating image"},{type:"callout",variant:"warning",text:"Avoid stretching images using side handles—this will distort the picture."}]},{heading:"Inserting Screenshots",blocks:[{type:"paragraph",text:"PowerPoint allows you to capture screenshots of open windows directly into your slide."},{type:"paragraph",text:"Go to Insert → Screenshot and choose from available windows."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_screenshot.png",alt:"Screenshot command"},{type:"paragraph",text:"The selected window will be inserted onto your slide."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_screenshot_displayed.png",alt:"Screenshot inserted"}]},{heading:"Using Screen Clipping",blocks:[{type:"paragraph",text:"Screen Clipping allows you to capture a specific portion of your screen instead of an entire window."},{type:"paragraph",text:"Select Screen Clipping, then click and drag to capture only the area you need."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_screen_clipping.png",alt:"Screen clipping tool"},{type:"paragraph",text:"This is especially useful when you want to highlight a specific part of a website or application."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_screen_clipping_displayed.png",alt:"Screen clipping result"}]},{heading:"Completed Slide Examples",blocks:[{type:"paragraph",text:"By combining images, layout positioning, and resizing, you can create visually appealing slides."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_final_result.jpeg",alt:"Final slide example"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which tool allows you to capture only part of your screen?",options:["Screenshot","Screen Clipping","Online Pictures","Insert Object"],correctIndex:1,explanation:"Screen Clipping, on the Screenshot dropdown, dims the screen and lets you drag a rectangle around just the region you want, inserting that area alone.",optionRationales:["Screenshot inserts a whole available window. Screen Clipping is the option on its menu for capturing a region.","Correct. Screen Clipping captures only the part of the screen you drag around.","Online Pictures searches the web for images rather than capturing your own screen.","Insert Object embeds a file or another application's content, which is a different feature."]}]}],challenge:[{type:"paragraph",text:"Download and open the practice presentation."},{type:"list",ordered:!0,items:["Select the last slide.","Use the Online Pictures command to insert a picture of your favorite form of exercise.","Resize your picture so it takes up a majority of the slide without covering the title.","When you're finished, your slide should look something like this:"]},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_challenge_example.jpeg",alt:"Exercise slide result"},{type:"list",ordered:!0,start:6,items:["Insert a new slide with a Title Only layout.","In the Title placeholder, type Learn More at Fitness.gov.","Open https://odphp.health.gov/pcfsn in your browser, then insert a screen clipping of the website onto the slide you just created.","When you're finished, your slide should look something like this:"]},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_final_result.jpeg",alt:"Exercise slide result"}]},{slug:"formatting-pictures",title:"Formatting Pictures",description:"Learn how to enhance and customize images using picture styles, corrections, color adjustments, artistic effects, cropping, and compression tools in PowerPoint.",objectives:["Crop, resize, and adjust images without distorting them","Compress images to control presentation file size","Remove a background to isolate a subject","Add alt text so images are accessible"],duration:"14 min",videoUrl:"https://www.youtube.com/embed/LD52XcAhL3s",practiceFiles:[{name:"Formatting Pictures Practice File",url:"/practice/powerpoint/module-5/formatting-pictures/Powerpoint_FormattingPictures_Practice.pptx"}],sections:[{heading:"Never resize an image by dragging a side handle",blocks:[{type:"scenario",role:"You finish the orientation deck at Lakeside Medical Associates.",text:"You widen a staff photo by dragging the right-hand handle to fill the space. Everyone in the photo is now noticeably stretched. The file is also 60 MB, because eleven phone photos are embedded at full resolution, and it bounces from the practice's email.",task:"Resize proportionally and compress deliberately."},{type:"paragraph",text:"Dragging a side or top handle changes one dimension only, which distorts the image — obvious and unflattering on any photo containing a face. Always drag a corner handle, which preserves the aspect ratio, and hold Shift if you want to be certain."},{type:"paragraph",text:"Compression is the other habit. Picture Format > Compress Pictures reduces embedded images to a resolution appropriate for the output. For a projected presentation, 150 ppi is ample and will typically cut the file size by an order of magnitude. Uncheck 'Apply only to this picture' to compress the whole deck at once."},{type:"callout",variant:"warning",text:"Check 'Delete cropped areas of pictures' when compressing. Cropping only hides the removed region — the pixels remain in the file, and anyone can drag the crop handles back out to reveal them. If you cropped a photo to remove a patient in the background, that person is still in the file until you delete the cropped areas."},{type:"tip",text:"Add alt text to every meaningful image: right-click > Edit Alt Text. Describe what the image conveys rather than what it depicts. Mark purely decorative images as decorative so screen readers skip them."}]},{heading:"Introduction to Formatting Pictures",blocks:[{type:"paragraph",text:"PowerPoint provides a wide range of tools that allow you to enhance and customize your images. These tools help you improve clarity, adjust colors, apply styles, and make your visuals more professional."},{type:"paragraph",text:"All picture formatting tools are located under the Picture Tools Format tab, which appears when you select an image."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_ribbon_command.png",alt:"Picture Tools Format tab"},{type:"callout",variant:"info",text:"Think of formatting as polishing your image—this is where your presentation starts to look professional instead of basic."}]},{heading:"Cropping Pictures",blocks:[{type:"paragraph",text:"Cropping allows you to remove unwanted parts of an image so you can focus on the most important content."},{type:"paragraph",text:"Select your image, go to the Format tab, and click Crop. Drag the black handles to trim the image."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_crop.png",alt:"Crop tool"},{type:"paragraph",text:"Once you’re done adjusting, click Crop again to apply the changes."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_image_adjustments.png",alt:"Cropped image result"}]},{heading:"Cropping to a Shape",blocks:[{type:"paragraph",text:"You can also crop images into shapes to better match your slide design."},{type:"paragraph",text:"Click the Crop dropdown, choose Crop to Shape, and select a shape like a rounded rectangle or circle."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_crop_to_shape.png",alt:"Crop to shape menu"},{type:"paragraph",text:"This instantly transforms your image into the selected shape."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_image_cropped_to_shape.png",alt:"Cropped to shape result"}]},{heading:"Adding Picture Borders",blocks:[{type:"paragraph",text:"Borders help your images stand out and match your presentation’s theme."},{type:"paragraph",text:"Select your image, click Picture Border, then choose a color, thickness, or style."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_picture_border.png",alt:"Picture border options"},{type:"paragraph",text:"You can customize the border to match your slide’s color scheme."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_picture_border_example.png",alt:"Border applied example"}]},{heading:"Image Corrections",blocks:[{type:"paragraph",text:"Corrections allow you to adjust brightness, contrast, and sharpness to improve image clarity."},{type:"paragraph",text:"Use this when your image looks too dark, too bright, or slightly blurry."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_corrections.png",alt:"Corrections menu"}]},{heading:"Adjusting Image Color",blocks:[{type:"paragraph",text:"The Color tool allows you to modify saturation, tone, and recolor your image."},{type:"paragraph",text:"This is useful when you want to match your image with your presentation’s theme or create a specific mood."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_color.png",alt:"Color adjustments"}]},{heading:"Applying Artistic Effects",blocks:[{type:"paragraph",text:"Artistic Effects allow you to transform your image into stylized versions like sketches, paintings, or blur effects."},{type:"paragraph",text:"These are best used sparingly to enhance visual storytelling without distracting your audience."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_artistic_effects.png",alt:"Artistic effects options"}]},{heading:"Using Picture Styles",blocks:[{type:"paragraph",text:"Picture Styles provide quick, pre-designed visual enhancements like frames, shadows, and reflections."},{type:"paragraph",text:"These styles can instantly upgrade the appearance of your image with just one click."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_picture_styles.png",alt:"Picture styles gallery"}]},{heading:"Compressing Pictures",blocks:[{type:"paragraph",text:"Large images can make your presentation file size too big, especially when sharing via email."},{type:"paragraph",text:"PowerPoint allows you to compress images to reduce file size by lowering resolution and removing cropped areas."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_compress_pictures.png",alt:"Compress pictures command"},{type:"paragraph",text:"For sharing presentations, choosing Email resolution creates the smallest file size."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_compress_email.png",alt:"Compression settings"}]},{heading:"Completed Slide Example",blocks:[{type:"paragraph",text:"By combining cropping, styles, borders, and adjustments, you can transform basic images into polished, professional visuals."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_final_result.jpeg",alt:"Final formatted slide"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which tool helps reduce presentation file size?",options:["Picture Styles","Crop","Compress Pictures","Corrections"],correctIndex:2,explanation:"Compress Pictures reduces the resolution of embedded images to what the output actually needs, which is usually the largest single reduction available to a presentation's file size.",optionRationales:["Picture Styles add frames and effects. They change appearance and can slightly increase file size.","Cropping hides part of an image but leaves the hidden pixels in the file unless you also delete cropped areas during compression.","Correct. Compress Pictures lowers embedded image resolution and can discard cropped regions.","Corrections adjusts brightness and sharpness without reducing the stored data."]}]}],challenge:[{type:"paragraph",text:"Download and open the practice presentation."},{type:"list",ordered:!0,items:["On slide 7, select the treadmill picture.","Crop the picture so it's slightly smaller and the treadmills take up a majority of the frame.","Change the style of the picture.","Apply a correction to the picture (for example, increase the brightness).","Compress your picture and choose Email as your target output.","When you're finished, your slide should look something like this:"]},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_final_result.jpeg",alt:"Final challenge result"}]},{slug:"shapes-in-powerpoint",title:"Shapes in PowerPoint",description:"Learn how to insert, format, resize, rotate, and customize shapes to make your slides more visually engaging and professional.",objectives:["Insert, resize, and rotate shapes precisely","Change one shape into another without rebuilding it","Use shape styles consistently across a diagram","Build simple diagrams that explain a process"],duration:"9 min",videoUrl:"https://www.youtube.com/embed/lwBSCkmhwJA",practiceFiles:[{name:"Shapes in PowerPoint Practice File",url:"/practice/powerpoint/module-5/shapes/Powerpoint_Shapes_Practice.pptx"}],sections:[{heading:"Shapes make relationships visible",blocks:[{type:"scenario",role:"You explain the referral workflow at Lakeside Medical Associates.",text:"Described in bullets, the workflow takes three slides and still leaves people unsure where the decision point sits. Drawn as boxes, a diamond, and arrows, it fits on one slide and needs no explanation at all.",task:"Use shapes where the relationship between steps is the actual content."},{type:"paragraph",text:"Diagrams are worth building when structure is the point — a sequence, a branch, a hierarchy. Bullets flatten all of these into a list of equal-looking items, which is exactly what loses the structure."},{type:"table",caption:"Handles on a selected shape",columns:["Handle","Appearance","Does"],rows:[["Sizing","White squares at corners and edges","Resizes — use corners to keep proportions"],["Rotation","Circular arrow above the shape","Rotates; hold Shift for 15\xb0 increments"],["Adjustment","Yellow dot","Changes the shape's proportions, such as an arrow's head size"],["Connection","Gray dots on the outline","Anchors a connector so it follows the shape when moved"]]},{type:"tip",text:"Edit Shape > Change Shape converts an existing shape to a different one while keeping its size, position, text, and formatting. When a rectangle should have been a diamond, this is one command instead of rebuilding and re-styling it."}]},{heading:"Why Shapes Matter",blocks:[{type:"paragraph",text:"Shapes are more than decorative objects. In PowerPoint, they can be used to highlight important ideas, create visual emphasis, build diagrams, and make slides feel more polished and intentional."},{type:"paragraph",text:"A simple shape can help direct attention to key content or add personality to a slide. In this lesson, shapes are used to support a wellness presentation by turning plain slides into more visually appealing ones."},{type:"callout",variant:"info",text:"Shapes are one of the fastest ways to add structure and visual interest to a slide without needing outside graphics."}]},{heading:"Inserting a Shape",blocks:[{type:"paragraph",text:"To insert a shape, go to the Insert tab and click Shapes. PowerPoint includes lines, rectangles, arrows, stars, banners, callouts, and many other built-in shape options."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_select_shape.png",alt:"Shapes menu on the Insert tab in PowerPoint"},{type:"paragraph",text:"After selecting a shape, click and drag on the slide to draw it. The size and proportions of the shape will depend on how far you drag."},{type:"paragraph",text:"In this example, a sun shape is inserted onto the slide as a starting point for a visual callout."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_sizing_shape.png",alt:"A newly inserted sun shape on a PowerPoint slide"}]},{heading:"Resizing and Rotating Shapes",blocks:[{type:"paragraph",text:"Once a shape is inserted, you can resize it using the sizing handles around the border. Drag a corner handle to scale the shape larger or smaller."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_sizing_shape.png",alt:"Resizing a shape in PowerPoint"},{type:"paragraph",text:"To rotate a shape, drag the circular rotation handle above it. This allows you to angle the shape to better fit your design."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_rotate_shape.png",alt:"Rotating a shape in PowerPoint"},{type:"paragraph",text:"Resizing and rotating are basic but important adjustments. Even a simple angle change can make a shape look more dynamic and eye-catching."}]},{heading:"Using the Yellow Adjustment Handle",blocks:[{type:"paragraph",text:"Some shapes include one or more yellow adjustment handles. These allow you to modify the appearance of the shape itself."},{type:"paragraph",text:"For example, with the sun shape, the yellow handle changes the length and spacing of the rays. Other shapes may use this handle to alter corners, arrowheads, banner folds, or other design details."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_yellow_handles.png",alt:"Yellow adjustment handle on a shape in PowerPoint"},{type:"tip",text:"If a shape looks close to what you want but not quite right, check for a yellow handle before replacing it with a different shape."}]},{heading:"Applying Shape Styles",blocks:[{type:"paragraph",text:"PowerPoint includes built-in Shape Styles that instantly apply combinations of fill colors, outlines, and effects."},{type:"paragraph",text:"To use them, select the shape and go to the Drawing Tools Format tab. In the Shape Styles group, choose a preset style from the gallery."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_shape_style.png",alt:"Shape Styles gallery on the Format tab"},{type:"paragraph",text:"Applying a style is a quick way to improve the appearance of a shape without manually adjusting every setting."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_style_selected.png",alt:"A selected style applied to a sun shape"}]},{heading:"Changing Shape Fill",blocks:[{type:"paragraph",text:"Shape Fill controls the interior color or appearance of a shape. You can apply a solid fill, gradient, texture, picture fill, or choose No Fill."},{type:"paragraph",text:"To change the fill, select the shape, go to the Format tab, and click Shape Fill."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_select_color.png",alt:"Shape Fill color options in PowerPoint"},{type:"paragraph",text:"You can use one of the theme colors for consistency, or choose More Fill Colors for additional customization."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_more_fill_colors.png",alt:"More fill color options in PowerPoint"},{type:"paragraph",text:"In this example, changing the fill color helps transform the sun from a simple green shape into a brighter, more attention-grabbing graphic."}]},{heading:"Changing Shape Outline",blocks:[{type:"paragraph",text:"Shape Outline controls the border around a shape. You can change its color, thickness, dashes, or remove it entirely."},{type:"paragraph",text:"To change the outline, select the shape and click Shape Outline on the Format tab."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_formatting_options.png",alt:"Shape Outline menu with color and weight options"},{type:"paragraph",text:"Increasing the outline weight makes the border thicker and more visible. Removing the outline creates a cleaner, flatter look."},{type:"paragraph",text:"In this lesson, outline changes help define the shape and make it coordinate more effectively with the slide theme."}]},{heading:"Applying Shape Effects",blocks:[{type:"paragraph",text:"Shape Effects add visual enhancements such as shadows, glows, reflections, bevels, and 3-D rotation."},{type:"paragraph",text:"To apply an effect, select the shape, go to Shape Effects, and choose the effect you want to use."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_shape_effects.png",alt:"Shape Effects menu in PowerPoint"},{type:"paragraph",text:"Glow effects are especially useful when you want a shape to stand out from the background."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_shape_options.png",alt:"Format Shape pane showing glow options"},{type:"callout",variant:"warning",text:"Effects can make a shape pop, but too many effects at once can make a slide feel cluttered or dated. Use them on purpose."}]},{heading:"Editing and Changing a Shape",blocks:[{type:"paragraph",text:"You are not locked into the original shape you insert. PowerPoint allows you to change a shape into a different one while keeping much of its formatting."},{type:"paragraph",text:"Select the shape, go to Edit Shape, and choose Change Shape. Then select a new shape from the gallery."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_edit_shape.png",alt:"Edit Shape and Change Shape menu in PowerPoint"},{type:"paragraph",text:"This is useful when you like the color, size, and effects you already applied, but want the object to take on a different form."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_new_shape.png",alt:"A changed shape on the slide after using Change Shape"}]},{heading:"Adding Text to a Shape",blocks:[{type:"paragraph",text:"You can type directly inside most shapes. Simply select the shape and start typing, or right-click and choose Edit Text."},{type:"paragraph",text:"Once text is added, you can format it using the usual font, color, size, alignment, and WordArt options."},{type:"paragraph",text:"Adding text makes shapes especially useful for labels, callouts, banners, and highlighted messages on a slide."}]},{heading:"Completed Slide Example",blocks:[{type:"paragraph",text:"After inserting a shape, adjusting its size, rotating it, changing its fill and outline, applying effects, and adding text, the slide becomes much more visually dynamic."},{type:"paragraph",text:"In this example, a plain shape evolves into a bold visual element that reinforces the message of the slide."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_final_result.png",alt:"Completed slide showing a fully formatted shape with text"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which handle allows you to rotate a shape in PowerPoint?",options:["The yellow adjustment handle","The corner sizing handle","The circular rotation handle above the shape","The center point of the shape"],correctIndex:2,explanation:"The circular arrow handle above a selected shape rotates it. Holding Shift while dragging constrains rotation to 15-degree increments.",optionRationales:["The yellow adjustment handle changes a shape's internal proportions, such as the thickness of an arrow.","Corner sizing handles resize the shape while preserving its proportions.","Correct. The circular handle above the shape rotates it.","The center point is not a handle. Dragging inside a shape moves it."]},{type:"knowledge-check",question:"Which command lets you turn one shape into a different shape without starting over?",options:["Shape Fill","Shape Effects","Picture Border","Edit Shape → Change Shape"],correctIndex:3,explanation:"Edit Shape > Change Shape swaps the shape's geometry while preserving its size, position, text, and formatting — so you never have to rebuild and re-style it.",optionRationales:["Shape Fill changes the interior color, not the geometry.","Shape Effects adds shadows and reflections, leaving the shape itself unchanged.","Picture Border applies to pictures rather than shapes.","Correct. Edit Shape > Change Shape converts one shape into another, keeping everything else."]}]}],challenge:[{type:"paragraph",text:"Download and open the practice presentation."},{type:"list",ordered:!0,items:["Select slide 6.","Insert a Folded Corner shape onto the slide.","Rotate the shape so it is slightly angled.","Change the shape fill to a gold or yellow color.","Change the outline settings or remove the outline to improve the appearance.","Apply a shadow or glow effect to make the shape stand out.","Type a short wellness message inside the shape, such as Make stress relief a priority!","Optional: Use Edit Shape → Change Shape to transform the object into a different shape while keeping the formatting."]},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_final_result.png",alt:"Final challenge result for the shapes lesson"}]},{slug:"aligning-grouping-objects",title:"Aligning, Ordering, and Grouping Objects",description:"Learn how to align objects, distribute them evenly, group and ungroup items, control object layering, and rotate objects to create cleaner, more professional slides.",objectives:["Align and distribute objects precisely","Group objects so they move and scale together","Use guides and smart guides for consistent placement","Diagnose why the Group command is sometimes unavailable"],duration:"13 min",videoUrl:"https://www.youtube.com/embed/2GyjYgr-tSM",practiceFiles:[{name:"Aligning & Grouping Practice File",url:"/practice/powerpoint/module-5/aligning-grouping/Powerpoint_Aligning_Practice.pptx"}],sections:[{heading:"Alignment is what the audience notices without noticing",blocks:[{type:"scenario",role:"You finish the workflow diagram at Lakeside Medical Associates.",text:"Five boxes positioned by dragging. Projected at three meters wide, the small misalignments become very visible, and the diagram reads as careless — which is not a good impression for a document describing a clinical process.",task:"Use alignment and distribution so the layout is exact, then group it so it stays that way."},{type:"paragraph",text:"Select several objects and use Shape Format > Align. Align Left puts every left edge on the same coordinate; Distribute Horizontally makes the gaps mathematically equal. Both are exact, and projection magnifies every error that dragging leaves behind."},{type:"paragraph",text:"Group (Ctrl+G) then binds the finished diagram into one object, so moving or resizing it preserves every internal relationship. Without grouping, moving a diagram means moving each piece and re-aligning at the destination."},{type:"callout",variant:"info",text:"If Group is greyed out, the usual cause is that one selected item is a placeholder rather than a free object. Placeholders belong to the layout and cannot be grouped with ordinary shapes. Either build the diagram entirely from inserted shapes, or copy the placeholder's content into a text box first."}]},{heading:"Why Object Arrangement Matters",blocks:[{type:"paragraph",text:"A slide can have great colors, strong images, and useful content, but still look messy if the objects are poorly arranged. In PowerPoint, pictures, shapes, and text boxes can be aligned, spaced, layered, grouped, and rotated so the slide looks intentional instead of random."},{type:"paragraph",text:"This lesson focuses on the arrangement tools that help you clean up your layouts. These tools are especially useful when working with multiple pictures or overlapping objects."},{type:"callout",variant:"info",text:"Design is not only about what you place on a slide. It is also about where you place it and how each object relates to the others."}]},{heading:"Aligning Objects",blocks:[{type:"paragraph",text:"When you move objects manually, PowerPoint displays alignment guides and spacing guides to help you line them up. These guides are useful, but they are not always enough when several objects need to line up perfectly."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_single_object.jpeg",alt:"Pictures on a slide with alignment guides visible"},{type:"paragraph",text:"To align two or more objects, first select them together. Hold the Shift key while clicking each object so PowerPoint knows they should be treated as a set."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_align_two_or_more.jpeg",alt:"Selecting multiple pictures in PowerPoint"},{type:"paragraph",text:"Once the objects are selected, open the Format tab and click the Align command. Then choose Align Selected Objects so PowerPoint aligns the objects relative to one another instead of to the slide itself."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_align_to_slide_option.png",alt:"Align Selected Objects option in PowerPoint"},{type:"paragraph",text:"After that, open the Align menu again and choose one of the six alignment options. These include Align Left, Align Center, Align Right, Align Top, Align Middle, and Align Bottom."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_align_bottom.png",alt:"Align Bottom option in the Align menu"},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_align_middle.png",alt:"Align Middle option in the Align menu"},{type:"paragraph",text:"In this example, the pictures are aligned so they share a consistent position. This immediately makes the slide feel cleaner and easier to read."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_objects_aligned.jpeg",alt:"Objects aligned evenly on a slide"}]},{heading:"Aligning Objects to the Slide",blocks:[{type:"paragraph",text:"Sometimes you do not want objects aligned to each other. Instead, you want them aligned to a specific area of the slide, such as the top, middle, or bottom."},{type:"paragraph",text:"To do this, open the Align menu and switch from Align Selected Objects to Align to Slide."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_align_to_slide_checked.png",alt:"Align to Slide checked in the Align menu"},{type:"paragraph",text:"Once Align to Slide is selected, choose an alignment command such as Align Middle or Align Bottom. PowerPoint will position the selected objects relative to the slide itself."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_objects_middle_aligned.jpeg",alt:"Objects aligned to the middle of the slide"},{type:"paragraph",text:"This is especially helpful when you want several objects to sit neatly across a slide without guessing at their vertical position."},{type:"tip",text:"Use Align Selected Objects when objects should line up with each other. Use Align to Slide when objects should line up with the slide."}]},{heading:"Distributing Objects Evenly",blocks:[{type:"paragraph",text:"Even after objects are aligned, they may still have uneven spacing between them. Distribution commands solve that problem by placing equal distance between each selected object."},{type:"paragraph",text:"If your objects are arranged in a row, use Distribute Horizontally. If they are arranged in a column, use Distribute Vertically."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_distribute_horizontal.png",alt:"Distribute Horizontally option in PowerPoint"},{type:"paragraph",text:"You can use distribution with either Align to Slide or Align Selected Objects, depending on whether the spacing should be based on the full slide or just the selected items."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_objects_distributed.jpeg",alt:"Pictures distributed evenly across a slide"},{type:"paragraph",text:"This is one of the fastest ways to make a row of pictures or icons look professionally arranged."}]},{heading:"Grouping Objects",blocks:[{type:"paragraph",text:"Grouping lets you combine multiple objects into one object. After grouping, the objects can be moved or resized together instead of one at a time."},{type:"paragraph",text:"This is useful when you have finished arranging several objects and want them to stay together as a unit."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_group_ribbon.png",alt:"Group command on the PowerPoint Format tab"},{type:"paragraph",text:"Select the objects you want to group, then go to Format and choose Group. PowerPoint will place a single selection box around the entire set."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_grouped_objects.jpeg",alt:"Objects grouped into one selection box"},{type:"paragraph",text:"Once grouped, the pictures behave like one larger object. You can move them together, resize them together, and rotate them together."},{type:"callout",variant:"warning",text:"Placeholders cannot be grouped. If the Group command is disabled, one or more of the selected items may still be inside a placeholder."},{type:"paragraph",text:"If that happens, reinsert the images using the Pictures command on the Insert tab instead of the placeholder picture icon."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_pictures_command.png",alt:"Pictures command on the Insert tab"}]},{heading:"Ungrouping Objects",blocks:[{type:"paragraph",text:"If you need to edit one object inside a group, you can ungroup the set. This separates the objects so each item can be selected individually again."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_ungroup_command.png",alt:"Ungroup command in PowerPoint"},{type:"paragraph",text:"After ungrouping, the objects return to individual items and can be moved, resized, or reformatted independently."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_objects_ungroupped.jpeg",alt:"Objects after being ungrouped"}]},{heading:"Ordering Objects and Understanding Layers",blocks:[{type:"paragraph",text:"When objects overlap on a slide, their order determines what appears in front and what appears behind. PowerPoint stacks objects in levels based on the order in which they were inserted."},{type:"paragraph",text:"In this example, a large arrow shape sits on top of the pictures. That means it is currently on a higher layer than the images behind it."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_single_object_overlap.jpeg",alt:"Large arrow shape overlapping pictures"},{type:"paragraph",text:"To change the order by one level, select the object and use Bring Forward or Send Backward on the Format tab."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_send_backward.png",alt:"Send Backward command on the Format tab"},{type:"paragraph",text:"This is useful when you want gradual control over layering and only need to move the object one step."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_objects_reordered.jpeg",alt:"Object reordered behind some slide content"}]},{heading:"Sending Objects to the Back and Using the Selection Pane",blocks:[{type:"paragraph",text:"If an object needs to move behind several other objects, it is usually faster to use the drop-down menu and select Send to Back instead of clicking Send Backward multiple times."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_send_to_back.png",alt:"Send to Back option in PowerPoint"},{type:"paragraph",text:"After sending the arrow backward, the pictures become more visible and the design begins to make more sense visually."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_reordered_send_back.jpeg",alt:"Arrow moved behind pictures on a slide"},{type:"paragraph",text:"When several objects overlap, selecting the right one can become difficult. The Selection Pane gives you a list of all objects on the slide so you can select and reorder them more precisely."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_selection_pane.jpeg",alt:"Selection Pane showing slide objects"},{type:"paragraph",text:"This is especially helpful in layered slides where clicking directly on the object is difficult."}]},{heading:"Rotating Objects",blocks:[{type:"paragraph",text:"In addition to aligning and ordering objects, PowerPoint also allows you to rotate them. Rotation is useful when an image or shape needs to face a different direction or better match the design of the slide."},{type:"paragraph",text:"Select the object, go to the Format tab, click Rotate, and choose the option you want. You can rotate left, rotate right, or flip the object horizontally or vertically."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_rotate.jpeg",alt:"Rotate menu in PowerPoint"},{type:"paragraph",text:"In this lesson, the food image is rotated so it better fits the final slide layout and makes the arrangement feel more dynamic."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_object_rotated.jpeg",alt:"Object rotated on the slide"}]},{heading:"Completed Slide Examples",blocks:[{type:"paragraph",text:"Once alignment, distribution, grouping, ordering, and rotation are all working together, the slide becomes much cleaner and easier to follow."},{type:"paragraph",text:"This example shows how orderly spacing and correct layering make the design feel more intentional and professional."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_final_result.jpeg",alt:"Completed final slide after aligning and arranging objects"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which PowerPoint command spaces selected objects evenly across a slide?",options:["Align Middle","Distribute Horizontally","Send Backward","Group"],correctIndex:1,explanation:"Distribute Horizontally makes the horizontal gaps between selected objects equal. It needs at least three objects to be meaningful, since it adjusts the ones between the outermost two.",optionRationales:["Align Middle lines objects up on a shared horizontal axis. It aligns rather than spaces them.","Correct. Distribute Horizontally equalizes the horizontal spacing between the selected objects.","Send Backward changes stacking order, which controls what sits on top of what.","Group combines objects into one unit but does not reposition them."]},{type:"knowledge-check",question:"If the Group command is unavailable, what is a likely reason?",options:["The objects are too large","The file is read-only","One of the selected objects is inside a placeholder","You must rotate the objects first"],correctIndex:2,explanation:"Placeholders belong to the slide layout rather than to the slide, so they cannot be grouped with ordinary shapes. Selecting one alongside free shapes disables Group.",optionRationales:["Object size has no effect on whether Group is available.","A read-only file disables editing altogether, not the Group command specifically.","Correct. A placeholder in the selection prevents grouping, because placeholders belong to the layout.","Rotation is unrelated to grouping."]}]}],challenge:[{type:"paragraph",text:"Download and open the practice presentation."},{type:"list",ordered:!0,items:["On the last slide, select the picture of the hamburger and Rotate Left 90\xb0.","Hold down the Shift key and select all three food pictures. Make sure you do not select the green diamonds.","Check Align to Slide under the Align command, then Align to Middle.","With the pictures still selected, Distribute Horizontally.","Select the first green diamond and send it behind the breakfast picture.","When you're finished, your slide should look like this:"]},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_final_result.jpeg",alt:"Final challenge result for aligning, ordering, and grouping objects"}]}],level:"Beginner",estimatedMinutes:50},{moduleNumber:6,moduleSlug:"module-6",title:"Animations & Multimedia",emoji:"\uD83C\uDFAC",description:"Apply slide transitions, animate text and objects, and embed audio and video into your presentation.",lessons:[{slug:"applying-transitions",title:"Applying Slide Transitions",description:"Learn how to add visual effects between slides, preview transitions, and control timing in PowerPoint.",objectives:["Apply transitions and control their duration","Explain the difference between a transition and an animation","Choose transitions that support rather than distract","Apply a consistent transition across a whole deck"],duration:"9 min",videoUrl:"https://www.youtube.com/embed/Ey1atEavZ-M",practiceFiles:[{name:"Applying Transitions Practice File",url:"/practice/powerpoint/module-6/transitions/Powerpoint_Transitions_Practice.pptx"}],sections:[{heading:"Restraint is the whole skill here",blocks:[{type:"scenario",role:"You present to the board at Lakeside Medical Associates.",text:"You give each slide a different transition — one spins, one checkerboards, one flips in three dimensions. The board remembers the effects and not a single figure. Each transition also adds a second and a half, which across forty slides is a minute of watching animation.",task:"Use one subtle transition throughout, or none at all."},{type:"paragraph",text:"A transition is the effect between slides; an animation is the effect applied to an object on a slide. Both cost attention, and attention is the scarcest thing in a presentation."},{type:"paragraph",text:"The working guidance is: pick one subtle transition — Fade or Push — apply it to every slide with Apply To All, and set the duration to around 0.5 seconds. Consistency makes the transition invisible, which is exactly what you want. Anything the audience notices is competing with your content."},{type:"tip",text:"Reserve a distinct transition for genuine structural breaks — the move from one section to the next. Used sparingly it becomes a signal that the topic is changing, which is real communication rather than decoration."}]},{heading:"What are Slide Transitions?",blocks:[{type:"paragraph",text:"A slide transition is a visual effect that occurs when moving from one slide to the next during a presentation."},{type:"paragraph",text:"Transitions can be simple effects like fading between slides or more dynamic animations that add movement and energy to your presentation."},{type:"paragraph",text:"When used appropriately, transitions can give your presentation a polished and professional appearance."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_subtle.png",alt:"Examples of subtle transitions in PowerPoint"}]},{heading:"Transition Categories",blocks:[{type:"paragraph",text:"PowerPoint groups transitions into three categories: Subtle, Exciting, and Dynamic Content."},{type:"paragraph",text:"Subtle transitions use simple animations and are the most commonly used for professional presentations."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_subtle.png",alt:"Subtle transitions in PowerPoint"},{type:"paragraph",text:"Exciting transitions contain more complex animations. These can add visual interest but should be used sparingly."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_exciting.png",alt:"Exciting transitions in PowerPoint"},{type:"paragraph",text:"Dynamic Content transitions animate only slide elements instead of the entire slide, helping maintain visual continuity between slides."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_dynamic_content.png",alt:"Dynamic content transitions in PowerPoint"}]},{heading:"Applying a Transition",blocks:[{type:"paragraph",text:"Transitions are applied from the Transitions tab on the PowerPoint ribbon."},{type:"paragraph",text:"To apply a transition, first select the slide that you want the transition to appear on."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_desired_slide.png",alt:"Selecting a slide to apply a transition"},{type:"paragraph",text:"Open the Transitions tab and locate the Transition to This Slide group."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_more_dropdown.png",alt:"Transitions gallery in PowerPoint"},{type:"paragraph",text:"Click a transition to apply it to the selected slide. PowerPoint will automatically preview the transition."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_preview_ribbon.png",alt:"Preview transition button in PowerPoint"}]},{heading:"Previewing Transitions",blocks:[{type:"paragraph",text:"You can preview transitions at any time to see how they will appear during your slideshow."},{type:"paragraph",text:"Click the Preview button on the Transitions tab to watch the effect."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_preview_ribbon.png",alt:"Preview button on the transitions tab"},{type:"paragraph",text:"You can also preview the transition by clicking the Play Animations button beside a slide in the slide navigation pane."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_play_animations.png",alt:"Play animations preview in slide pane"}]},{heading:"Applying Transitions to All Slides",blocks:[{type:"paragraph",text:"If you want every slide to use the same transition, you can apply it to all slides at once."},{type:"paragraph",text:"After selecting a transition, click Apply to All in the Timing group."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_apply_to_all.png",alt:"Apply to All button in PowerPoint"}]},{heading:"Changing Transition Effects",blocks:[{type:"paragraph",text:"Some transitions allow you to customize the direction or style of the effect."},{type:"paragraph",text:"Click Effect Options to choose different variations such as From Left, From Right, From Top, or From Bottom."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_effect_options.png",alt:"Effect options menu for transitions"}]},{heading:"Adjusting Duration and Sound",blocks:[{type:"paragraph",text:"You can control how fast a transition plays by adjusting the duration setting."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_duration_timing.png",alt:"Transition duration setting"},{type:"paragraph",text:"PowerPoint also allows you to add sound effects to transitions. However, these should be used sparingly to avoid distracting the audience."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_add_sound.png",alt:"Transition sound options"}]},{heading:"Automatically Advancing Slides",blocks:[{type:"paragraph",text:"Normally slides advance when you click the mouse during a presentation."},{type:"paragraph",text:"You can configure slides to automatically advance after a set amount of time."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_after_timing.png",alt:"Automatic slide timing settings"},{type:"paragraph",text:"This feature is useful for presentations that run automatically, such as kiosk displays or trade show presentations."}]},{heading:"Removing Transitions",blocks:[{type:"paragraph",text:"If you decide you no longer want a transition on a slide, you can remove it easily."},{type:"paragraph",text:"Select the slide, open the Transitions tab, and choose None from the transition gallery."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_remove_transition.png",alt:"Removing a transition in PowerPoint"}]},{heading:"Completed Slideshow Example",blocks:[{type:"paragraph",text:"When transitions are applied consistently and used in moderation, they can improve the flow and professionalism of your presentation."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_final_result.gif",alt:"Example slideshow with transitions applied"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is a slide transition?",options:["An animation that moves text onto a slide","A sound effect that plays during a presentation","A visual effect that plays when moving from one slide to the next","A way to hide certain slides during a presentation"],correctIndex:2,explanation:"A transition is the visual effect that plays as one slide replaces the next. Effects applied to objects on a single slide are animations, which are a separate tab.",optionRationales:["That describes an animation, which applies to an object on a slide.","Transitions can include a sound, but the transition itself is the visual effect between slides.","Correct. A transition plays when moving from one slide to the next.","Hiding slides is done with right-click > Hide Slide and is unrelated to transitions."]}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Open the practice presentation.","Apply the Push transition to the first slide.","Change the Effect Options to push From Right.","Change the transition duration to 2 seconds.","Set slides to automatically advance after 3 seconds.","Click Apply to All."]},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_final_result.gif",alt:"Final slideshow with transitions applied"}]},{slug:"animating-text-and-objects",title:"Animating Text and Objects",description:"Learn how to apply animation effects to text and objects, customize timing, use the Animation Pane, and control the order animations play.",objectives:["Apply entrance, emphasis, and exit animations","Control animation order and start timing","Use the Animation Pane to manage a sequence","Judge when animation clarifies and when it distracts"],duration:"11 min",videoUrl:"",practiceFiles:[{name:"Animations Practice File",url:"/practice/powerpoint/module-6/animations/Powerpoint_Animations_Practice.pptx"}],sections:[{heading:"Animate to control attention, not to decorate",blocks:[{type:"scenario",role:"You explain a four-stage process at Lakeside Medical Associates.",text:"All four stages appear at once and the audience reads ahead to stage four while you are still on stage one. Revealing each stage as you reach it keeps everyone with you — which is the one thing animation genuinely does well.",task:"Use animation to control when information arrives, and leave it alone otherwise."},{type:"paragraph",text:"The legitimate use of animation is sequencing: revealing points as you discuss them so the audience attends to the one you are on. Almost every other use costs attention without returning any."},{type:"table",caption:"Start timing options",columns:["Setting","Plays","Use for"],rows:[["On Click","When you click","Revealing points at your own pace"],["With Previous","At the same time as the previous animation","Two elements that belong together"],["After Previous","Automatically when the previous one finishes","A self-running sequence with no clicking"]]},{type:"callout",variant:"info",text:"The Animation Pane (Animations > Animation Pane) lists every animation on the slide in order, with its trigger and duration. On any slide with more than two animations it is the only practical way to see and reorder the sequence — dragging entries in the pane is far easier than guessing from the numbered markers on the slide."}]},{heading:"What Are Animations?",blocks:[{type:"paragraph",text:"Animations in PowerPoint control how individual objects — text, images, and shapes — appear, move, or disappear on a slide."},{type:"paragraph",text:"Unlike transitions, which affect the entire slide, animations target specific objects. This makes them useful for revealing bullet points one at a time or drawing attention to a key graphic."},{type:"callout",variant:"info",text:"Use animations purposefully. Too many competing effects on a single slide can distract your audience instead of helping them follow along."}]},{heading:"Animation Categories",blocks:[{type:"paragraph",text:"Entrance brings something onto the slide, Emphasis draws attention to something already there, Exit removes it, and Motion Path moves it along a route you draw. Entrance is the one with a legitimate everyday use — revealing points as you discuss them — and the other three are usually decoration."},{type:"list",ordered:!1,items:["Entrance — controls how an object appears on the slide (e.g., Fade, Fly In, Appear).","Emphasis — draws attention to an object that is already visible (e.g., Pulse, Spin, Grow/Shrink).","Exit — controls how an object leaves the slide (e.g., Fade Out, Fly Out).","Motion Paths — moves an object along a defined path on the slide."]},{type:"image",src:"/images/powerpoint/module-6/animations/animations_categories.png",alt:"Four animation categories in PowerPoint"}]},{heading:"Applying an Animation",blocks:[{type:"paragraph",text:"To apply an animation, select an object on the slide and open the Animations tab."},{type:"image",src:"/images/powerpoint/module-6/animations/animations_tab.png",alt:"Animations tab on the PowerPoint ribbon"},{type:"paragraph",text:"Click an effect from the Animation gallery. PowerPoint will immediately preview the animation on your slide."},{type:"image",src:"/images/powerpoint/module-6/animations/animations_gallery.png",alt:"Animation gallery showing entrance, emphasis, and exit effects"},{type:"paragraph",text:"Those badges are the running order, and they do not renumber when you rearrange objects on the slide. If your reveals fire in an order that surprises you during a rehearsal, the badges will show you why."},{type:"image",src:"/images/powerpoint/module-6/animations/animations_number_badge.png",alt:"Animation number badge on a slide object"}]},{heading:"Effect Options",blocks:[{type:"paragraph",text:"Many animations offer additional variations through Effect Options. For example, a text box can fade in all at once, or paragraph by paragraph."},{type:"paragraph",text:"Click Effect Options on the Animations tab to see the available choices for the selected animation."},{type:"image",src:"/images/powerpoint/module-6/animations/animations_effect_options.png",alt:"Effect Options menu for animations"}]},{heading:"The Animation Pane",blocks:[{type:"paragraph",text:"The Animation Pane gives you a detailed list of every animation on the current slide and the order in which they play."},{type:"paragraph",text:"To open it, click Animation Pane on the Animations tab."},{type:"image",src:"/images/powerpoint/module-6/animations/animations_pane_open.png",alt:"Animation Pane open in PowerPoint"},{type:"paragraph",text:"You can drag items up or down in the pane to reorder them, and click the Play All button at the top to preview the full sequence."}]},{heading:"Start, Duration, and Delay",blocks:[{type:"paragraph",text:"Start decides what triggers it: On Click waits for you, With Previous fires alongside the animation before it, and After Previous fires automatically once that one finishes. Duration sets the speed — under half a second for most things, because anything slower makes the audience wait. Delay staggers a sequence without needing extra clicks."},{type:"list",ordered:!1,items:["Start — On Click (default), With Previous (plays at the same time as the animation before it), or After Previous (plays automatically after the previous animation ends).","Duration — how long the animation takes to complete.","Delay — how many seconds to wait before the animation begins."]},{type:"image",src:"/images/powerpoint/module-6/animations/animations_timing_controls.png",alt:"Start, Duration, and Delay timing controls on the Animations tab"},{type:"tip",text:"Set multiple animations to With Previous or After Previous so the sequence plays automatically without requiring extra clicks."}]},{heading:"Reordering Animations",blocks:[{type:"paragraph",text:"To change the order that animations play, select an animation in the Animation Pane and use the Move Earlier or Move Later buttons on the Animations tab."},{type:"image",src:"/images/powerpoint/module-6/animations/animations_reorder.png",alt:"Move Earlier and Move Later buttons for reordering animations"}]},{heading:"Removing an Animation",blocks:[{type:"paragraph",text:"To remove an animation, select the object on the slide or select the animation entry in the Animation Pane, then press the Delete key."},{type:"paragraph",text:"You can also select the object and choose None from the Animation gallery to clear all animations from that object."},{type:"image",src:"/images/powerpoint/module-6/animations/animations_remove.png",alt:"Removing an animation in PowerPoint"}]},{heading:"Completed Slide Example",blocks:[{type:"paragraph",text:"When animations are applied consistently and sequenced correctly, they guide the audience through your content in a controlled and professional way."},{type:"image",src:"/images/powerpoint/module-6/animations/animations_final_result.gif",alt:"Slide demonstrating an animated sequence"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which animation start setting causes an animation to play automatically after the previous one ends?",options:["On Click","With Previous","After Previous","Delayed Start"],correctIndex:2,explanation:"After Previous starts the animation automatically once the preceding one finishes, requiring no click. With Previous starts it simultaneously with the preceding animation instead.",optionRationales:["On Click waits for you to click before playing.","With Previous plays at the same time as the previous animation rather than after it.","Correct. After Previous plays automatically once the preceding animation completes.","There is no 'Delayed Start' option. Delay is a separate timing field applied to any of the three start settings."]}]}],challenge:[{type:"paragraph",text:"Open the practice presentation and complete the following tasks:"},{type:"list",ordered:!0,items:["Select the title text box on slide 2.","Apply the Fly In entrance animation.","Change the Effect Options so the text flies in From Left.","Select the content placeholder on the same slide and apply the Fade entrance animation.","Change the Start setting to After Previous so it plays automatically after the title.","Open the Animation Pane to verify the sequence looks correct.","Preview the animations by clicking Play All."]},{type:"image",src:"/images/powerpoint/module-6/animations/animations_final_result.gif",alt:"Final animated slide result"}]},{slug:"working-with-audio",title:"Working with Audio",description:"Learn how to insert audio files into your presentation, control playback settings, trim audio clips, and configure music to play across multiple slides.",objectives:["Insert audio and control how it plays","Set audio to continue across multiple slides","Hide the audio icon during a show","Consider accessibility when a presentation relies on sound"],duration:"8 min",videoUrl:"",practiceFiles:[{name:"Working with Audio Practice File",url:"/practice/powerpoint/module-6/audio/Powerpoint_Audio_Practice.pptx"}],sections:[{heading:"Audio that stops at the slide boundary",blocks:[{type:"scenario",role:"You build a self-running display for the waiting room at Lakeside Medical Associates.",text:"You add background music to the first slide. It stops the moment the deck advances, because by default audio belongs to the slide it was inserted on.",task:"Configure audio playback so it behaves the way the presentation requires."},{type:"paragraph",text:"Select the audio icon and use the Playback tab. 'Play Across Slides' lets it continue as the deck advances; 'Loop until Stopped' repeats it; 'Hide During Show' removes the speaker icon from view. For a looping waiting-room display you generally want all three."},{type:"callout",variant:"warning",text:"Never let audio be the only way information is conveyed. Deaf and hard-of-hearing viewers, and anyone watching with the sound off — which is most people in a waiting room — receive nothing. Any narration needs on-screen text carrying the same content. Music must be licensed for the use; commercial recordings are not free to play in a public waiting area."}]},{heading:"Why Add Audio to a Presentation?",blocks:[{type:"paragraph",text:"Audio is worth adding for narration on a self-running deck and rarely worth it in a live presentation, where you are the narration. Two constraints apply whatever the use: any information carried by audio must also appear on screen, because deaf and hard-of-hearing viewers and anyone with the sound off receive none of it; and music must be licensed for the setting, since commercial recordings are not free to play in a waiting room or a classroom."},{type:"paragraph",text:"Common uses include background music for kiosk displays, recorded narration for self-running presentations, and sound cues that accompany specific slides."},{type:"callout",variant:"warning",text:"Use audio with purpose. Background music or sounds that don't match your content can distract your audience."}]},{heading:"Inserting Audio from Your Computer",blocks:[{type:"paragraph",text:"To add an audio file, go to the Insert tab and select Audio, then choose Audio on My PC."},{type:"image",src:"/images/powerpoint/module-6/audio/audio_insert_ribbon.png",alt:"Audio command on the Insert tab"},{type:"paragraph",text:"Browse to and select your audio file. PowerPoint supports common formats including MP3 and WAV."},{type:"paragraph",text:"After inserting, a speaker icon appears on the slide along with a small audio player bar."},{type:"image",src:"/images/powerpoint/module-6/audio/audio_icon_on_slide.png",alt:"Audio speaker icon and player bar on a slide"}]},{heading:"The Audio Format and Playback Tabs",blocks:[{type:"paragraph",text:"When the audio icon is selected, two new tabs appear on the ribbon: Audio Format and Playback."},{type:"paragraph",text:"The Playback tab is where you configure most audio settings including start behavior, looping, and volume."},{type:"image",src:"/images/powerpoint/module-6/audio/audio_playback_tab.png",alt:"Playback tab for audio in PowerPoint"}]},{heading:"Playback Settings",blocks:[{type:"paragraph",text:"Audio stops when the slide changes unless you also turn on Play Across Slides on the Playback tab. That is the setting people miss when background music cuts out one slide in — the file is fine, it simply belongs to the slide it was inserted on."},{type:"image",src:"/images/powerpoint/module-6/audio/audio_start_options.png",alt:"Audio start options in PowerPoint"},{type:"list",ordered:!1,items:["In Click Sequence — audio plays when you reach it during your click sequence.","Automatically — audio starts as soon as the slide appears.","When Clicked On — audio only plays when the audience clicks the icon."]},{type:"paragraph",text:"You can also enable Loop until Stopped to repeat the audio continuously, and Hide During Show to keep the speaker icon invisible during the presentation."},{type:"image",src:"/images/powerpoint/module-6/audio/audio_loop_hide.png",alt:"Loop until Stopped and Hide During Show options"}]},{heading:"Playing Audio Across Slides",blocks:[{type:"paragraph",text:"By default, audio stops when you move to the next slide. To have music continue across multiple slides, check Play Across Slides in the Playback tab."},{type:"image",src:"/images/powerpoint/module-6/audio/audio_play_across_slides.png",alt:"Play Across Slides option in PowerPoint"},{type:"tip",text:"Combine Play Across Slides with Hide During Show and Loop until Stopped for seamless background music throughout a presentation."}]},{heading:"Trimming Audio",blocks:[{type:"paragraph",text:"Trimming in PowerPoint is non-destructive: it changes the start and end points used during playback and leaves the original file whole, so you can always widen the trim again. It does not shrink the file, though — the untrimmed audio is still embedded, which matters when you are emailing the deck."},{type:"paragraph",text:"Click Trim Audio on the Playback tab. Drag the green start marker and red end marker to define the portion you want to keep."},{type:"image",src:"/images/powerpoint/module-6/audio/audio_trim_dialog.png",alt:"Trim Audio dialog with start and end markers"},{type:"paragraph",text:"Click OK to apply the trim. The audio clip will now start and stop at the points you selected."}]},{heading:"Adjusting Volume",blocks:[{type:"paragraph",text:"Use the Volume button on the Playback tab to set the default playback level to Low, Medium, High, or Mute."},{type:"image",src:"/images/powerpoint/module-6/audio/audio_volume_control.png",alt:"Volume control on the Playback tab"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which setting keeps audio playing as you advance through multiple slides?",options:["Loop until Stopped","Hide During Show","Play Across Slides","When Clicked On"],correctIndex:2,explanation:"Play Across Slides lets the audio continue as the presentation advances, instead of stopping when the slide it belongs to is replaced.",optionRationales:["Loop until Stopped repeats the clip, but it still stops when the slide changes unless Play Across Slides is also set.","Hide During Show only conceals the speaker icon. It has no effect on playback.","Correct. Play Across Slides keeps the audio playing as you move between slides.","When Clicked On means the audio starts on a click rather than automatically."]}]}],challenge:[{type:"paragraph",text:"Open the practice presentation and complete the following tasks:"},{type:"list",ordered:!0,items:["Insert an audio file onto slide 1 using Audio on My PC.","Set the Start option to Automatically.","Enable Play Across Slides so the music continues as you advance slides.","Enable Hide During Show so the speaker icon is not visible during the presentation.","Enable Loop until Stopped.","Use Trim Audio to shorten the clip to approximately 30 seconds.","Preview your presentation from slide 1 to confirm the audio plays correctly."]}]},{slug:"working-with-video",title:"Working with Video",description:"Learn how to insert videos from your computer or online, control playback settings, trim clips, and format the video frame on your slides.",objectives:["Insert video from a file or an online source","Trim a video and set a poster frame","Control playback options","Prepare video so it works on another machine"],duration:"10 min",videoUrl:"",practiceFiles:[{name:"Working with Video Practice File",url:"/practice/powerpoint/module-6/video/Powerpoint_Video_Practice.pptx"}],sections:[{heading:"Video is where presentations fail on unfamiliar hardware",blocks:[{type:"scenario",role:"You present a training deck at Lakeside Medical Associates.",text:"Your video plays perfectly at your desk. On the conference room machine the slide shows a black rectangle, because the deck was linked to a file still sitting on your computer, and the guest network cannot reach the online copy either.",task:"Embed and optimize media so the deck is genuinely self-contained."},{type:"paragraph",text:"Video inserted from your PC is embedded in the file, which is what makes the deck portable — at the cost of size. Online video is linked, so it needs a working connection and an unblocked site at presentation time. Conference room networks frequently block video platforms."},{type:"paragraph",text:"A poster frame is the still image shown before the video plays. By default it is the first frame, which is often black. Playback > Poster Frame lets you choose a meaningful frame, so the slide looks intentional rather than broken while you introduce it."},{type:"callout",variant:"warning",text:"Before presenting from another machine, run File > Info > Optimize Media Compatibility. It embeds and re-encodes media into formats that play reliably elsewhere. Then test the deck on the actual presentation machine — media is the most common single point of failure in a presentation, and it fails silently until you are standing in front of people."}]},{heading:"Why Embed Video in a Presentation?",blocks:[{type:"paragraph",text:"Videos can make a presentation far more engaging than static slides. A short clip can demonstrate a process, share a testimonial, or show a product in action."},{type:"paragraph",text:"Embedding video directly into your presentation keeps everything in one file, so you don't need to switch applications during a live presentation."},{type:"callout",variant:"info",text:"Keep embedded videos short. Long clips can increase file size significantly and may slow down your presentation."}]},{heading:"Inserting Video from Your Computer",blocks:[{type:"paragraph",text:"Go to the Insert tab, click Video, then select This Device."},{type:"image",src:"/images/powerpoint/module-6/video/video_insert_ribbon.png",alt:"Video command on the Insert tab"},{type:"paragraph",text:"Browse to your video file and click Insert. PowerPoint supports common formats including MP4, MOV, and AVI."},{type:"paragraph",text:"The video appears on the slide as a preview image with a playback bar beneath it."},{type:"image",src:"/images/powerpoint/module-6/video/video_on_slide.png",alt:"Inserted video on a slide with playback bar"}]},{heading:"Inserting an Online Video",blocks:[{type:"paragraph",text:"You can also embed a video from an online source such as YouTube without downloading it first."},{type:"paragraph",text:"Go to Insert → Video → Online Video. Paste the video URL into the search box and click Insert."},{type:"image",src:"/images/powerpoint/module-6/video/video_online_insert.png",alt:"Online Video dialog in PowerPoint"},{type:"callout",variant:"warning",text:"Online videos require an internet connection during your presentation. If connectivity is uncertain, use a locally saved video file instead."}]},{heading:"The Video Format and Playback Tabs",blocks:[{type:"paragraph",text:"When a video is selected, the Video Format and Playback tabs appear on the ribbon."},{type:"paragraph",text:"Video Format lets you apply styles, adjust borders, and crop the video frame. Playback controls how the video behaves during the presentation."},{type:"image",src:"/images/powerpoint/module-6/video/video_playback_tab.png",alt:"Playback tab for video in PowerPoint"}]},{heading:"Playback Settings",blocks:[{type:"paragraph",text:"The Start setting works the same as audio — In Click Sequence, Automatically, or When Clicked On."},{type:"paragraph",text:"Additional useful options include:"},{type:"list",ordered:!1,items:["Play Full Screen — expands the video to fill the entire screen during playback.","Hide While Not Playing — hides the video frame until it starts playing.","Loop until Stopped — repeats the video continuously.","Rewind after Playing — returns the video to the first frame when it ends."]},{type:"image",src:"/images/powerpoint/module-6/video/video_playback_options.png",alt:"Video playback options in PowerPoint"}]},{heading:"Trimming Video",blocks:[{type:"paragraph",text:"To use only part of a video, click Trim Video on the Playback tab."},{type:"image",src:"/images/powerpoint/module-6/video/video_trim_ribbon.png",alt:"Trim Video button on the Playback tab"},{type:"paragraph",text:"Drag the green start marker and the red end marker to define the clip you want to keep, then click OK."},{type:"image",src:"/images/powerpoint/module-6/video/video_trim_dialog.png",alt:"Trim Video dialog with start and end markers"},{type:"tip",text:"Trimming is non-destructive — the original video file is not modified. You can re-open the dialog and adjust the markers at any time."}]},{heading:"Adding a Video Poster Frame",blocks:[{type:"paragraph",text:"A poster frame is the still image shown on the video before it plays. By default, PowerPoint shows the first frame."},{type:"paragraph",text:"To set a custom poster frame, play the video to the frame you want, pause it, then click Poster Frame → Current Frame on the Video Format tab."},{type:"image",src:"/images/powerpoint/module-6/video/video_poster_frame.png",alt:"Poster Frame options on the Video Format tab"}]},{heading:"Formatting the Video Frame",blocks:[{type:"paragraph",text:"Just like images, videos can be styled with borders, shadows, and reflections using the Video Styles gallery on the Video Format tab."},{type:"image",src:"/images/powerpoint/module-6/video/video_styles_gallery.png",alt:"Video Styles gallery on the Video Format tab"},{type:"paragraph",text:"You can also resize and reposition the video frame on the slide the same way you would resize an image."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is a video poster frame?",options:["The final frame that plays when the video ends","The still image displayed on the video before it plays","A picture inserted behind the video on the slide","A style applied to the video border"],correctIndex:1,explanation:"The poster frame is the still image displayed on the slide before the video plays. Setting a meaningful one avoids the black rectangle that the default first frame often produces.",optionRationales:["The final frame is simply where playback ends. It is not a separate setting.","Correct. The poster frame is the still image shown before playback begins.","A picture placed behind the video would be a separate object on the slide.","Border styling is applied from Video Format. The poster frame is the preview image."]}]}],challenge:[{type:"paragraph",text:"Open the practice presentation and complete the following tasks:"},{type:"list",ordered:!0,items:["On slide 3, insert a video from your computer.","Resize and reposition the video so it fits neatly within the slide content area.","Set the Start option to Automatically.","Enable Rewind after Playing.","Use Trim Video to remove the first 5 seconds and last 5 seconds of the clip.","Apply a video style from the Video Format tab to give the frame a polished appearance.","Set a poster frame using a frame from inside the clip.","Preview the slide to confirm the video plays and rewinds correctly."]}]}],level:"Intermediate",estimatedMinutes:38},{moduleNumber:7,moduleSlug:"module-7",title:"Tables, Charts & SmartArt",emoji:"\uD83D\uDCCA",description:"Create and format tables, insert data-driven charts, and build professional diagrams using SmartArt.",lessons:[{slug:"inserting-tables",title:"Inserting Tables",description:"Learn how to create and insert tables in PowerPoint, add and remove rows and columns, merge cells, and apply table styles to organize data clearly.",objectives:["Insert and format a table on a slide","Navigate a table and add rows efficiently","Use table style options to aid reading","Judge when a table belongs on a slide at all"],duration:"10 min",videoUrl:"",practiceFiles:[{name:"Tables Practice File",url:"/practice/powerpoint/module-7/tables/Powerpoint_Tables_Practice.pptx"}],sections:[{heading:"Most tables do not belong on a slide",blocks:[{type:"scenario",role:"You present budget figures at Lakeside Medical Associates.",text:"You paste a twelve-column, thirty-row table from Excel onto a slide. At the back of the room it is a gray texture. Nobody reads a single figure, and the two numbers that actually mattered are lost among four hundred that did not.",task:"Put the few figures that matter on the slide, and give the full table out as a handout."},{type:"paragraph",text:"A slide is glanced at from a distance. A table with more than about five columns and six rows exceeds what that allows. If the audience needs the full data set, it belongs in a handout or an appendix — and the slide should carry the three numbers your point actually rests on."},{type:"tip",text:"Banded rows are the highest-value table formatting on a slide: alternating shading lets the eye track across a row without losing its place, which matters much more at a distance than up close. Turn on Header Row as well, so the labels are visibly distinct from the data."}]},{heading:"When to Use Tables",blocks:[{type:"paragraph",text:"Tables are useful whenever you need to present structured data in rows and columns — schedules, comparison charts, pricing tiers, contact lists, and similar content."},{type:"paragraph",text:"A well-formatted table helps an audience absorb organized information quickly without requiring them to read through long paragraphs."},{type:"callout",variant:"info",text:"Keep tables simple. Avoid cramming so much data into a table that it becomes difficult to read at presentation size."}]},{heading:"Inserting a Table",blocks:[{type:"paragraph",text:"Go to the Insert tab and click Table. A grid appears where you can drag to choose the number of columns and rows you need."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_insert_grid.png",alt:"Table insertion grid on the Insert tab"},{type:"paragraph",text:"Release the mouse to insert the table. PowerPoint places it on the slide and opens the Table Design and Layout tabs."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_inserted.png",alt:"Blank table inserted on a slide"},{type:"tip",text:"If you need more rows or columns than the grid allows, select Insert Table from the Table menu to enter exact numbers."}]},{heading:"Entering and Navigating Table Content",blocks:[{type:"paragraph",text:"Click inside any cell to begin typing. Press Tab to move to the next cell, or Shift+Tab to move backwards."},{type:"paragraph",text:"Pressing Tab in the last cell of the last row automatically adds a new row to the table."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_data_entered.png",alt:"Table with data entered across multiple cells"}]},{heading:"Adding and Removing Rows and Columns",blocks:[{type:"paragraph",text:"To add a row or column, click inside the table near where you want to insert. Then open the Layout tab and use the Insert Above, Insert Below, Insert Left, or Insert Right buttons."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_insert_row_col.png",alt:"Insert row and column options on the Layout tab"},{type:"paragraph",text:"To delete a row or column, click inside it, then use the Delete Rows or Delete Columns button on the Layout tab."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_delete_row_col.png",alt:"Delete row and column options on the Layout tab"}]},{heading:"Merging and Splitting Cells",blocks:[{type:"paragraph",text:"Merging combines multiple adjacent cells into a single cell. This is commonly used for header rows that span all columns."},{type:"paragraph",text:"Select the cells you want to merge, then click Merge Cells on the Layout tab."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_merge_cells.png",alt:"Merge Cells button on the Layout tab"},{type:"paragraph",text:"To reverse a merge, select the merged cell and click Split Cells. Enter the number of rows and columns you want to split it into."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_split_cells.png",alt:"Split Cells dialog in PowerPoint"}]},{heading:"Resizing Columns and Rows",blocks:[{type:"paragraph",text:"You can resize columns and rows by dragging the border between cells. Position your cursor over the border until it changes to a resize arrow, then drag."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_resize_column.png",alt:"Resizing a table column by dragging"},{type:"paragraph",text:"For precise sizing, enter exact values in the Width and Height fields on the Layout tab."},{type:"paragraph",text:"Use Distribute Columns or Distribute Rows on the Layout tab to make all columns or rows the same size instantly."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_distribute.png",alt:"Distribute Rows and Columns options"}]},{heading:"Applying Table Styles",blocks:[{type:"paragraph",text:"The Table Design tab offers a gallery of pre-built styles that apply colors, shading, and borders matching your presentation's theme."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_style_gallery.png",alt:"Table Design style gallery in PowerPoint"},{type:"paragraph",text:"Use the Table Style Options checkboxes — such as Header Row, Banded Rows, and Total Row — to emphasize specific parts of the table."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_style_options.png",alt:"Table Style Options checkboxes"}]},{heading:"Aligning Text in Cells",blocks:[{type:"paragraph",text:"Text inside table cells can be aligned horizontally (left, center, right) and vertically (top, middle, bottom) using the alignment buttons on the Layout tab."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_text_alignment.png",alt:"Text alignment options on the Table Layout tab"},{type:"tip",text:"Center-aligning text both horizontally and vertically in header cells gives tables a cleaner, more polished look."}]},{heading:"Completed Table Example",blocks:[{type:"paragraph",text:"A formatted table with a styled header row, banded rows, and properly aligned content is much easier to read during a presentation than raw data."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_final_result.png",alt:"Completed and formatted table on a slide"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What happens when you press Tab in the last cell of a table?",options:["The table is deselected","A new column is inserted to the right","The cursor moves back to the first cell","A new row is added at the bottom of the table"],correctIndex:3,explanation:"Tab in the last cell adds a new row and moves the cursor into it, so you can keep typing without deciding the row count in advance.",optionRationales:["The table stays selected and active.","Tab never adds columns; columns are added from the Table Layout tab.","That is what Ctrl+Home does. Tab moves forward.","Correct. A new row is added at the bottom and the cursor moves into it."]},{type:"knowledge-check",question:"Which Table Style Option emphasizes alternating rows with different shading?",options:["Header Row","Total Row","Banded Rows","First Column"],correctIndex:2,explanation:"Banded Rows applies alternating shading to rows, which helps the eye track across a row — particularly valuable when the table is being read from a distance.",optionRationales:["Header Row formats the first row distinctly as column labels.","Total Row emphasizes a summary row at the bottom.","Correct. Banded Rows shades alternate rows to aid horizontal tracking.","First Column emphasizes the leftmost column, usually the row labels."]}]}],challenge:[{type:"paragraph",text:"Open the practice presentation and complete the following tasks:"},{type:"list",ordered:!0,items:["Insert a new slide with a Title and Content layout.","Add the title: Quarterly Schedule.","Insert a table with 4 columns and 5 rows.","Type Quarter, Region, Sales Rep, and Status as the header row content.","Fill in at least three more rows with sample data.","Merge the top-left cell with the cell to its right to create a wide header.","Apply a table style that includes banded rows.","Distribute the columns evenly so they are all the same width.","When finished, your table should look organized and easy to read at presentation size."]},{type:"image",src:"/images/powerpoint/module-7/tables/tables_final_result.png",alt:"Completed table challenge result"}]},{slug:"inserting-charts",title:"Inserting Charts",description:"Learn how to insert charts into PowerPoint, choose the right chart type, edit chart data, and format your chart to communicate information visually.",objectives:["Insert a chart and edit its underlying data","Choose a chart type that answers the audience's question","Simplify a chart so it reads from the back of a room","Update a chart when the source figures change"],duration:"11 min",videoUrl:"",practiceFiles:[{name:"Charts Practice File",url:"/practice/powerpoint/module-7/charts/Powerpoint_Charts_Practice.pptx"}],sections:[{heading:"A presentation chart needs to be simpler than a report chart",blocks:[{type:"scenario",role:"You present spending trends at Lakeside Medical Associates.",text:"You paste the chart from your Excel report: eight series, gridlines, a legend on the right, and axis labels at nine point. In the report, where a reader can study it, it works. Projected, it is a colored tangle.",task:"Rebuild the chart for a glance from six meters away, not for a reader at a desk."},{type:"paragraph",text:"A report chart is read; a presentation chart is glanced at. That difference means fewer series — two or three, not eight — larger type, no gridlines, and direct labels on the lines rather than a legend the eye has to travel to and match by color."},{type:"table",caption:"Choosing a chart type",columns:["The question","Chart"],rows:[["How did this change over time?","Line"],["How do these categories compare?","Column or bar"],["What share of the whole is each part?","Pie, five or fewer slices"],["Are these two measures related?","Scatter"]]},{type:"callout",variant:"warning",text:"Start a column chart's value axis at zero. Readers judge bar length, so a truncated axis makes a small difference look dramatic. Presenting a misleading chart damages your credibility even when the distortion was accidental — and it usually is."}]},{heading:"Why Use Charts in Presentations?",blocks:[{type:"paragraph",text:"Charts transform raw numbers into visuals that are far easier to interpret at a glance. A bar chart comparing sales figures communicates instantly what a table of numbers takes time to process."},{type:"paragraph",text:"In professional presentations, charts are among the most effective tools for presenting data-driven arguments and trends."},{type:"callout",variant:"info",text:"Choose your chart type based on what you want to communicate, not just what looks interesting. The wrong chart type can mislead your audience."}]},{heading:"Common Chart Types",blocks:[{type:"paragraph",text:"PowerPoint includes many chart types. These are the most commonly used in business presentations:"},{type:"list",ordered:!1,items:["Column and Bar — compare values across categories. Column charts are vertical; bar charts are horizontal.","Line — show trends over time. Best when data has a clear sequence like months or years.","Pie — show proportions of a whole. Use only when you have a small number of categories.","Area — similar to line charts but filled with color, emphasizing volume."]},{type:"image",src:"/images/powerpoint/module-7/charts/charts_types_overview.png",alt:"Common chart types in PowerPoint"}]},{heading:"Inserting a Chart",blocks:[{type:"paragraph",text:"Go to the Insert tab and click Chart."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_insert_ribbon.png",alt:"Chart command on the Insert tab"},{type:"paragraph",text:"The Insert Chart dialog opens. Choose a chart type from the left panel and select a specific subtype from the top row, then click OK."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_insert_dialog.png",alt:"Insert Chart dialog with chart types"},{type:"paragraph",text:"A sample chart appears on your slide alongside a small Excel-style spreadsheet where you enter your actual data."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_data_sheet.png",alt:"Sample chart and data spreadsheet side by side"}]},{heading:"Editing Chart Data",blocks:[{type:"paragraph",text:"Replace the placeholder data in the spreadsheet with your own numbers. The chart on the slide updates automatically as you type."},{type:"paragraph",text:"Column headers become the chart's legend labels. Row headers become the category labels along the axis."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_data_entered.png",alt:"Updated chart data and resulting chart"},{type:"paragraph",text:"Close the spreadsheet when you're done. To edit the data again later, right-click the chart and select Edit Data."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_edit_data_menu.png",alt:"Edit Data option in the right-click menu"}]},{heading:"Chart Design and Format Tabs",blocks:[{type:"paragraph",text:"When a chart is selected, the Chart Design and Format tabs appear on the ribbon. These tabs contain all chart customization tools."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_design_tab.png",alt:"Chart Design tab on the PowerPoint ribbon"}]},{heading:"Applying a Chart Style",blocks:[{type:"paragraph",text:"The Chart Design tab includes a Chart Styles gallery with pre-built color and shading combinations that coordinate with your theme."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_style_gallery.png",alt:"Chart Styles gallery on the Chart Design tab"},{type:"paragraph",text:"Click Change Colors to select a different color palette for your chart's data series."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_change_colors.png",alt:"Change Colors options for a chart"}]},{heading:"Changing the Chart Layout",blocks:[{type:"paragraph",text:"Quick Layouts on the Chart Design tab let you change what elements appear on the chart — such as the title, legend, gridlines, and data labels."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_quick_layout.png",alt:"Quick Layout options on the Chart Design tab"},{type:"paragraph",text:"You can also use Add Chart Element to turn individual elements on or off, such as axis titles, data labels, and the legend."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_add_element.png",alt:"Add Chart Element menu"}]},{heading:"Changing the Chart Type",blocks:[{type:"paragraph",text:"If you decide that a different chart type would represent your data better, you don't have to start over."},{type:"paragraph",text:"Click Change Chart Type on the Chart Design tab, select the new type, and click OK. Your data transfers to the new chart format."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_change_type.png",alt:"Change Chart Type option on the Chart Design tab"}]},{heading:"Completed Chart Example",blocks:[{type:"paragraph",text:"A well-chosen chart type with a matching style and clear labels can make even complex data easy to understand at a glance."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_final_result.png",alt:"Completed formatted chart on a slide"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which chart type is best suited for showing a trend over a period of time?",options:["Pie","Column","Line","Scatter"],correctIndex:2,explanation:"A line chart shows change over a continuous period. The connecting line is read as continuity, which makes the shape of the trend immediately visible.",optionRationales:["Pie charts show composition at one moment and cannot express change over time.","Column charts compare discrete categories well and can show time, but a line expresses a continuous trend more directly.","Correct. Line charts show trends over time.","Scatter charts show the relationship between two measures rather than a trend over time."]},{type:"knowledge-check",question:"How do you update the data in a chart after it has been inserted?",options:["Delete the chart and insert a new one","Right-click the chart and select Edit Data","Use the Format tab to enter new values","Double-click the chart legend"],correctIndex:1,explanation:"Right-clicking the chart and choosing Edit Data opens the embedded worksheet holding the chart's values. Change them there and the chart redraws immediately.",optionRationales:["Deleting and rebuilding discards all your formatting for no reason.","Correct. Edit Data opens the underlying worksheet.","The Format tab styles the chart's appearance; it does not hold the values.","Double-clicking the legend opens legend formatting options."]}]}],challenge:[{type:"paragraph",text:"Open the practice presentation and complete the following tasks:"},{type:"list",ordered:!0,items:["Insert a new slide with a Title and Content layout.","Add the title: Regional Sales — Q1.","Insert a Clustered Column chart.","Replace the placeholder data with four regions (North, South, East, West) and their sales figures.","Close the data spreadsheet.","Apply a chart style that uses your theme colors.","Use Add Chart Element to add data labels above each column.","Remove the chart legend since the data labels make it redundant.","Review the result and ensure the chart is clearly readable at slide size."]},{type:"image",src:"/images/powerpoint/module-7/charts/charts_final_result.png",alt:"Completed chart challenge result"}]},{slug:"using-smartart",title:"Using SmartArt",description:"Learn how to insert SmartArt graphics, choose the right layout for your content, add and edit text, and apply styles to create professional diagrams.",objectives:["Insert SmartArt and choose a category that fits the relationship","Add and reorder items using the Text Pane","Convert bullet lists into SmartArt","Recognize when SmartArt clarifies and when it merely decorates"],duration:"9 min",videoUrl:"",practiceFiles:[{name:"SmartArt Practice File",url:"/practice/powerpoint/module-7/smartart/Powerpoint_SmartArt_Practice.pptx"}],sections:[{heading:"SmartArt is only useful when the shape means something",blocks:[{type:"scenario",role:"You present the referral process at Lakeside Medical Associates.",text:"Six sequential steps as bullets read as six equal items. The same six in a Process graphic show direction, order, and where the flow branches — the structure becomes visible rather than merely stated.",task:"Choose the SmartArt category that matches the actual relationship in your content."},{type:"paragraph",text:"SmartArt builds a diagram from text you type, keeping every element aligned and consistently styled. Its value is that the layout carries meaning — but only if you choose the category that matches your content's real structure. A Cycle graphic applied to a linear process tells the audience something untrue."},{type:"table",caption:"SmartArt categories",columns:["Category","Shows","Use for"],rows:[["Process","A sequence with direction","Steps in a workflow"],["Cycle","A repeating loop","A process that genuinely returns to its start"],["Hierarchy","Levels of reporting or containment","Org charts, classification"],["Relationship","Connection between items","Overlaps, opposing forces"],["Matrix","Parts of a whole in quadrants","Two-axis categorization"],["List","Grouped items, no sequence","Bullets that need visual grouping"]]},{type:"tip",text:"Type in the Text Pane rather than clicking each shape. Enter adds an item, Tab demotes it, Shift+Tab promotes it — and SmartArt re-lays out and resizes everything automatically. Building a diagram this way takes a fraction of the time of positioning shapes by hand."}]},{heading:"What is SmartArt?",blocks:[{type:"paragraph",text:"SmartArt lets you transform a list of items into a professional-looking diagram without any design experience."},{type:"paragraph",text:"Instead of placing text and shapes manually, SmartArt handles the layout automatically. You just choose a structure and type your content."},{type:"callout",variant:"info",text:"SmartArt works best when your content has a clear relationship — a sequence of steps, a hierarchy, a cycle, or a set of interconnected ideas."}]},{heading:"SmartArt Categories",blocks:[{type:"paragraph",text:"PowerPoint organizes SmartArt layouts into categories based on the type of relationship they represent."},{type:"list",ordered:!1,items:["List — unordered or grouped items without a directional flow.","Process — steps in a sequence or workflow.","Cycle — a repeating process with no defined start or end.","Hierarchy — org charts and tree structures.","Relationship — connections and overlapping concepts, including Venn diagrams.","Matrix — how parts relate to a whole across two axes.","Pyramid — proportional or foundational relationships."]},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_categories.png",alt:"SmartArt layout categories in PowerPoint"}]},{heading:"Inserting SmartArt",blocks:[{type:"paragraph",text:"Go to the Insert tab and click SmartArt."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_insert_ribbon.png",alt:"SmartArt command on the Insert tab"},{type:"paragraph",text:"The Choose a SmartArt Graphic dialog opens. Select a category on the left, then pick a layout from the center panel. A preview and description appear on the right."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_choose_dialog.png",alt:"Choose a SmartArt Graphic dialog"},{type:"paragraph",text:"Click OK. The SmartArt graphic appears on your slide with placeholder text."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_inserted.png",alt:"SmartArt graphic inserted on a slide"}]},{heading:"Adding Text to SmartArt",blocks:[{type:"paragraph",text:"You can type directly into the shapes, or use the Text Pane on the left side of the graphic for easier editing."},{type:"paragraph",text:"To open the Text Pane, click the small arrow on the left edge of the SmartArt border or click Text Pane on the SmartArt Design tab."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_text_pane.png",alt:"SmartArt Text Pane open for editing"},{type:"paragraph",text:"Each bullet in the Text Pane corresponds to a shape in the graphic. Press Enter to add a new item and Tab to create a sub-level item."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_text_entered.png",alt:"SmartArt with text entered across all shapes"}]},{heading:"Adding and Removing Shapes",blocks:[{type:"paragraph",text:"SmartArt automatically sizes its shapes based on how many items you have. To add a shape, click Add Shape on the SmartArt Design tab."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_add_shape.png",alt:"Add Shape button on the SmartArt Design tab"},{type:"paragraph",text:"To remove a shape, click it in the graphic and press Delete."}]},{heading:"Changing the SmartArt Layout",blocks:[{type:"paragraph",text:"If the layout you chose doesn't quite fit your content, you can switch to a different one without retyping your text."},{type:"paragraph",text:"On the SmartArt Design tab, click a different layout in the Layouts gallery. Your content transfers to the new structure automatically."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_layout_gallery.png",alt:"SmartArt layout gallery on the Design tab"}]},{heading:"Applying SmartArt Styles and Colors",blocks:[{type:"paragraph",text:"The SmartArt Styles gallery offers pre-built visual treatments including flat, polished, and 3D looks that coordinate with your theme."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_styles_gallery.png",alt:"SmartArt Styles gallery"},{type:"paragraph",text:"Click Change Colors to choose a color variation that matches your presentation's palette."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_change_colors.png",alt:"Change Colors options for SmartArt"}]},{heading:"Converting a Bulleted List to SmartArt",blocks:[{type:"paragraph",text:"If you already have a bulleted text placeholder, you can convert it directly into SmartArt without starting over."},{type:"paragraph",text:"Select the text placeholder, right-click, and choose Convert to SmartArt. Then select a layout from the mini gallery that appears."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_convert_from_text.png",alt:"Convert to SmartArt option in the right-click menu"},{type:"tip",text:"Converting a list to SmartArt is one of the fastest ways to make a plain slide look more polished."}]},{heading:"Completed SmartArt Example",blocks:[{type:"paragraph",text:"A well-chosen SmartArt layout with consistent colors and readable text can replace several plain bullet-point slides."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_final_result.png",alt:"Completed SmartArt graphic on a slide"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which SmartArt category is most appropriate for showing the steps in a workflow?",options:["Cycle","Hierarchy","Process","Matrix"],correctIndex:2,explanation:"Process graphics show a sequence with direction, which is exactly what a workflow is. The arrows communicate order — something a bulleted list cannot do.",optionRationales:["Cycle shows a repeating loop returning to its start, which misrepresents a linear workflow.","Hierarchy shows levels of reporting or containment, as in an org chart.","Correct. Process graphics show sequential steps with direction.","Matrix shows parts of a whole arranged in quadrants."]},{type:"knowledge-check",question:"How do you add a new item to a SmartArt graphic using the Text Pane?",options:["Click Insert → Shape","Press Enter in the Text Pane to create a new bullet","Drag a shape from the Format tab","Type directly in the slide title"],correctIndex:1,explanation:"In the Text Pane, pressing Enter creates a new bullet and SmartArt adds a corresponding shape, re-laying out the whole graphic automatically.",optionRationales:["Insert > Shape adds a free shape to the slide, which is not part of the SmartArt graphic.","Correct. Enter in the Text Pane adds an item and SmartArt creates the shape for it.","Shapes cannot be dragged in from the Format tab.","The slide title is a separate placeholder and has no connection to the SmartArt."]}]}],challenge:[{type:"paragraph",text:"Open the practice presentation and complete the following tasks:"},{type:"list",ordered:!0,items:["Navigate to the slide with the bulleted list about the onboarding process.","Select the text placeholder containing the bulleted items.","Right-click and use Convert to SmartArt to turn it into a Process graphic.","Open the Text Pane and add one more step at the end.","Apply a SmartArt style that gives the shapes a polished, 3D appearance.","Use Change Colors to apply an accent color palette from your theme.","Resize the SmartArt graphic so it fills the lower portion of the slide without covering the title."]},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_final_result.png",alt:"Completed SmartArt challenge result"}]}],level:"Intermediate",estimatedMinutes:30},{moduleNumber:8,moduleSlug:"module-8",title:"Review & Presenting",emoji:"\uD83C\uDFA4",description:"Spell-check your work, collaborate with comments, deliver your presentation using Presenter View, and share or export your file.",lessons:[{slug:"checking-spelling-and-comments",title:"Checking Spelling & Using Comments",description:"Learn how to run a spell check, use the built-in thesaurus, add and review comments, and use Track Changes tools to collaborate and polish your presentation before delivery.",objectives:["Run spell check across a presentation","Add, reply to, and resolve comments","Remove comments before presenting or distributing","Proofread the things spell check cannot catch"],duration:"8 min",videoUrl:"",practiceFiles:[{name:"Review Practice File",url:"/practice/powerpoint/module-8/review/Powerpoint_Review_Practice.pptx"}],sections:[{heading:"Errors are magnified by a projector",blocks:[{type:"scenario",role:"You present to external partners at Lakeside Medical Associates.",text:"Slide four carries a typo in a heading, three inches tall on the screen. A reviewer's comment is also still attached — 'is this number even right?' — visible to the room.",task:"Clear comments and proofread properly before anything is projected."},{type:"paragraph",text:"Spell check catches misspellings and nothing else. It will not notice 'from' where you meant 'form,' a title that is wrong, or a number that contradicts the previous slide. Reading the deck through once in Reading View is what catches those, and it takes a few minutes."},{type:"callout",variant:"warning",text:"Comments are visible in Normal view and can appear in Presenter View, so a frank internal remark can end up in front of an audience or a client. Delete every comment before presenting or distributing, and run File > Info > Check for Issues > Inspect Document to confirm none remain — along with any presentation notes or metadata you would not want shared."}]},{heading:"Why Review Before You Present?",blocks:[{type:"paragraph",text:"Spelling errors and unclear slide content can undermine your credibility with an audience. A final review ensures your presentation is polished, accurate, and ready to deliver."},{type:"paragraph",text:"PowerPoint's Review tab contains all the tools you need to check spelling, look up synonyms, and collaborate with colleagues using comments."},{type:"image",src:"/images/powerpoint/module-8/review/review_tab_ribbon.png",alt:"Review tab on the PowerPoint ribbon"}]},{heading:"Running Spell Check",blocks:[{type:"paragraph",text:"PowerPoint checks spelling as you type, marking errors with a red wavy underline. You can also run a full spell check when you're ready to review everything at once."},{type:"paragraph",text:"Go to the Review tab and click Spelling. PowerPoint will scan your entire presentation and stop at each error."},{type:"image",src:"/images/powerpoint/module-8/review/review_spelling_ribbon.png",alt:"Spelling button on the Review tab"},{type:"paragraph",text:"The Spelling pane shows the flagged word along with suggested corrections. You can choose to change the word, ignore it once, or ignore all occurrences."},{type:"image",src:"/images/powerpoint/module-8/review/review_spelling_pane.png",alt:"Spelling pane with suggestions in PowerPoint"},{type:"tip",text:"Right-click any underlined word directly on the slide to see spelling suggestions without opening the full Spelling pane."}]},{heading:"Using the Thesaurus",blocks:[{type:"paragraph",text:"The Thesaurus helps you find more precise or varied word choices for your slide content."},{type:"paragraph",text:"Select a word on your slide, then click Thesaurus on the Review tab. The Thesaurus pane opens with a list of synonyms."},{type:"image",src:"/images/powerpoint/module-8/review/review_thesaurus_pane.png",alt:"Thesaurus pane showing synonyms for a selected word"},{type:"paragraph",text:"Hover over a synonym and click the arrow to insert it directly as a replacement for the selected word."}]},{heading:"Adding Comments",blocks:[{type:"paragraph",text:"Comments let you add notes to specific parts of a slide without affecting the slide content itself. This is useful for your own reminders or for collaborating with a colleague."},{type:"paragraph",text:"To add a comment, select the object or text you want to comment on, go to the Review tab, and click New Comment."},{type:"image",src:"/images/powerpoint/module-8/review/review_new_comment.png",alt:"New Comment button on the Review tab"},{type:"paragraph",text:"A comments pane opens where you can type your note. A small comment icon appears on the slide near the object you commented on."},{type:"image",src:"/images/powerpoint/module-8/review/review_comment_icon.png",alt:"Comment icon visible on a slide"}]},{heading:"Reviewing and Replying to Comments",blocks:[{type:"paragraph",text:"To read all comments in a presentation, open the Comments pane from the Review tab. Use the Previous and Next buttons to navigate between comments."},{type:"image",src:"/images/powerpoint/module-8/review/review_comments_pane.png",alt:"Comments pane showing all comments in the presentation"},{type:"paragraph",text:"You can reply to any comment by clicking inside it and typing your response. This creates a threaded conversation visible to anyone who opens the file."}]},{heading:"Resolving and Deleting Comments",blocks:[{type:"paragraph",text:"Once a comment has been addressed, you can resolve it to mark it as done without deleting it, or delete it entirely."},{type:"paragraph",text:"To delete a comment, select it in the Comments pane and click Delete on the Review tab. To delete all comments in the presentation, use the Delete All Comments in Presentation option."},{type:"image",src:"/images/powerpoint/module-8/review/review_delete_comment.png",alt:"Delete comment options on the Review tab"},{type:"callout",variant:"warning",text:"Always delete or resolve comments before delivering a presentation to a live audience. Comment icons visible on slides can distract your viewers."}]},{heading:"Comparing Presentations",blocks:[{type:"paragraph",text:"If a colleague has sent back a revised version of your file, the Compare tool lets you merge their changes into your version and review each one."},{type:"paragraph",text:"Click Compare on the Review tab, select the revised file, and PowerPoint highlights every difference between the two versions."},{type:"image",src:"/images/powerpoint/module-8/review/review_compare_ribbon.png",alt:"Compare button on the Review tab"},{type:"paragraph",text:"Use the Revisions pane to accept or reject individual changes, then click End Review when finished."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What should you do with all comments before presenting to a live audience?",options:["Print them as handouts","Convert them to footnotes","Delete or resolve them so they are not visible on slide","Move them to the Notes pane"],correctIndex:2,explanation:"Comments should be deleted or resolved before presenting so no internal remark can appear on screen or in Presenter View. Inspect Document confirms none remain.",optionRationales:["Printing internal comments as handouts distributes exactly what should not be shared.","PowerPoint has no footnotes, and converting would not remove the content anyway.","Correct. Delete or resolve comments so they cannot be seen during the presentation.","Moving comments to the Notes pane keeps them in the file, and notes are visible in Presenter View."]}]}],challenge:[{type:"paragraph",text:"Open the practice presentation and complete the following tasks:"},{type:"list",ordered:!0,items:["Run a full Spell Check from the Review tab and correct any errors found.","On slide 2, select the word in the title and use the Thesaurus to find and apply a stronger synonym.","Add a comment to slide 3 noting that the chart data needs to be updated.","Navigate to slide 4 and reply to the existing comment with a short confirmation.","Delete all comments from the presentation so it is ready to present."]}]},{slug:"presenting-your-slideshow",title:"Presenting Your Slideshow",description:"Learn how to start a slide show, navigate slides during a presentation, use Presenter View, draw on slides, and use the laser pointer to guide your audience.",objectives:["Start a slide show from the beginning or the current slide","Use Presenter View during a live presentation","Use pen, highlighter, and screen blanking","Set up a self-running presentation"],duration:"10 min",videoUrl:"",practiceFiles:[{name:"Presenting Practice File",url:"/practice/powerpoint/module-8/presenting/Powerpoint_Presenting_Practice.pptx"}],sections:[{heading:"Know the controls before you are standing up",blocks:[{type:"scenario",role:"You present at the staff meeting at Lakeside Medical Associates.",text:"Someone asks about slide 22 while you are on slide 8. You either click forward fourteen times while everyone watches, or you know that typing 22 and pressing Enter jumps straight there.",task:"Learn the handful of controls that let you respond to a room instead of fighting the software."},{type:"table",caption:"Presentation controls",columns:["Key","Does"],rows:[["F5","Starts from the beginning"],["Shift + F5","Starts from the current slide"],["Number then Enter","Jumps to that slide"],["B / W","Blanks the screen black or white"],["Ctrl + P","Pen; Ctrl+A returns to the arrow"],["Esc","Ends the show"]]},{type:"tip",text:"Shift+F5 starts from the slide you are on, which is what you want when rehearsing a single section. Restarting from slide one every time you want to check slide 30 is a surprisingly large waste of a rehearsal."}]},{heading:"Starting a Slide Show",blocks:[{type:"paragraph",text:"F5 starts from the beginning and Shift+F5 starts from the slide you are on. Shift+F5 is the one to learn: restarting from slide one every time you want to check slide 30 wastes most of a rehearsal."},{type:"list",ordered:!1,items:["From Beginning — starts the presentation from the first slide (F5).","From Current Slide — starts from whichever slide is currently selected (Shift+F5).","Custom Slide Show — presents a subset of slides in a custom order."]},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_start_options.png",alt:"Slide Show start options on the Slide Show tab"},{type:"paragraph",text:"You can also click the Slide Show view button in the lower-right corner of the PowerPoint window to start from the current slide."},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_view_button.png",alt:"Slide Show view button in the status bar"}]},{heading:"Navigating During a Presentation",blocks:[{type:"paragraph",text:"During a slide show, you can advance slides using the mouse, arrow keys, spacebar, or Page Down. Go back with the left arrow key or Page Up."},{type:"paragraph",text:"Right-click anywhere during the presentation to access a shortcut menu with navigation options, including Go to Slide, which lets you jump directly to any slide."},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_right_click_menu.png",alt:"Right-click navigation menu during a slide show"},{type:"tip",text:"Press a slide number followed by Enter to jump directly to that slide (e.g., press 5 then Enter to go to slide 5)."}]},{heading:"Using Presenter View",blocks:[{type:"paragraph",text:"Presenter View is a professional presenting mode that shows your slide on the audience's screen while you see a private view with the current slide, upcoming slide, speaker notes, and a timer."},{type:"paragraph",text:"Presenter View needs two displays — your screen and the projector — and PowerPoint decides which is which. If your notes appear on the projector and the slides on your laptop, use Display Settings during the show to swap them. Check this in the actual room before the audience arrives; it is the most common thing that goes wrong in the first thirty seconds."},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_presenter_view_toggle.png",alt:"Use Presenter View checkbox on the Slide Show tab"},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_presenter_view.png",alt:"Presenter View layout showing current slide, next slide, and speaker notes"},{type:"callout",variant:"info",text:"Presenter View requires two displays — your laptop screen and a projector or external monitor. It only works when PowerPoint detects a second screen."}]},{heading:"Speaker Notes",blocks:[{type:"paragraph",text:"Speaker notes appear in the Notes pane below each slide and are visible only to you in Presenter View. Use them to store reminders, talking points, or key statistics."},{type:"paragraph",text:"The notes pane is where the sentences you plan to say belong. Moving them off the slide is what lets you cut a slide down to the few words that benefit from being seen — the audience cannot read and listen at once, and given the choice they read."},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_notes_pane.png",alt:"Notes pane below a slide in Normal View"},{type:"paragraph",text:"You can also print speaker notes as handouts using File → Print → Notes Pages."}]},{heading:"Using the Laser Pointer",blocks:[{type:"paragraph",text:"The laser pointer is useful on a dense chart and unnecessary on a slide with four words. If you are reaching for it constantly, the slide is probably carrying too much."},{type:"paragraph",text:"Hold Ctrl and press the left mouse button to activate the laser pointer. Move the mouse to point to any area on the slide."},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_laser_pointer.png",alt:"Laser pointer active during a presentation"}]},{heading:"Drawing on Slides During a Presentation",blocks:[{type:"paragraph",text:"PowerPoint's Pen and Highlighter tools let you draw or annotate on slides during a presentation."},{type:"paragraph",text:"Right-click during the slide show, choose Pointer Options, and then select Pen or Highlighter."},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_pen_tool.png",alt:"Pointer Options menu with Pen and Highlighter options"},{type:"paragraph",text:"At the end of the show, PowerPoint asks if you want to keep your ink annotations. You can keep them on the slides or discard them."},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_keep_ink.png",alt:"Dialog asking whether to keep ink annotations"},{type:"tip",text:"Press E to erase all pen marks on the current slide during a live presentation."}]},{heading:"Hiding Slides",blocks:[{type:"paragraph",text:"Sometimes you create slides with extra content that you only want to show if an audience member asks. Hidden slides stay in the file but are skipped automatically during the normal slide show."},{type:"paragraph",text:"A hidden slide stays in the file and is skipped during the show, which makes it the right way to hold backup detail for a question you might be asked. Press its number then Enter during the presentation to jump to it, and it appears as if you had planned for the question."},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_hide_slide.png",alt:"Hide Slide option in the right-click menu"},{type:"paragraph",text:"Hidden slides are indicated with a strikethrough number in the slide panel. To jump to a hidden slide during a presentation, type its number and press Enter."}]},{heading:"Ending a Slide Show",blocks:[{type:"paragraph",text:"Two more keys are worth knowing. B blanks the screen to black and W to white — press either when discussion starts, so the slide stops competing with the conversation. Typing a slide number then Enter jumps straight there, which is how you answer a question about slide 22 without clicking through fourteen slides while everyone watches."},{type:"paragraph",text:"If you have reached the last slide, a black end screen appears. Press Escape or click the screen to exit."},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_end_of_show.png",alt:"End of slide show black screen"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What keyboard shortcut starts a slide show from the beginning?",options:["Ctrl+P","F5","Shift+F5","Ctrl+F5"],correctIndex:1,explanation:"F5 starts the slide show from the first slide. Shift+F5 starts from the slide you are currently on, which is the one to use when rehearsing a section.",optionRationales:["Ctrl+P opens the print dialog outside a show, and switches to the pen during one.","Correct. F5 starts the presentation from the beginning.","Shift+F5 starts from the current slide rather than the beginning.","Ctrl+F5 is not a PowerPoint presentation shortcut."]},{type:"knowledge-check",question:"What does Presenter View show that the audience screen does not?",options:["The slide theme","All slide animations","Speaker notes, the next slide, and a timer","The file name and save location"],correctIndex:2,explanation:"Presenter View shows your speaker notes, the next slide, and an elapsed timer on your screen, while the audience display shows only the current slide.",optionRationales:["The theme is visible to everyone — it is how the slides look.","Animations play on the audience display as designed.","Correct. Presenter View privately shows notes, the next slide, and a timer.","File details are not shown in Presenter View."]}]}],challenge:[{type:"paragraph",text:"Open the practice presentation and complete the following tasks:"},{type:"list",ordered:!0,items:["Add brief speaker notes to at least three slides.","Hide the last slide in the presentation.","Start the slide show From Beginning using F5.","Advance through the first three slides using the spacebar.","Right-click and use Go to Slide to jump directly to slide 5.","Activate the Pen tool and circle one key item on the slide.","Press E to erase your ink marks.","Press Escape to exit the slide show.","Confirm that the last slide is still hidden by checking the slide panel."]}]},{slug:"sharing-and-exporting",title:"Sharing and Exporting Presentations",description:"Learn how to share your presentation via OneDrive, export it as a PDF, create a video from your slides, and package your file for delivery on another computer.",objectives:["Export a presentation to PDF, video, and other formats","Package a presentation with its media for another machine","Share by link with appropriate permissions","Choose a distribution format based on the recipient's need"],duration:"9 min",videoUrl:"",practiceFiles:[],sections:[{heading:"Decide what the recipient needs to do with it",blocks:[{type:"scenario",role:"You distribute the orientation deck at Lakeside Medical Associates.",text:"Three audiences: new hires who need to watch it, a colleague who must update it next quarter, and a partner organization that only needs to read it. One format cannot serve all three.",task:"Match the export format to what each recipient actually needs to do."},{type:"table",caption:"Distribution formats",columns:["Recipient needs to","Send","Why"],rows:[["Watch it without you","MP4 video","Preserves animation, timing, and narration"],["Edit it",".pptx via OneDrive link","Editable, and everyone stays on one version"],["Read it","PDF","Opens anywhere and cannot be altered casually"],["Present it elsewhere","Package for CD","Bundles fonts and media into a portable folder"]]},{type:"callout",variant:"info",text:"Package Presentation for CD is badly named — it produces a folder, and CDs are long gone. What it actually does is still useful: it bundles the presentation with all linked media and embedded fonts, so the whole thing works on a machine that has neither. Copy that folder to a USB drive when you are presenting somewhere unfamiliar."}]},{heading:"Why Sharing and Exporting Matter",blocks:[{type:"paragraph",text:"A great presentation needs to reach your audience in the right format. Sometimes that means sharing a live editable file; other times you need a locked PDF or a self-contained video that can play anywhere."},{type:"paragraph",text:"Decide what the recipient needs to do before choosing the format. Watch it without you means video. Edit it means a .pptx via a link, not an attachment. Read it means PDF. Present it themselves means a PowerPoint Show or a packaged folder."}]},{heading:"Sharing via OneDrive",blocks:[{type:"paragraph",text:"The Share button in the upper-right corner of PowerPoint lets you invite people to view or edit your presentation using OneDrive."},{type:"image",src:"/images/powerpoint/module-8/sharing/sharing_share_button.png",alt:"Share button in the upper-right corner of PowerPoint"},{type:"paragraph",text:"That prompt is telling you something useful: a share link points at a file in the cloud, so a local file has nothing to link to. Emailing a copy instead creates a second version that immediately starts diverging from yours."},{type:"image",src:"/images/powerpoint/module-8/sharing/sharing_onedrive_prompt.png",alt:"Prompt to save file to OneDrive before sharing"},{type:"paragraph",text:"Enter email addresses, choose whether recipients can edit or only view, and optionally add a message before clicking Send."},{type:"image",src:"/images/powerpoint/module-8/sharing/sharing_share_pane.png",alt:"Share pane with email invitation fields"},{type:"tip",text:"Use Can View instead of Can Edit when sharing with clients or stakeholders who should not modify the presentation."}]},{heading:"Sending as an Email Attachment",blocks:[{type:"paragraph",text:"To attach the presentation directly to an email, go to File → Share → Email and choose one of the send options."},{type:"image",src:"/images/powerpoint/module-8/sharing/sharing_email_options.png",alt:"Email sharing options in Backstage view"},{type:"list",ordered:!1,items:["Send as Attachment — attaches the editable .pptx file.","Send as PDF — converts and attaches a PDF version.","Send as XPS — attaches an XPS document (similar to PDF)."]}]},{heading:"Exporting as a PDF",blocks:[{type:"paragraph",text:"A PDF version of your presentation preserves formatting exactly as you designed it and can be opened on any device without PowerPoint installed."},{type:"paragraph",text:"PDF locks the layout and fonts so the deck renders identically anywhere, which also solves the font-substitution problem — if a recipient lacks a font you used, PowerPoint silently swaps it and your text reflows. PDF drops animation, transitions, and embedded video, so it suits a deck to be read rather than watched."},{type:"image",src:"/images/powerpoint/module-8/sharing/sharing_export_pdf.png",alt:"Create PDF/XPS dialog in PowerPoint"},{type:"paragraph",text:"Click Options before publishing to control what is included — all slides, a range of slides, or hidden slides."},{type:"image",src:"/images/powerpoint/module-8/sharing/sharing_pdf_options.png",alt:"PDF options dialog showing slide range settings"},{type:"callout",variant:"info",text:"PDF is the best format to use when you need recipients to view but not edit your presentation."}]},{heading:"Creating a Video from Your Presentation",blocks:[{type:"paragraph",text:"PowerPoint can export your entire presentation — including animations and transitions — as a standalone video file that plays without PowerPoint."},{type:"paragraph",text:"Video keeps animation, timing, and any recorded narration, which makes it the right format for training people watch on their own. Rendering a long deck takes several minutes and the file is large, so produce it the day before rather than the hour of."},{type:"image",src:"/images/powerpoint/module-8/sharing/sharing_create_video.png",alt:"Create a Video export options in PowerPoint"},{type:"paragraph",text:"PowerPoint will render the video and save it as an MP4 or WMV file. This can be shared, uploaded to a website, or played at a kiosk."},{type:"tip",text:"For most purposes choose Full HD (1080p). Use Presentation HD (720p) only if file size is a concern."}]},{heading:"Packaging a Presentation for Delivery",blocks:[{type:"paragraph",text:"If you need to present on a computer that may not have PowerPoint — or if your presentation uses linked media files — use Package Presentation for CD."},{type:"paragraph",text:"Go to File → Export → Package Presentation for CD. This bundles your presentation, all linked media, and the PowerPoint Viewer into a single folder you can copy to a USB drive."},{type:"image",src:"/images/powerpoint/module-8/sharing/sharing_package_for_cd.png",alt:"Package Presentation for CD dialog"},{type:"callout",variant:"warning",text:"Despite the name, you do not need an actual CD. Copy to Folder saves everything to a location you choose, such as a USB drive or a network folder."}]},{heading:"Marking a Presentation as Final",blocks:[{type:"paragraph",text:"Mark as Final signals to recipients that the presentation is complete and discourages further editing. It sets the file to read-only and displays an information banner."},{type:"paragraph",text:"Mark as Final is advisory, not protection. It sets the file read-only and shows a notice, and any recipient can dismiss it with one click. If a deck genuinely must not be altered, send a PDF; if it must be confidential, use Encrypt with Password on the same menu and consider where the file is stored."},{type:"image",src:"/images/powerpoint/module-8/sharing/sharing_mark_as_final.png",alt:"Mark as Final option in Backstage view"},{type:"callout",variant:"warning",text:"Mark as Final is not a security feature. Any recipient can click Edit Anyway to remove the restriction and modify the file."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which export format preserves slide formatting and can be opened without PowerPoint?",options:[".pptx",".docx","PDF",".xlsx"],correctIndex:2,explanation:"PDF preserves layout and fonts exactly and opens on any device without PowerPoint. It loses animation, transitions, and embedded media, so it suits reading rather than presenting.",optionRationales:[".pptx requires PowerPoint or a compatible viewer and remains fully editable.",".docx is a Word document format and is not a presentation export.","Correct. PDF preserves formatting and opens without PowerPoint.",".xlsx is an Excel workbook format, unrelated to presentations."]},{type:"knowledge-check",question:"What is the primary purpose of Package Presentation for CD?",options:["To compress the file for email","To bundle the presentation and media into a portable folder for use on other computers","To convert the presentation to a video","To share the file on OneDrive"],correctIndex:1,explanation:"Package Presentation for CD bundles the presentation with its linked media and embedded fonts into one folder, so it plays correctly on a computer that lacks those fonts or media files.",optionRationales:["It usually increases total size, since it gathers all linked files together.","Correct. It bundles the presentation and its media into a portable folder for use on other machines.","Converting to video is a separate option under File > Export > Create a Video.","Sharing on OneDrive is done with the Share button."]}]}],challenge:[{type:"paragraph",text:"Open the practice presentation and complete the following tasks:"},{type:"list",ordered:!0,items:["Export the presentation as a PDF. Make sure only slides 1 through 5 are included.","Export the presentation as a Full HD (1080p) video with each slide set to display for 5 seconds.","Use Package Presentation for CD to copy the file to a folder on your Desktop named Presentation Package.","Open the resulting folder and confirm it contains the presentation file and any associated media.","Return to PowerPoint, go to File → Info, and Mark the presentation as Final."]}]}],level:"Intermediate",estimatedMinutes:27}]}};